function bentoIcon(n) { return '<svg class="kico" viewBox="0 0 24 24" aria-hidden="true">' + (BENTO_ICONS[n] || '') + '</svg>'; }

function renderBento(info) {
  if (!document.getElementById('bento-grid')) return;
  const name = communityProfile && communityProfile.username ? String(communityProfile.username) : '';
  bentoSetText('bh-hello', name ? t('bento.helloName', { name }) : t('bento.hello'));
  bentoSetText('today-date', bentoShortDate(new Date()) + ' · ' + t('bento.weekNo', { n: currentIsoWeekNumber() }));

  /* Ďalší tréning / prebiehajúci tréning (dlaždica "Next up ✦" / "In progress · 0:07") */
  const sess = getSession();
  const plan = getPlan(sess ? sess.planId : recommendedPlan());
  const ps = bentoPlanStats(plan);
  bentoSetText('bt-next-label', sess
    ? t('bento.inProgress', { time: formatDurationClock(sessionElapsedSeconds(sess)) })
    : t('bento.nextUp'));
  bentoSetText('bt-next-name', sess && !plan ? (sess.planName || t('pokrok.workoutFallback')) : planDisplayName(plan));
  bentoSetText('dnes-next-plan', (sess && plan
    ? t('bento.setsOf', { done: totalSetsDone(), total: planExerciseCount(plan) })
    : (plan ? bentoCountsText(ps.exercises, ps.sets) : t('dnes.nextPlan', { plan: planNameOf(recommendedPlan()) })))
    + (plan ? programWeekSuffix(plan.id) : ''));
  const startBtn = document.getElementById('btn-start-workout');
  if (startBtn) {
    startBtn.innerHTML = sess
      ? '<span id="bt-start-text">' + esc(t('bento.continue')) + '</span>' + bentoIcon('chevron')
      : bentoIcon('play') + '<span id="bt-start-text">' + esc(t('bento.start')) + '</span>';
  }
  const hintEl = document.getElementById('bt-recovery-hint');
  if (hintEl) {
    const hint = recoveryHintForToday();
    hintEl.textContent = hint || '';
    if (hint) { hintEl.title = hint; hintEl.setAttribute('aria-label', hint); } else { hintEl.removeAttribute('title'); hintEl.removeAttribute('aria-label'); }
    hintEl.hidden = !hint;
  }
  const img = document.getElementById('bt-next-img');
  const src = sess ? '' : bentoExerciseImage(plan);
  if (img) {
    if (src) { if (img.getAttribute('src') !== src) img.setAttribute('src', src); img.hidden = false; }
    else { img.removeAttribute('src'); img.hidden = true; }
  }

  /* Týždeň: "2 / 3" a sedem dní */
  bentoSetValue('week-count', info.weekCount, '/ ' + info.goal);
  const dots = document.getElementById('bt-week-dots');
  if (dots) dots.innerHTML = bentoWeekDots();
  const weekTile = document.getElementById('bt-week');
  if (weekTile) weekTile.setAttribute('aria-label', t('bento.week') + ': ' + t('dnes.weekDone', { n: info.weekCount, g: info.goal }));

  /* Séria */
  bentoSetValue('bt-streak-v', info.streak, tPluralWord('bento.weeksWord', info.streak));

  /* Level */
  const lv = levelInfo();
  bentoSetText('bt-level-l', t('bento.level', { n: lv.level }));
  bentoSetValue('bt-level-v', lv.xp, t('units.xp'));
  const bar = document.getElementById('bt-level-bar');
  if (bar) bar.style.width = Math.min(100, Math.round((lv.levelXP / lv.total) * 100)) + '%';
  bentoSetText('bt-level-line', t('bento.toNext', { xp: lv.total - lv.levelXP, n: lv.level + 1 }));

  /* Telo, najlepší výkon, jedlo */
  const weights = sortedMeasurements().filter((x) => x.weightKg !== null && x.weightKg !== undefined);
  const m = weights[weights.length - 1];
  if (m) bentoSetValue('bt-body-v', formatMeasure(m.weightKg, 'weight'), weightUnitLabel());
  else bentoSetText('bt-body-v', '—');
  const pr = personalRecords()[0];
  if (pr) bentoSetText('bt-lift-v', pr.weight + ' ' + t('units.kg'));
  else bentoSetText('bt-lift-v', '—');
  bentoSetText('bt-lift-line', pr ? recordedNameToDisplay(pr.name) : t('bento.noLift'));
  const foodOn = state.settings.foodLogEnabled === true;
  if (foodOn) bentoSetValue('bt-food-v', foodTotals(foodEntriesFor(todayISO())).kcal, t('units.kcal'));
  else bentoSetText('bt-food-v', t('bento.foodOff'));

  bentoShowChatsBadge();
  const train = document.getElementById('bt-train');
  if (train) train.hidden = !trainAvailable();
  if (!timerInterval) bentoSetText('bt-rest-line', t('bento.rest'));
  bentoRenderFriends();
}

function bentoShowChatsBadge() {
  const b = document.getElementById('bt-chats-badge');
  if (!b) return;
  const n = communityBadges.chats + communityBadges.requests;
  b.hidden = !n;
  b.textContent = n > 99 ? '99+' : String(n);
}

/* Avatary priateľov (ako v návrhu: kruhy s farebným okrajom). Bez Community dlaždica otvorí Community. */
let bentoFriendsCache = null;   // { at, rows }
let bentoFriendsLoading = false;
const BENTO_AV_COLORS = ['#E4572E', '#2E86AB', '#7A9E3B', '#A23B72', '#F18F01', '#3B8EA5', '#6C4AB6'];
function bentoAvatarHtml(r, i) {
  const url = r.avatar_path ? communityPublicUrl(communityClient(), 'avatars', r.avatar_path) : '';
  if (url) return '<span class="k-av"><img src="' + escAttr(url) + '" alt=""></span>';
  const nm = String(r.username || '?');
  return '<span class="k-av" style="--av:' + BENTO_AV_COLORS[i % BENTO_AV_COLORS.length] + '">' + esc(nm.slice(0, 1).toUpperCase()) + '</span>';
}
function bentoRenderFriends() {
  const box = document.getElementById('bt-friends-avs');
  const label = document.getElementById('bt-friends-l');
  if (!box) return;
  const ready = communityConfigured() && communityOptIn() && communityV2() && !!communityProfile;
  if (label) label.textContent = ready ? t('bento.friends') : t('bento.community');
  if (!ready) { box.innerHTML = ''; return; }
  const rows = bentoFriendsCache ? bentoFriendsCache.rows : [];
  box.innerHTML = rows.slice(0, 5).map(bentoAvatarHtml).join('')
    + (!rows.length && bentoFriendsCache ? '<span class="bt-line">' + esc(t('bento.addFriends')) + '</span>' : '');
  if (bentoFriendsLoading || (bentoFriendsCache && Date.now() - bentoFriendsCache.at < 5 * 60 * 1000)) return;
  const sb = communityClient();
  if (!sb) return;
  bentoFriendsLoading = true;
  Promise.resolve(sb.rpc('friends_list')).then((r) => {
    bentoFriendsCache = { at: Date.now(), rows: (r && !r.error && Array.isArray(r.data)) ? r.data : [] };
  }).catch(() => {
    bentoFriendsCache = { at: Date.now(), rows: [] };
  }).finally(() => {
    bentoFriendsLoading = false;
    if (activeTab === 'dnes') bentoRenderFriends();
  });
}

/* Časovač oddychu ako list (v návrhu Bento "Rest" otvára list). */
function openRestSheet() {
  document.getElementById('modal-rest').hidden = false;
  renderTimerPresets();
}
function closeRestSheet() {
  if (typeof hideCustomTimer === 'function') hideCustomTimer();
  if (presetManageMode && typeof setPresetManageMode === 'function') setPresetManageMode(false);
  document.getElementById('modal-rest').hidden = true;
  refreshUpdateBanner();
}

/* Ťuknutie na dlaždicu = otvorenie existujúcej obrazovky alebo funkcie. */
function bentoGo(where) {
  if (where === 'calendar') { openCalendarPage(); return; }
  if (where === 'motivation' || where === 'body' || where === 'food' || where === 'photos' || where === 'history') {
    pokrokReturnTab = activeTab && activeTab !== 'pokrok' ? activeTab : null;
    switchTab('pokrok'); setPokrokView(where === 'history' ? 'progress' : where); return;
  }
  if (where === 'records') {
    switchTab('pokrok'); setPokrokView('progress');
    const r = document.getElementById('records-list');
    if (r && r.scrollIntoView) r.closest('.card').scrollIntoView({ block: 'start' });
    return;
  }
  if (where === 'muscles') { openMuscles(); return; }
  if (where === 'rest') { openRestSheet(); return; }
  if (where === 'profile') { openOwnProfileSheet(activeTab); return; }
  if (where === 'chats') { openMessagesTab(); return; }
  if (where === 'friends' || where === 'top20' || where === 'compose') {
    communityMode = 'community';
    switchTab('komunita');
    if (communityV2() && communityProfile) communitySetView(where === 'top20' ? 'leaderboard' : where);
    return;
  }
  if (where === 'library') { openLibrary('browse'); return; }
  if (where === 'settings') { openSettings(); return; }
  if (where === 'goal') {
    openSettings();
    const g = document.getElementById('settings-goal-chips');
    if (g && g.scrollIntoView) g.scrollIntoView({ block: 'center' });
    return;
  }
  if (where === 'train') {
    switchTab('trening');
    if (!trainPickerOpen) trainOpenPicker();
    const box = document.getElementById('train-box');
    if (box && box.scrollIntoView) box.scrollIntoView({ block: 'start' });
  }
}

/* ---------- Bento: karta Ty (profil, cieľ, nastavenia) ---------- */
/* ---------- Ty = môj profil (v80) ----------
   Ťuknutím na Ty sa hneď otvorí môj profil: fotka, meno, @meno, bio, počty, kompaktné akcie (úroveň, cieľ,
   fotky progresu, Upraviť profil, Priatelia) a pod tým moje zverejnené príspevky (Všetko / Fotky / Text /
   Tréningy) s postupným načítaním starších. „História tréningov“ je súkromná (len táto appka, len ja) –
   tréningy z histórie sa nikdy nezverejnia ani nemiešajú s príspevkami. Príspevky sa len čítajú zo servera
   (community_feed, rovnaké pravidlá viditeľnosti) a držia sa iba v pamäti. */
let tyFilter = 'all';            // all | photos | text | workouts | history
let tyFeed = null;               // { uid, items, extra, done, loading, error, card, ach }
let tyLoadedAt = 0;
let tyReturn = null;             // { y, filter } – návrat z príspevku / listu na rovnaké miesto
let tyHistoryShown = 20;
let tyObserver = null;
const TY_FILTERS = ['all', 'photos', 'text', 'workouts', 'history'];

function tyState() {
  if (!communityConfigured()) return 'unavailable';
  if (!communityOptIn()) return 'off';
  if (communityProfile && communityV2()) return 'ready';
  if (tyFeed && tyFeed.signedOut) return 'signedout';
  if (tyFeed && tyFeed.legacy && communitySocial !== null) return 'unavailable';
  return 'loading';
}
function tyKind(p) { return p.share ? 'workouts' : (p.photos && p.photos.length ? 'photos' : 'text'); }

function renderTy() {
  const st = tyState();
  const ready = st === 'ready';
  const p = communityProfile;
  const lv = levelInfo();
  const name = ready && p.username ? String(p.username) : t('tab.ty');
  /* lišta: meno ako na Instagrame; nastavenia vždy, ⋯ a Nový príspevok len s Community */
  bentoSetText('ty-title', t('tab.ty'));
  const el = (id) => document.getElementById(id);
  el('ty-compose').hidden = !ready;
  el('ty-more').hidden = !ready;
  if (!ready) { el('ty-menu').hidden = true; el('ty-more').setAttribute('aria-expanded', 'false'); }
  /* avatar: skutočná fotka profilu, inak písmeno */
  const av = el('ty-av');
  const avUrl = ready && p.avatar_path ? communityPublicUrl(communityClient(), 'avatars', p.avatar_path) : '';
  if (avUrl) { const img = av.querySelector('img'); if (!img || img.getAttribute('src') !== avUrl) av.innerHTML = '<img src="' + escAttr(avUrl) + '" alt="">'; }
  else av.textContent = name.slice(0, 1).toUpperCase();
  bentoSetText('ty-name', name);
  bentoSetText('ty-handle', ready && p.username ? '@' + p.username : '');
  bentoSetText('motivation-text', ready && p.bio ? String(p.bio) : motivationText());
  el('motivation-text').classList.toggle('ty-bio-real', !!(ready && p.bio));
  /* počty: Community (príspevky, sledovatelia, sledovaní, priatelia) alebo z tohto zariadenia */
  const card = ready && tyFeed && tyFeed.uid === p.id ? tyFeed.card : null;
  const stat = (n, label, attrs) => '<' + (attrs ? 'button type="button" ' + attrs : 'span') + ' class="cstat">'
    + '<span class="cstat-n">' + (Number(n) || 0) + '</span><span class="cstat-l">' + esc(label) + '</span></' + (attrs ? 'button' : 'span') + '>';
  const hist = state.history || [];
  el('ty-stats').innerHTML = ready
    ? stat(card ? card.posts : '–', t('community2.statPosts'), 'data-ty-stat="posts"')
      + stat(card ? card.followers : '–', t('community2.statFollowers'), 'data-ty-stat="followers"')
      + stat(card ? card.following : '–', t('community2.statFollowing'), 'data-ty-stat="following"')
      + stat(card ? card.friends : '–', t('community2.statFriends'), 'data-ty-stat="friends"')
    : stat(hist.length, tPluralWord('bento.workoutsWord', hist.length)) + stat(computeStreak(), t('ty.streak')) + stat(Object.keys(state.achievements || {}).length, t('ty.achievements'));
  if (ready && !card) el('ty-stats').querySelectorAll('.cstat-n').forEach((x) => { x.textContent = '–'; });
  /* kompaktné akcie */
  bentoSetText('ty-level-line', t('bento.levelLower', { n: lv.level }).replace(/^./, (c) => c.toUpperCase()) + ' · ' + lv.xp + ' ' + t('units.xp'));
  bentoSetText('ty-goal-line', tPlural('bento.goalLine', weeklyGoal()).replace('{n}', String(weeklyGoal())));
  const prof = el('ty-profile');
  prof.textContent = ready ? t('community2.editProfile') : t('community.title');
  prof.dataset.tyAction = ready ? 'edit' : 'community';
  const fr = el('ty-friends');
  fr.hidden = !ready;
  const reqs = communityBadges.requests;
  fr.innerHTML = esc(t('community2.friendsTitle')) + (reqs ? ' <span class="cnav-badge cbadge-inline">' + reqs + '</span>' : '');
  fr.dataset.tyAction = 'friends';
  renderTyMenu();
  renderTyFilters();
  renderTyPosts();
}
function renderTyMenu() {
  const menu = document.getElementById('ty-menu');
  if (!menu) return;
  const mod = communityProfile && communityProfile.role === 'moderator';
  menu.innerHTML = [
    pfMenuItem('data-ty-action="edit"', t('pf.settings')),
    pfMenuItem('data-ty-action="myposts"', t('community.tabMyPosts')),
  ].concat(mod ? [pfMenuItem('data-ty-action="moderate"', t('community.tabModerate'))] : [])
    .concat([pfMenuItem('data-ty-action="signout"', t('community.signOut'), true)]).join('');
}
function renderTyFilters() {
  const box = document.getElementById('ty-seg');
  if (!box) return;
  const ready = tyState() === 'ready';
  if (!ready && tyFilter !== 'history') tyFilter = 'history';
  const list = ready ? TY_FILTERS : ['history'];
  const label = { all: 'ty.all', photos: 'ty.pics', text: 'ty.text', workouts: 'ty.workouts', history: 'ty.history' };
  box.innerHTML = list.map((f) => '<button type="button" role="tab" class="ty-filter' + (f === tyFilter ? ' on' : '') + (f === 'history' ? ' ty-filter-private' : '') + '" data-ty-filter="' + f + '" aria-selected="' + (f === tyFilter ? 'true' : 'false') + '" tabindex="' + (f === tyFilter ? '0' : '-1') + '">'
    + (f === 'history' ? '<svg class="kico" viewBox="0 0 24 24" aria-hidden="true"><rect x="5" y="10.5" width="14" height="10" rx="2.5"/><path d="M8.5 10.5V8a3.5 3.5 0 0 1 7 0v2.5"/></svg>' : '')
    + esc(t(label[f])) + '</button>').join('');
  const priv = document.getElementById('ty-private');
  priv.hidden = tyFilter !== 'history';
  priv.textContent = t('ty.historyPrivate');
}
/* Kartička stavu namiesto propagačnej dlaždice: Community vypnutá / odhlásený / offline / chyba. */
function tyNoticeHtml(st) {
  const f = tyFeed || {};
  let key = null, btn = null;
  if (st === 'off') { key = 'ty.offLine'; btn = 'community.title'; }
  else if (st === 'signedout') { key = 'ty.signedOutLine'; btn = 'community.signIn'; }
  else if (st === 'unavailable') key = 'ty.unavailableLine';
  else if (st === 'ready' && f.error && !(f.items || []).length) key = navigator.onLine === false ? 'ty.offlineLine' : 'ty.errorLine';
  if (!key) return '';
  return '<div class="ty-note"><span>' + esc(t(key)) + '</span>'
    + (btn ? '<button type="button" class="btn btn-secondary btn-sm" data-ty-action="community">' + esc(t(btn)) + '</button>' : '') + '</div>';
}
function tyTimeLabel(iso) { return communityTimeAgo(iso); }
function tyTextCardHtml(p) {
  const repost = p.reposted_by && communityProfile && p.user_id !== communityProfile.id;
  return '<button type="button" class="ty-card ty-text" data-ty-post="' + escAttr(p.id) + '">'
    + '<span class="ty-meta">' + (repost ? communityIcon('share') + esc(t('ty.repostOf', { name: p.name || '' })) + ' · ' : '') + esc(tyTimeLabel(p.published))
    + (p.visibility === 'friends' ? ' · ' + esc(t('community2.friendsOnly')) : '') + '</span>'
    + '<span class="ty-body">' + esc(p.caption) + '</span>'
    + '<span class="ty-counts-row">' + communityIcon('heart') + p.likes + ' ' + communityIcon('chat') + (p.comments || 0) + '</span></button>';
}
function tyWorkoutCardHtml(p) {
  const a = p.share || {};
  const workout = a.kind === 'workout';
  const meta = [];
  if (workout && a.date) meta.push(formatDate(String(a.date)));
  if (workout && Number(a.duration) > 0) meta.push(formatDurationNatural(Number(a.duration)));
  if (workout && Number(a.xp) > 0) meta.push({ html: '<bdi>+' + Number(a.xp) + ' ' + esc(t('units.xp')) + '</bdi>' });   // bdi: v arabčine sa "+50 XP" nepreskladá
  if (Array.isArray(a.exercises)) meta.push(tPlural('share.exercises', a.exercises.length));
  const ph = p.photos && p.photos[0];
  const url = ph && p.urls ? p.urls[ph.thumb] : '';
  const ex = Array.isArray(a.exercises) ? a.exercises.slice(0, 3).map((e) => esc(e && (e.id && BUILTIN_EXERCISE_IDS.has(e.id) ? t('exercise.' + e.id) : (e.n || e.name || '')))).filter(Boolean).join(' · ') : '';
  return '<button type="button" class="ty-card ty-workout ' + (workout ? 'ty-w-done' : 'ty-w-plan') + '" data-ty-post="' + escAttr(p.id) + '">'
    + '<span class="ty-w-icon" aria-hidden="true">' + PF_GLYPHS[workout ? 'check' : 'dumbbell'] + '</span>'
    + '<span class="ty-w-main"><span class="ty-meta">' + esc(t(workout ? 'share.kindWorkout' : 'share.kindPlan')) + ' · ' + esc(tyTimeLabel(p.published)) + '</span>'
    + '<b class="ty-w-name">' + esc(a.name || '') + '</b>'
    + '<span class="ty-w-sub">' + meta.map((m) => (m && m.html) || esc(m)).join(' · ') + '</span>'
    + (ex ? '<span class="ty-w-ex">' + ex + '</span>' : '')
    + (p.caption ? '<span class="ty-body ty-body-sm">' + esc(p.caption) + '</span>' : '') + '</span>'
    + (url ? '<span class="ty-w-thumb"><img loading="lazy" decoding="async" src="' + escAttr(url) + '" alt=""></span>' : '') + '</button>';
}
function tyPhotoTileHtml(p) {
  const ph = p.photos[0];
  const url = p.urls ? p.urls[ph.thumb] : '';
  const n = p.photos.length;
  const repost = p.reposted_by && communityProfile && p.user_id !== communityProfile.id;
  const label = (repost ? t('ty.repostOf', { name: p.name || '' }) + ' · ' : '') + (p.caption || t('ty.photoOnly')) + ' · ' + tyTimeLabel(p.published);
  return '<button type="button" class="ty-photo" data-ty-post="' + escAttr(p.id) + '" aria-label="' + escAttr(label) + '">'
    + (url ? '<img loading="lazy" decoding="async" src="' + escAttr(url) + '" alt="">' : '')
    + ((n > 1 || repost) ? '<span class="pf-marks">' + (n > 1 ? '<span class="pf-mark pf-count">' + n + '</span>' : '') + (repost ? '<span class="pf-mark">' + communityIcon('share') + '</span>' : '') + '</span>' : '')
    + '</button>';
}
function tyPendingHtml(r) {
  const ph = (r.photos || [])[0];
  const url = ph && r.urls ? r.urls[ph.thumb] : '';
  const status = t('community.status' + r.status.charAt(0).toUpperCase() + r.status.slice(1));
  return '<button type="button" class="ty-card ty-pending ty-' + escAttr(r.status) + '" data-ty-action="myposts">'
    + '<span class="ty-w-main"><span class="ty-meta"><span class="ty-status">' + esc(status) + '</span> · ' + esc(t('ty.onlyYou')) + '</span>'
    + '<span class="ty-body ty-body-sm">' + esc(r.caption || t('ty.photoOnly')) + '</span></span>'
    + (url ? '<span class="ty-w-thumb"><img loading="lazy" decoding="async" src="' + escAttr(url) + '" alt=""></span>' : '') + '</button>';
}
/* Všetko: poradie od najnovšieho; po sebe idúce fotky v riadkoch po 3, text a tréningy ako celé karty. */
function tyMixedHtml(items) {
  let html = '', row = [];
  /* 1 fotka = široká dlaždica, 2 = polovice, 3 = tretiny (mozaika Bento, poradie ostáva) */
  const flush = () => { if (row.length) html += '<div class="ty-photos ty-mosaic" data-n="' + row.length + '">' + row.join('') + '</div>'; row = []; };
  items.forEach((p) => {
    const k = tyKind(p);
    if (k === 'photos') { row.push(tyPhotoTileHtml(p)); if (row.length === 3) flush(); }
    else { flush(); html += k === 'workouts' ? tyWorkoutCardHtml(p) : tyTextCardHtml(p); }
  });
  flush();
  return html;
}
function tyHistoryHtml() {
  const hist = (state.history || []).slice().sort((a, b) => (a.date < b.date ? 1 : a.date > b.date ? -1 : 0));
  if (!hist.length) return '<p class="empty-state ty-empty">' + esc(t('ty.historyEmpty')) + '</p>';
  const shown = hist.slice(0, tyHistoryShown);
  return '<div class="ty-history">' + shown.map((w) => '<button type="button" class="ty-card ty-hist" data-ty-day="' + escAttr(w.date) + '">'
    + '<span class="ty-hist-date"><b>' + esc(String(parseDate(w.date).getDate())) + '</b><span>' + esc(localeData().monthsShort ? localeData().monthsShort[parseDate(w.date).getMonth()] : '') + '</span></span>'
    + '<span class="ty-w-main"><b class="ty-w-name">' + esc(historyPlanName(w)) + '</b>'
    + '<span class="ty-w-sub">' + esc(formatDate(w.date)) + ' · ' + esc(tPlural('bento.setCount', historySets(w)).replace('{n}', String(historySets(w)))) + ' · ' + bentoWorkoutLine(w) + '</span></span></button>').join('')
    + '</div>' + (hist.length > tyHistoryShown ? '<button type="button" class="btn btn-secondary btn-block ty-more-btn" data-ty-action="history-more">' + esc(t('community.loadMore')) + '</button>' : '');
}
function renderTyPosts() {
  const box = document.getElementById('ty-posts');
  if (!box) return;
  const st = tyState();
  if (tyFilter === 'history') { box.innerHTML = tyNoticeHtml(st) + tyHistoryHtml(); return; }
  const f = tyFeed;
  if (st !== 'ready' || !f || f.uid !== communityProfile.id) {
    box.innerHTML = tyNoticeHtml(st) || '<p class="ty-loading">' + esc(t('community.loading')) + '</p>';
    return;
  }
  const items = tyFilter === 'all' ? f.items : f.items.filter((p) => tyKind(p) === tyFilter);
  let html = tyNoticeHtml(st);
  if (tyFilter === 'all' && f.extra.length) html += '<div class="ty-pend">' + f.extra.map(tyPendingHtml).join('') + '</div>';
  if (tyFilter === 'photos') html += items.length ? '<div class="ty-photos">' + items.map(tyPhotoTileHtml).join('') + '</div>' : '';
  else if (tyFilter === 'text') html += items.map(tyTextCardHtml).join('');
  else if (tyFilter === 'workouts') html += items.map(tyWorkoutCardHtml).join('');
  else html += tyMixedHtml(items);
  if (!items.length && !(tyFilter === 'all' && f.extra.length) && f.done && !f.error) {
    html += '<div class="ty-empty"><p class="empty-state">' + esc(t(tyFilter === 'all' ? 'ty.noPosts' : 'ty.noneOfKind')) + '</p>'
      + (tyFilter === 'all' ? '<button type="button" class="btn btn-primary btn-sm" data-go="compose">' + esc(t('community.newPost')) + '</button>' : '') + '</div>';
  }
  if (f.loading) html += '<p class="ty-loading">' + esc(t('community.loading')) + '</p>';
  else if (!f.done) html += '<button type="button" class="btn btn-secondary btn-block ty-more-btn" data-ty-action="more">' + esc(t('community.loadMore')) + '</button>';
  box.innerHTML = html;
  tyWatchSentinel();
}
/* Načítanie: hlavička (profile_card), čakajúce vlastné príspevky a prvá strana; ďalšie strany kurzorom. */
async function tyLoad(force) {
  if (!communityConfigured() || !communityOptIn()) { renderTy(); return; }
  const sb = communityClient(); if (!sb) return;
  let session = null;
  try { const r = await sb.auth.getSession(); session = r && r.data ? r.data.session : null; } catch (e) {}
  if (!session) { tyFeed = { signedOut: true, items: [], extra: [] }; renderTy(); return; }
  if (!communityProfile || communityProfile.id !== session.user.id || communitySocial === null) {
    try { await communityEnsureProfile(sb, session.user); await communityDetectSocial(sb); } catch (e) {}
  }
  if (!communityProfile || !communityV2()) { tyFeed = { legacy: true, items: [], extra: [] }; renderTy(); return; }
  const uid = communityProfile.id;
  if (!force && tyFeed && tyFeed.uid === uid && Date.now() - tyLoadedAt < 60000) { renderTy(); return; }
  const feed = { uid, items: [], extra: [], done: false, loading: true, error: false, card: tyFeed && tyFeed.uid === uid ? tyFeed.card : null };
  if (!(tyFeed && tyFeed.uid === uid && tyFeed.items.length)) { tyFeed = feed; renderTy(); }
  let res, card, pend;
  try {
    [res, card, pend] = await Promise.all([
      sb.rpc('community_feed', { p_scope: 'user', p_user: uid, p_before: null, p_before_id: null, p_limit: COMMUNITY_PAGE }),
      communityProfileCard(sb, uid),
      Promise.resolve(sb.from('posts').select('id,status,caption,image_path,thumb_path,created_at').eq('user_id', uid).neq('status', 'approved').order('created_at', { ascending: false }).limit(30)).catch((e) => ({ error: e }))
    ]);
  } catch (e) { res = { error: e }; }
  feed.loading = false;
  if (!res || res.error) { feed.error = true; if (tyFeed && tyFeed.uid === uid && tyFeed.items.length) { tyFeed.error = true; renderTy(); return; } tyFeed = feed; renderTy(); return; }
  feed.items = await communityFeedItemsFromRows(sb, res.data || []);
  feed.done = (res.data || []).length < COMMUNITY_PAGE;
  feed.card = card || feed.card;
  const rows = pend && !pend.error ? (pend.data || []) : [];
  if (rows.length) {
    const photos = await communityPostPhotos(sb, rows);
    const urls = await communitySignedUrls(sb, [].concat(...Object.values(photos).map((l) => l.map((ph) => ph.thumb))));
    feed.extra = rows.map((r) => Object.assign({}, r, { photos: photos[r.id] || [], urls }));
  }
  if (!communityProfile || communityProfile.id !== uid) return;
  tyFeed = feed;
  tyLoadedAt = Date.now();
  renderTy();
}
async function tyLoadMore() {
  const f = tyFeed;
  if (!f || f.loading || f.done || !f.uid || tourOpen()) return;   // návod beží: žiadne stránkovanie (ani z už naplánovaného volania)
  const sb = communityClient(); if (!sb) return;
  const last = f.items[f.items.length - 1];
  f.loading = true;
  renderTyPosts();
  let res;
  try {
    res = await sb.rpc('community_feed', { p_scope: 'user', p_user: f.uid, p_before: last ? last.at : null, p_before_id: last ? last.id : null, p_limit: COMMUNITY_PAGE });
  } catch (e) { res = { error: e }; }
  f.loading = false;
  if (res.error) { f.error = true; renderTyPosts(); return; }
  const add = await communityFeedItemsFromRows(sb, res.data || []);
  const seen = new Set(f.items.map((p) => p.id + '|' + (p.reposted_by || '')));   // nikdy dvakrát to isté
  add.forEach((p) => { const k = p.id + '|' + (p.reposted_by || ''); if (!seen.has(k)) { seen.add(k); f.items.push(p); } });
  f.done = (res.data || []).length < COMMUNITY_PAGE;
  f.error = false;
  if (tyFeed === f) renderTyPosts();
}
/* Staršie príspevky sa načítajú samy, keď sa pri posúvaní priblížiš ku koncu (a pri filtri, kým je čo ukázať). */
function tyWatchSentinel() {
  const s = document.getElementById('ty-sentinel');
  if (!s || typeof IntersectionObserver !== 'function') return;
  if (!tyObserver) {
    tyObserver = new IntersectionObserver((entries) => {
      if (tourSuppressed() || activeTab !== 'ty' || tyFilter === 'history') return;   // aj chvíľu po zatvorení návodu: znovu zobrazená obrazovka spustí observer
      if (entries.some((e) => e.isIntersecting)) tyLoadMore();
    }, { rootMargin: '600px 0px' });
    tyObserver.observe(s);
  }
  if (activeTab === 'ty' && !tourSuppressed() && tyFilter !== 'history' && tyFeed && !tyFeed.done && !tyFeed.loading) {
    const r = s.getBoundingClientRect();
    if (r.top < innerHeight + 600) setTimeout(tyLoadMore, 0);
  }
}
/* Príspevok, zoznam či úprava profilu sa otvoria ako list Community; Späť vráti na Ty na rovnaké miesto. */
function tyOpenSheet(view, apply) {
  tyReturn = { y: window.scrollY || 0, filter: tyFilter };
  communityMode = 'community';
  communityBack = [];
  communityReturnTab = 'ty';
  if (apply) apply();
  communityView = view;
  communitySetMessage('');
  switchTab('komunita');
}
function tyOpenPost(id) {
  const f = tyFeed;
  if (!f) return;
  tyOpenSheet('comments', () => {
    communityPostId = id;
    communityFeed = { items: f.items, offset: 0, done: f.done, loading: false, scope: 'user', user: f.uid, grid: true, own: true, extra: [] };
  });
}
function tyAction(act) {
  const me = communityProfile && communityProfile.id;
  if (act === 'edit') tyOpenSheet('editprofile');
  else if (act === 'friends') tyOpenSheet('friends');
  else if (act === 'myposts') openOwnPostsSheet('ty');
  else if (act === 'moderate') tyOpenSheet('moderate');
  else if (act === 'signout') { tyMenu(false); requestSignOut(); }
  else if (act === 'community') { communityMode = 'community'; communityBack = []; communityReturnTab = null; communityView = 'feed'; switchTab('komunita'); }
  else if (act === 'more') tyLoadMore();
  else if (act === 'history-more') { tyHistoryShown += 20; renderTyPosts(); }
  else if ((act === 'followers' || act === 'following') && me) tyOpenSheet('list', () => { communityListKind = act; communityViewUser = me; });
}
function tyMenu(open) {
  const m = document.getElementById('ty-menu'), b = document.getElementById('ty-more');
  if (!m || !b) return;
  m.hidden = !open;
  b.setAttribute('aria-expanded', open ? 'true' : 'false');
  if (open) { const f = m.querySelector('button'); if (f) f.focus(); }
}
function tySetFilter(f) {
  if (TY_FILTERS.indexOf(f) < 0) return;
  tyFilter = f;
  renderTyFilters();
  renderTyPosts();
}
/* Otvorenie listu Community s návratom na kartu, odkiaľ prišiel (Ty, Dnes …). */
function openOwnPostsSheet(returnTab) {
  if (returnTab === 'ty') tyReturn = { y: window.scrollY || 0, filter: tyFilter };
  communityMode = 'community';
  communityBack = [];
  communityView = 'myposts';
  communityReturnTab = returnTab || null;
  if (communityV2() && communityProfile) communitySheetSkeleton(t('community.tabMyPosts'));
  switchTab('komunita');
}

/* Kalendár: celostránkový list (ako v návrhu), Späť vráti na kartu, odkiaľ sa otvoril. */
let calendarReturnTab = 'dnes';
function openCalendarPage() {
  if (activeTab !== 'kalendar') calendarReturnTab = activeTab || 'dnes';
  switchTab('kalendar');
  window.scrollTo(0, 0);
}

/* ---------- Vykreslenie: TRÉNING ---------- */

/* ---------- Aktívna tréningová session (jediný zdroj pravdy pre rozbehnutý tréning) ----------
   Priebeh tréningu NIKDY nežije len v prekreslenom DOM. Žije v state.activeSession, ktorý
   prežije prekreslenie, zmenu jazyka, prepnutie karty, úpravu plánu aj obnovenie stránky. */

/* Plán rozbehnutého tréningu: pri rozbehnutej session je to vždy jej plán (aj rýchly tréning),
   inak vybraný plán. Nič iné nesmie počas tréningu prepísať, ktorý plán sa zobrazuje a ukladá. */
function currentPlan() {
  const sess = getSession();
  return (sess && (sess.programPlan || getPlan(sess.planId))) || getPlan(selectedPlan);
}
/* Rozbehnutá session drží výber plánu (nikdy ho neprepíše odporúčaný ani iný plán). */
function keepSessionPlan() {
  const sess = getSession();
  if (sess && (sess.programPlan || getPlan(sess.planId))) { selectedPlan = sess.planId; return true; }
  return false;
}

function getSession() {
  return (state && state.activeSession) || null;
}

/* Stabilný kľúč cviku v rámci session. Používa stabilné id zabudovaného cviku, inak názov.
   Zobrazený názov sa pri prepnutí SK/EN prekladá, ale uložený názov cviku sa nemení,
   takže značky prežijú zmenu jazyka, váhy aj poradia cvikov v pláne.
   `sessionKey` nesie náhrada cviku počas tréningu, krok zmeny nastavení a každé ďalšie opakovanie toho istého riadku
   plánu (`kľúč~dupN`, viď exerciseSlots) – vďaka tomu sa nikdy nezrazia značky dvoch rôznych slotov. */
function exerciseSessionKey(ex) {
  if (!ex) return '';
  if (ex.sessionKey) return String(ex.sessionKey);
  /* Vlastný cvik nesie od v100 odvodenú identitu cx-<hash názvu>, no kľúč session zostáva
     'c:'+názov, aby značky rozbehnutého tréningu prežili aktualizáciu. Ručne daná cx-… hodnota
     (iná než odvodená) sa ako kľúč používa naďalej. */
  if (ex.id && (BUILTIN_EXERCISE_IDS.has(ex.id) || (String(ex.id).indexOf('cx-') === 0 && ex.id !== exerciseIdentity(ex)))) return String(ex.id);
  return 'c:' + String(ex.name == null ? '' : ex.name);
}

/* Kľúč jednej série. Jednostranný cvik má pre každú stranu vlastný kľúč,
   takže ľavá a pravá strana sa nikdy nemôžu označiť navzájom. */
function setSessionKey(ex, index, side) {
  const base = exerciseSessionKey(ex) + ':' + index;
  return side ? base + ':' + (side === 'right' ? 'R' : 'L') : base;
}

/* Poradie strán jednostranného cviku; null pre bežný (obojstranný) cvik. */
function exerciseSideOrder(ex) {
  if (!ex || ex.unilateral !== true) return null;
  return ex.startSide === 'right' ? ['right', 'left'] : ['left', 'right'];
}

/* Koľko samostatne označiteľných položiek cvik má (každá strana = jedna). */
function exerciseSlotCount(ex) {
  return ex.sets * (exerciseSideOrder(ex) ? 2 : 1);
}

/* Dočasný strop počtu sérií jedného cviku: pri zápise segmentu uzavretého zmenou nastavení do histórie
   sa zapíše len práca po poslednú hotovú sériu (zvyšok prevzal nasledovník). { key, n } alebo null. */
let sessionSetCountCap = null;

/* Počet sérií cviku v rozbehnutom tréningu = plánované série + zmena v session
   (sess.setDelta[kľúč cviku], môže byť záporná; výsledok je aspoň 1, najviac 99).
   Chýbajúce pole (staršia session) = 0. Plán sa nikdy nemení. Bez session platí plán. */
function sessionSetCount(ex) {
  const snap = sessionSnapshotFor(ex);
  const planned = Math.max(0, Math.round(Number(snap && snap.sets !== undefined ? snap.sets : ex && ex.sets)) || 0);
  const sess = getSession();
  const d = sess && sess.setDelta && typeof sess.setDelta === 'object' ? Number(sess.setDelta[exerciseSessionKey(ex)]) : 0;
  const n = Math.min(99, Math.max(1, planned + (Number.isInteger(d) ? d : 0)));
  return sessionSetCountCap && sessionSetCountCap.key === exerciseSessionKey(ex) ? Math.min(n, sessionSetCountCap.n) : n;
}

/* Ako exerciseSlotCount, ale s počtom sérií z tréningu (použiť len pri cvikoch aktuálnej session,
   nie pri záznamoch z histórie). */
function sessionSlotCount(ex) {
  return sessionSetCount(ex) * (exerciseSideOrder(ex) ? 2 : 1);
}

/* ---------- Výmena cviku počas tréningu (session, NIE plán) ----------
   Výmena nikdy nezmení plán používateľa – zajtra ho čaká pôvodný cvik.
   Žije v state.activeSession.substituted, takže prežije prekreslenie, zmenu
   jazyka aj obnovenie stránky rovnako ako ostatné značky. */

/* Plánový cvik s hodnotami zo snímky session; predpísané série a opakovania sa nemenia úpravou plánu.
   Staršia session bez nových polí si ponechá pôvodné správanie. */
function sessionSnapshotExercise(ex, snap) {
  if (!snap) return ex;
  const out = Object.assign({}, ex, { weight: snap.weight });
  if (snap.sets !== undefined) out.sets = snap.sets;
  if (snap.reps !== undefined) out.reps = snap.reps;
  Object.defineProperty(out, '_sessionSnapshot', { value: snap });
  delete out.unilateral; delete out.startSide; delete out.assisted;
  if (snap.unilateral === true) { out.unilateral = true; out.startSide = snap.startSide === 'right' ? 'right' : 'left'; }
  if (snap.assisted === true) out.assisted = true;
  const muscles = cleanExerciseMuscles(snap.muscles);
  if (muscles) out.muscles = muscles;
  delete out.musclesAuto;
  if (muscles && muscles.primary === 'other' && typeof snap.musclesAuto === 'boolean') out.musclesAuto = snap.musclesAuto;
  return out;
}

/* Kópia slotu nesie snímku priamo; pôvodný riadok plánu ju nájde podľa poradia duplicity.
   Náhrady ani pridané cviky nesmú zdediť predpis iného slotu. */
function sessionSnapshotFor(ex) {
  const sess = getSession();
  if (!sess || !sess.snapshot || !ex) return null;
  if (ex._sessionSnapshot) return ex._sessionSnapshot;
  const plan = currentPlan();
  let rows = plan && plan.exercises;
  if (sess.programPlan && (!rows || !rows.includes(ex))) {
    const live = getPlan(sess.planId);
    rows = live && live.exercises;
  }
  if (!Array.isArray(rows)) return null;
  const index = rows.indexOf(ex);
  if (index < 0) return null;
  const key = exerciseSessionKey(ex);
  let occ = 0;
  for (let i = 0; i < index; i++) if (exerciseSessionKey(rows[i]) === key) occ++;
  return sess.snapshot[key + '#' + occ] || null;
}

/* Slot = jeden riadok tréningu aj s poradím opakovania (rovnaký cvik dvakrát v pláne): `base#occ`.
   Cviky tréningu = riadky plánu + cviky pridané počas tréningu (sess.extraExercises); plán sa nikdy nemení,
   rýchly tréning nesie svoje cviky priamo v plánovom pohľade. Snímka je po slotoch (kľúč#poradie), takže zdvojený
   cvik v pláne (napr. 60 kg a 80 kg) drží každý riadok osobitne.
   Každé ďalšie opakovanie (occ > 0) dostane aj vlastný kľúč sledovania (kópia riadku so `sessionKey` `base~dupN`):
   značky, hodnoty, zámky, rozcvičky, dropy aj počty sérií duplicít sú tak nezávislé. Prvé opakovanie si ponecháva
   pôvodný kľúč cviku, takže staršie značky, ktoré zdieľali obe opakovania, ostanú práve raz na prvom z nich a nikdy
   sa nerozmnožia. Kľúč sa odvodzuje z poradia riadku, preto prežije aj obnovenie stránky. */
function exerciseSlots(plan) {
  const sess = getSession();
  let rows = plan && Array.isArray(plan.exercises) ? plan.exercises : [];
  if (sess && sess.programPlan && plan && plan.id === sess.planId) rows = sess.programPlan.exercises;
  const extra = sess && Array.isArray(sess.extraExercises) ? sess.extraExercises : [];
  const seen = {};
  return rows.concat(extra).map((src, i) => {
    const base = exerciseSessionKey(src);
    const occ = seen[base] || 0;
    seen[base] = occ + 1;
    let ex = src;
    if (sess && sess.snapshot && i < rows.length) ex = sessionSnapshotExercise(src, sess.snapshot[base + '#' + occ]);
    if (sess && occ > 0) {
      if (ex === src) ex = Object.assign({}, src);
      ex.sessionKey = base + SESSION_DUP_TAG + occ;
    }
    return { ex, base, occ, slot: base + '#' + occ };
  });
}

function sessionExercises(plan) {
  return exerciseSlots(plan).map((slot) => slot.ex);
}

/* Kľúč cviku bez značky opakovania (meno bezprizorného kľúča rozcvičiek). */
function sessionPlainKey(key) {
  const at = key.lastIndexOf(SESSION_DUP_TAG);
  return at > 0 && /^\d+$/.test(key.slice(at + SESSION_DUP_TAG.length)) ? key.slice(0, at) : key;
}

/* Existuje pre tento cvik v pláne iba jeden slot? Pri duplicite sa výmena odmietne,
   aby sa nikdy nezamenili dve rôzne série. */
function slotIsUnique(plan, base) {
  return exerciseSlots(plan).filter((s) => s.base === base).length === 1;
}

function substitutionMap() {
  const sess = getSession();
  const map = sess && sess.substituted;
  return (map && typeof map === 'object' && !Array.isArray(map)) ? map : {};
}

function substitutionSteps(slot) {
  const list = substitutionMap()[slot];
  return Array.isArray(list) ? list : [];
}

function hasSubstitutions() {
  return Object.keys(substitutionMap()).length > 0;
}

/* Počet označených sérií ľubovoľného cviku (plánového aj náhrady). */
function countDoneSets(ex) {
  const sess = getSession();
  if (!sess || !ex) return 0;
  const sides = exerciseSideOrder(ex);
  let n = 0;
  for (let i = 0; i < sessionSetCount(ex); i++) {
    if (sides) {
      for (const side of sides) if (sess.completedSets[setSessionKey(ex, i, side)]) n++;
    } else if (sess.completedSets[setSessionKey(ex, i)]) n++;
  }
  return n;
}

/* Segmenty jedného slotu: pôvodný cvik (ak na ňom niečo je), predchádzajúce náhrady
   (tiež len ak na nich niečo je) a nakoniec aktívna náhrada.
   Predchádzajúce segmenty sú IBA NA ČÍTANIE – ich hotové série sa nikdy neprepisujú.
   `nextName` nesie cvik, ktorý daný segment NAOZAJ vystriedal (pri reťazci nie ten posledný). */
function exerciseSegments(info) {
  const steps = substitutionSteps(info.slot);
  if (!steps.length) {
    return [{ ex: info.ex, kind: 'plan', readOnly: false, active: true, step: null, nextName: '' }];
  }
  /* Uzavretý segment, po ktorom nasleduje krok „nastavenia“: jeho nesplnené série prevzal nasledovník,
     takže sa ukážu iba série po poslednú hotovú (`shown`) a do súčtu sérií idú len hotové. */
  const closed = (ex, step, next) => {
    const seg = { ex, kind: 'replaced', readOnly: true, active: false, step, nextName: exerciseDisplayName(next.ex) };
    if (next.kind === 'settings') { seg.settingsNext = true; seg.shown = exSettingsDoneExtent(ex); }
    return seg;
  };
  const segs = [];
  if (countDoneSets(info.ex) > 0) segs.push(closed(info.ex, null, steps[0]));
  for (let i = 0; i < steps.length; i++) {
    const step = steps[i];
    const last = i === steps.length - 1;
    if (last) {
      segs.push({ ex: step.ex, kind: step.kind === 'settings' ? 'settings' : 'substitute', readOnly: false, active: true, step, nextName: '' });
    } else if (countDoneSets(step.ex) > 0) {
      segs.push(closed(step.ex, step, steps[i + 1]));
    }
  }
  return segs;
}

/* ---------- Nastavenia cviku počas tréningu (session, NIE plán) ----------
   Zmena režimu (jednostranný / obojstranný), strany štartu, počtu ZOSTÁVAJÚCICH sérií, opakovaní, váhy alebo
   asistencie je ďalší krok reťazca sess.substituted[slot] s `kind: 'settings'` a novým `sessionKey`.
   Odcvičené série (značky, hodnoty, zlyhania) zostávajú pod pôvodným kľúčom a sú iba na čítanie; nový krok
   nesie len identitu cviku (id, názov, svaly) a zostávajúcu prácu – nikdy nie značky ani hodnoty starých sérií.
   Rozpracované (neodcvičené) hodnoty zostávajú v staršom kroku, takže Späť je bezstratové. Rovnaká cesta platí
   pre riadky plánu, duplicity aj cviky pridané počas tréningu. Plán ani pamäť váhy sa týmto nemenia. */
