async function communityModerate(action, id, extra) {
  const sb = communityClient(); if (!sb) return;
  let res = { error: null, data: [{ ok: 1 }] };
  if (action === 'approve' && communitySocial) {
    /* Schváli sa len text, ktorý moderátor videl: ak ho autor medzitým zmenil, nič sa neschváli. */
    res = await sb.from('posts').update({ status: 'approved', published_at: new Date().toISOString() })
      .eq('id', id).eq('status', 'pending').eq('caption', communityModCaptions[id] || '').select('id');
    if (!res.error && Array.isArray(res.data) && res.data.length === 0) { communitySetMessage('community.errChanged'); renderCommunity(); return; }
  } else if (action === 'approve' || action === 'reject') {
    const patch = action === 'approve' ? { status: 'approved', published_at: new Date().toISOString() } : { status: 'rejected' };
    res = await sb.from('posts').update(patch).eq('id', id).select('id');
  } else if (action === 'mod-remove') {
    res = await sb.from('posts').update({ status: 'rejected' }).eq('id', id).eq('status', 'approved').select('id');
  } else if (action === 'resolve-report') {
    res = await sb.from('reports').update({ status: 'resolved' }).eq('id', id).select('id');
  } else if (action === 'report-dismiss' || action === 'report-uphold-remove' || action === 'report-uphold-suspend') {
    res = await sb.rpc('resolve_report', { p_report: id, p_outcome: action === 'report-dismiss' ? 'dismissed' : 'upheld',
      p_remove_post: action === 'report-uphold-remove' });
    if (!res.error && action === 'report-uphold-suspend' && extra) res = await sb.from('profiles').update({ suspended: true }).eq('id', extra).select('id');
    else if (!res.error) res = { error: null, data: [{ ok: 1 }] };
  } else if (action === 'suspend' || action === 'unsuspend') {
    res = await sb.from('profiles').update({ suspended: action === 'suspend' }).eq('id', id).select('id');
  }
  /* RLS can filter the update to 0 rows without an error — report that honestly. */
  const denied = res && (res.error || (Array.isArray(res.data) && res.data.length === 0));
  communitySetMessage(denied ? 'community.errNotAllowed' : 'community.saved');
  if (action === 'mod-remove' && !denied) communityFeed.items = communityFeed.items.filter((p) => p.id !== id);
  renderCommunity();
}
/* Opustenie Community: odstráni príspevky a verejné údaje, ale ZACHOVÁ účet aj
   súkromnú cloudovú zálohu. (Server: delete-account mode 'community'.) */
function communityLeaveCommunity() {
  showGeneric(t('community.leaveTitle'), t('community.leaveConfirm'), () => {
    const sb = communityClient(); if (!sb) return;
    sb.functions.invoke('delete-account', { method: 'POST', body: { mode: 'community' } }).then((res) => {
      if (res && res.error) { communitySetMessage('community.errNetwork'); renderCommunity(); return null; }
      pushDisable(null);   // server zariadenia už zmazal (community_leave_cleanup)
      communityResetSocial2();
      communityProfile = null;
      communityConsent = null;
      communityView = 'feed';
      communitySetMessage('community.leftCommunity');
      renderCommunity();
    }).catch(() => { communitySetMessage('community.errNetwork'); renderCommunity(); });
  }, esc(t('community.leave')));
}
/* Úplné zmazanie účtu: zmaže účet aj všetky cloudové dáta (vrátane zálohy).
   (Server: delete-account mode 'full'.) Lokálne tréningy na zariadení zostávajú. */
function communityDeleteAccount() {
  showGeneric(t('community.deleteAccountTitle'), t('community.deleteAccount'), async () => {
    const sb = communityClient(); if (!sb) return;
    await wearRevoke();
    const user = await syncSessionUser();
    await syncQuiesce();   // žiadna synchronizácia nesmie po zmazaní zálohu znovu vytvoriť
    let res = null;
    try { res = await sb.functions.invoke('delete-account', { method: 'POST', body: { mode: 'full' } }); }
    catch (e) { res = { error: e }; }
    if (!res || res.error) { syncResume(); communitySetMessage('community.errNetwork'); renderCommunity(); return; }
    await pushDisable(null);   // účet je zmazaný aj so zariadeniami; lokálny odber sa zruší
    try { await sb.auth.signOut({ scope: 'local' }); } catch (e) {}
    communityProfile = null;
    if (user) wsDetachAfterAccountDeletion(user.id);   // lokálne dáta zostávajú ako hosťovský priestor
    try { sessionStorage.setItem('gq_notice', 'community.accountDeleted'); } catch (e) {}
    location.reload();
  }, esc(t('community.deleteAccountConfirm')));
}

/* ---------- E-mailové odkazy: potvrdenie účtu a obnova hesla ----------
   Spracúva sa aj pred zapnutím Community. Adresa s tokenom sa nikdy
   nezapisuje do logov a citlivé parametre sa hneď odstránia z adresného
   riadka. Nič sa neposiela a žiadne lokálne dáta sa nemenia. */
let authCallbackState = { view: 'idle', message: '', email: '' };

function authRedirectUrl() {
  try { return location.origin + location.pathname; } catch (e) { return location.href; }
}
function authHashParams() {
  const hash = location.hash && location.hash.charAt(0) === '#' ? location.hash.slice(1) : '';
  const search = location.search && location.search.charAt(0) === '?' ? location.search.slice(1) : '';
  const h = new URLSearchParams(hash);
  const q = new URLSearchParams(search);
  return { h: h, q: q, get: (k) => h.get(k) || q.get(k) || '' };
}
/* Odstráni tokeny z adresného riadka (celý hash aj citlivé query parametre). */
function authStripUrl() {
  try {
    const url = new URL(location.href);
    ['code', 'token_hash', 'error', 'error_code', 'error_description', 'type', 'access_token', 'refresh_token',
      'expires_in', 'expires_at', 'token_type', 'provider_token', 'provider_refresh_token']
      .forEach((k) => url.searchParams.delete(k));
    const q = url.searchParams.toString();
    history.replaceState(null, '', url.pathname + (q ? '?' + q : ''));
  } catch (e) { try { history.replaceState(null, '', location.pathname); } catch (e2) {} }
}
function authOpen() { const m = document.getElementById('modal-auth'); if (m) m.hidden = false; renderAuthModal(); }
function authClose() { const m = document.getElementById('modal-auth'); if (m) m.hidden = true; refreshUpdateBanner(); }
function authAskReset(email) { authCallbackState = { view: 'reset-request', message: '', email: email || '' }; authOpen(); }
function authStatusHtml() { return '<p class="media-status" id="auth-status" role="status" hidden></p>'; }
function authPrimary(key, action) {
  return '<div class="modal-actions">'
    + '<button type="button" class="btn btn-secondary" data-auth-action="close">' + esc(t('common.close')) + '</button>'
    + '<button type="button" class="btn btn-primary" data-auth-action="' + action + '">' + esc(t(key)) + '</button>'
    + '</div>';
}
/* Informational states have no distinct secondary action: a single primary
   (orange) button, so the same action is never offered twice. */
function authPrimaryOnly(key, action) {
  return '<div class="modal-actions">'
    + '<button type="button" class="btn btn-primary" data-auth-action="' + action + '">' + esc(t(key)) + '</button>'
    + '</div>';
}
function authEmailField(value) {
  return '<label class="modal-label" for="auth-email">' + esc(t('community.email')) + '</label>'
    + '<input type="email" class="modal-input" id="auth-email" autocomplete="email" value="' + escAttr(value || '') + '">';
}
function renderAuthModal() {
  const body = document.getElementById('auth-body');
  if (!body) return;
  const v = authCallbackState.view;
  if (v === 'confirmed') {
    body.innerHTML = '<p class="card-note">' + esc(t(authCallbackState.signedIn ? 'auth.confirmSignedIn' : 'auth.confirmSuccess')) + '</p>' + authPrimaryOnly('common.close', 'close');
  } else if (v === 'expired') {
    /* Neplatný/použitý odkaz: z adresy sa nedá spoľahlivo zistiť, či išlo o potvrdenie alebo
       obnovu hesla – ponúknu sa obe možnosti a nič sa nehlási ako úspech. */
    body.innerHTML = '<p class="card-note">' + esc(t('auth.expiredLinkBoth')) + '</p>' + authEmailField(authCallbackState.email || authLastEmail) + authStatusHtml()
      + '<div class="modal-actions">' + authMailButton('reset', 'auth.sendResetEmail', 'data-auth-action="send-reset"')
      + authMailButton('confirm', 'auth.resendConfirmation', 'data-auth-action="resend-confirm"') + '</div>'
      + authPrimaryOnly('common.close', 'close');
  } else if (v === 'reset-request') {
    body.innerHTML = '<p class="card-note">' + esc(t('auth.forgotHint')) + '</p>' + authEmailField(authCallbackState.email) + authStatusHtml()
      + '<div class="modal-actions"><button type="button" class="btn btn-secondary" data-auth-action="close">' + esc(t('common.close')) + '</button>'
      + authMailButton('reset', 'auth.sendResetEmail', 'data-auth-action="send-reset"').replace('btn btn-secondary', 'btn btn-primary') + '</div>';
  } else if (v === 'recovery') {
    body.innerHTML = '<p class="card-note">' + esc(t('auth.recoveryTitle')) + '</p>'
      + '<label class="modal-label" for="auth-newpass">' + esc(t('auth.newPassword')) + '</label>'
      + '<input type="password" class="modal-input" id="auth-newpass" autocomplete="new-password">'
      + '<label class="modal-label" for="auth-newpass2">' + esc(t('auth.confirmPassword')) + '</label>'
      + '<input type="password" class="modal-input" id="auth-newpass2" autocomplete="new-password">'
      + authStatusHtml()
      + '<div class="modal-actions">'
      + '<button type="button" class="btn btn-secondary" data-auth-action="close">' + esc(t('common.cancel')) + '</button>'
      + '<button type="button" class="btn btn-primary" data-auth-action="set-password" data-busy-kind="setpw"' + (authIsBusy('setpw') ? ' disabled' : '') + '>' + esc(t('auth.setPassword')) + '</button></div>';
  } else if (v === 'updated') {
    body.innerHTML = '<p class="card-note">' + esc(t('auth.passwordUpdated')) + '</p>' + authPrimaryOnly('common.close', 'close');
  } else if (v === 'sent') {
    body.innerHTML = '<p class="card-note">' + esc(t('auth.resetRequested')) + '</p>' + authPrimaryOnly('common.close', 'close');
  } else if (v === 'error') {
    body.innerHTML = '<p class="card-note">' + esc(t('auth.errorGeneric')) + '</p>' + authPrimaryOnly('common.close', 'close');
  } else {
    body.innerHTML = '';
  }
  if (authCallbackState.message) {
    const s = document.getElementById('auth-status');
    if (s) { s.textContent = authCallbackState.message; s.hidden = false; }
  }
  refreshUpdateBanner();
}
function authStatusText(text) { const s = document.getElementById('auth-status'); if (s) { s.textContent = text; s.hidden = false; } }
function authSendReset() { return authOnce('reset', authSendResetNow); }
async function authSendResetNow() {
  const el = document.getElementById('auth-email');
  const email = el ? el.value.trim() : '';
  if (!email) { authStatusText(t('auth.resetNeedEmail')); return; }
  if (!authEmailValid(email)) { authStatusText(t('auth.errInvalidEmail')); return; }
  authLastEmail = email;
  const left = authCooldownLeft('reset');
  if (left > 0) { authStatusText(t('auth.errRateLimitWait', { n: left })); return; }
  const sb = communitySb();
  if (!sb) { authStatusText(t('auth.errorGeneric')); return; }
  let res;
  try { res = await sb.auth.resetPasswordForEmail(email, { redirectTo: authRedirectUrl() }); }
  catch (e) { res = { error: e }; }
  if (res.error) { authStatusText(authErrorText(res.error, 'auth.resetFailed')); return; }
  /* Server odpovedá rovnako pre existujúci aj neexistujúci e-mail – správa tiež. */
  authStartCooldown('reset');
  authCallbackState = { view: 'sent', message: '', email: '' };
  renderAuthModal();
}
async function authResendFromModal() {
  const el = document.getElementById('auth-email');
  await authResendConfirmation(el ? el.value.trim() : '', authStatusText);
}
function authSetNewPassword() { return authOnce('setpw', authSetNewPasswordNow); }
async function authSetNewPasswordNow() {
  const p1 = document.getElementById('auth-newpass');
  const p2 = document.getElementById('auth-newpass2');
  const v1 = p1 ? p1.value : '';
  const v2 = p2 ? p2.value : '';
  authCallbackState.message = '';
  if (v1.length < 6) { authCallbackState.message = t('auth.passwordTooShort'); renderAuthModal(); return; }
  if (v1 !== v2) { authCallbackState.message = t('auth.passwordMismatch'); renderAuthModal(); return; }
  const sb = communitySb();
  if (!sb) { authCallbackState.message = t('auth.errorGeneric'); renderAuthModal(); return; }
  /* token_hash odkaz: jednorazový token sa použije až teraz, keď človek naozaj potvrdí nové heslo
     (e-mailové skenery, ktoré odkaz otvoria skôr, ho tak neminú). */
  if (authRecoveryTokenHash) {
    let vr;
    await syncQuiesce();
    try { vr = await sb.auth.verifyOtp({ token_hash: authRecoveryTokenHash, type: 'recovery' }); }
    catch (e) { vr = { error: e }; }
    syncResume();
    const verr = vr.error || (vr.data && vr.data.session ? null : { status: 403 });
    if (verr) {
      const st = Number(verr.status);
      if (st === 401 || st === 403 || verr.code === 'otp_expired') { authRecoveryTokenHash = ''; authCallbackState = { view: 'expired', message: '', email: '' }; }
      else authCallbackState.message = authErrorText(verr, 'auth.errorGeneric');
      renderAuthModal();
      return;
    }
    authRecoveryTokenHash = '';
    authRecoveryBindPending = true;
  }
  let res;
  try { res = await sb.auth.updateUser({ password: v1 }); }
  catch (e) { res = { error: e }; }
  if (res.error) {
    const e = res.error;
    /* Relácia z odkazu chýba alebo vypršala → odkaz už neplatí, nič sa nezmenilo. */
    if ((e.name === 'AuthSessionMissingError') || Number(e.status) === 401 || Number(e.status) === 403) {
      authCallbackState = { view: 'expired', message: '', email: '' };
    } else {
      authCallbackState.message = authErrorText(e, 'auth.errorGeneric');
    }
    renderAuthModal();
    return;
  }
  authCallbackState = { view: 'updated', message: '', email: '' };
  renderAuthModal();
  /* Prihlásenie vzniklo až teraz (nie pri štarte) → priraď účet k jeho priestoru ako pri bežnom prihlásení. */
  if (authRecoveryBindPending) { authRecoveryBindPending = false; await wsBindSession(true); }
}
/* Štart: citlivé parametre zmiznú z adresného riadka hneď po prečítaní. */
let authRecoveryTokenHash = '';
let authRecoveryBindPending = false;
async function initAuthCallback() {
  const p = authHashParams();
  if (!p.h.has('access_token') && !p.q.has('code') && !p.q.has('token_hash') && !p.get('error') && !p.get('error_code')) return;
  const type = p.get('type');
  /* Obnova hesla cez token_hash: zatiaľ nič neoveruj, iba ukáž formulár (token sa minie pri „Nastaviť heslo“). */
  if (p.q.get('token_hash') && type === 'recovery' && !p.get('error_code') && !p.get('error')) {
    authRecoveryTokenHash = p.q.get('token_hash');
    authStripUrl();
    authCallbackState = { view: 'recovery', message: '', email: '', signedIn: false };
    authOpen();
    return;
  }
  const errorCode = p.get('error_code') || p.get('error');
  const accessToken = p.h.get('access_token');
  const refreshToken = p.h.get('refresh_token');
  const code = p.q.get('code');
  const sb = communitySb();   // klient musí adresu ešte vidieť (implicit flow)
  authStripUrl();             // tokeny z adresného riadka preč
  if (errorCode) { authCallbackState = { view: 'expired', message: '', email: '' }; authOpen(); return; }
  if (!sb) { authCallbackState = { view: 'error', message: '', email: '' }; authOpen(); return; }
  /* The result of setSession/exchangeCodeForSession is authoritative: it gives
     the established session directly, whereas a later getSession() can briefly
     still be empty and would then be misread as an expired link. Only fall back
     to polling when the call returned no session. */
  let session = null;
  if (accessToken && refreshToken) {
    try { const r = await sb.auth.setSession({ access_token: accessToken, refresh_token: refreshToken }); session = r && r.data ? r.data.session : null; } catch (e) {}
  } else if (code) {
    try { const r = await sb.auth.exchangeCodeForSession(code); session = r && r.data ? r.data.session : null; } catch (e) {}
  }
  for (let i = 0; i < 20 && !session; i++) {
    try { const r = await sb.auth.getSession(); session = r && r.data ? r.data.session : null; } catch (e) {}
    if (!session) await new Promise((r) => setTimeout(r, 100));
  }
  if (type === 'recovery') authCallbackState = { view: session ? 'recovery' : 'expired', message: '', email: '', signedIn: !!session };
  else authCallbackState = { view: session ? 'confirmed' : 'expired', message: '', email: '', signedIn: !!session };
  authOpen();
  /* Priradenie účtu k priestoru (a načítanie) urobí syncStartup po tejto funkcii. */
}

function setPokrokView(view) {
  pokrokView = (view === 'stats' || view === 'body' || view === 'food' || view === 'photos' || view === 'motivation') ? view : 'progress';
  renderPokrok();
  refreshUpdateBanner();
}

function renderPokrokSubtabs() {
  const bar = document.getElementById('pokrok-subtabs');
  if (!bar) return;
  bar.querySelectorAll('.subtab').forEach((b) => {
    const on = b.dataset.pokrok === pokrokView;
    b.classList.toggle('active', on);
    b.setAttribute('aria-selected', on ? 'true' : 'false');
  });
  for (const v of ['progress', 'body', 'food', 'photos', 'motivation']) {
    const el = document.getElementById('subview-' + v);
    if (el) el.hidden = v !== pokrokView;
  }
  const grid = document.getElementById('stats-grid');
  if (grid) grid.hidden = pokrokView !== 'stats';
  const screen = document.getElementById('screen-pokrok');
  if (screen) screen.classList.toggle('sheet-open', pokrokView !== 'stats');
  if (pokrokView === 'stats') renderStatsGrid();
}

/* ---------- Bento: prehľad Štatistiky (dlaždice ako návrh) ---------- */
function historySets(w) {
  return (w.exercises || []).reduce((a, e) => a + (Number(e.setsDone) || 0), 0);
}
function bentoStatValue(n, sets) {
  /* sériu dáme na vlastný riadok: oddeľovač „·“ sa pri zalomení nesmie osamotiť na začiatku riadku */
  return '<span class="bt-v">' + n + '<small> ' + esc(tPluralWord('bento.workoutsWord', n)) + '</small>'
    + '<small class="bt-v-sets">' + esc(tPlural('bento.setCount', sets).replace('{n}', String(sets))) + '</small></span>';
}
function bentoBars(vals, labels, aria) {
  const W = 320, H = 110, gap = 6, lh = 14;
  const max = Math.max(1, ...vals), bw = (W - gap * (vals.length - 1)) / vals.length;
  return '<svg class="k-chart" viewBox="0 0 ' + W + ' ' + H + '" role="img" aria-label="' + escAttr(aria) + '">' + vals.map((v, i) => {
    const bh = Math.max(2, v / max * (H - lh - 4));
    return '<rect x="' + (i * (bw + gap)) + '" y="' + (H - lh - bh) + '" width="' + bw + '" height="' + bh + '" rx="3" class="k-col' + (i === vals.length - 1 ? ' last' : '') + '"/>'
      + '<text x="' + (i * (bw + gap) + bw / 2) + '" y="' + (H - 2) + '" text-anchor="middle" class="k-chart-t">' + esc(labels[i]) + '</text>';
  }).join('') + '</svg>';
}
function renderStatsGrid() {
  const grid = document.getElementById('stats-grid');
  if (!grid) return;
  const hist = state.history || [];
  const wk = currentWeekKey(), mk = currentMonthKey();
  const inWeek = hist.filter((w) => weekKey(parseDate(w.date)) === wk);
  const inMonth = hist.filter((w) => monthKey(parseDate(w.date)) === mk);
  const sum = (list) => list.reduce((a, w) => a + historySets(w), 0);
  /* posledných 8 ISO týždňov: série za týždeň */
  const vals = [], labels = [];
  for (let i = 7; i >= 0; i--) {
    const key = weekKey(addDays(new Date(), -7 * i));
    vals.push(sum(hist.filter((w) => weekKey(parseDate(w.date)) === key)));
    labels.push(t('bento.weekShort', { n: Number(key.split('-W')[1]) }));
  }
  const recs = personalRecords().slice(0, 3);
  const ach = Object.keys(state.achievements || {}).length;
  const recent = hist.slice().sort((a, b) => (a.date < b.date ? 1 : a.date > b.date ? -1 : 0)).slice(0, 4);
  const tile = (cls, go, inner, label) => '<button type="button" class="bt ' + cls + '" data-go="' + go + '"' + (label ? ' aria-label="' + escAttr(label) + '"' : '') + '>' + inner + '</button>';
  const L = (k) => '<span class="bt-l">' + esc(t(k)) + '</span>';
  grid.innerHTML = tile('bt-lime w2', 'history', L('bento.statWeek') + bentoStatValue(inWeek.length, sum(inWeek)))
    + tile('w2', 'history', L('bento.statMonth') + bentoStatValue(inMonth.length, sum(inMonth)))
    + tile('bt-lav w4', 'history', L('bento.statAll') + bentoStatValue(hist.length, sum(hist)))
    + '<div class="bt w4 h2 bt-static">' + L('bento.setsPerWeek') + bentoBars(vals, labels, t('bento.setsPerWeek')) + '</div>'
    + tile('bt-dark w2 h2', 'records', L('bento.records') + (recs.length
      ? recs.map((r) => '<span class="st-rec"><span>' + esc(recordedNameToDisplay(r.name)) + '</span><b>' + r.weight + '</b></span>').join('')
      : '<span class="bt-line">' + esc(t('pokrok.recordsEmpty')) + '</span>'))
    + tile('bt-peach w2 h2', 'motivation', L('bento.achievements') + '<span class="bt-v">' + ach + '</span><span class="bt-line">' + esc(t('bento.unlocked')) + '</span>')
    + tile('w2 bt-muscles', 'muscles', L('muscles.tile') + '<span class="bt-line">' + muscleTileLine() + '</span>' + bodyMapSvg(muscleRecovery(Date.now()), { size: 'mini' }))
    + tile('w2', 'calendar', bentoIcon('calendar') + '<span class="bt-line bt-bottom">' + esc(t('tab.kalendar')) + '</span>')
    + tile('w2', 'history', bentoIcon('clock') + '<span class="bt-line bt-bottom">' + esc(t('bento.history')) + '</span>')
    + recent.map((w) => '<button type="button" class="bt w2" data-day="' + escAttr(w.date) + '"><span class="bt-l">' + esc(bentoShortDay(w.date)) + '</span><b class="st-plan">'
      + esc(historyPlanName(w)) + '</b><span class="bt-line">' + bentoWorkoutLine(w) + '</span></button>').join('')
    + tile('bt-sky w2', 'body', bentoIcon('scale') + '<span class="bt-line bt-bottom">' + esc(t('bento.body')) + '</span>')
    + tile('w2', 'photos', bentoIcon('camera') + '<span class="bt-line bt-bottom">' + esc(t('bento.photos')) + '</span>')
    + tile('w2', 'food', bentoIcon('utensils') + '<span class="bt-line bt-bottom">' + esc(t('bento.foodTitle')) + '</span>')
    + tile('w2', 'history', bentoIcon('run') + '<span class="bt-line bt-bottom">' + esc(t('pokrok.actCount')) + '</span>');
}
function bentoWorkoutLine(w) {
  const mins = Math.round((Number(w.durationSeconds) || 0) / 60);
  return esc(mins ? t('bento.minutes', { n: mins }) + ' · ' : '') + '<bdi>+' + historyEntryXp(w) + ' ' + esc(t('units.xp')) + '</bdi>';   // vracia HTML (bdi: arabčina)
}

