/* ---------- Telo: súhrn najnovších mier ---------- */
function renderBodySummary() {
  const box = document.getElementById('body-summary');
  if (!box) return;
  box.innerHTML = '';
  if (!measureSeries('weightKg').length && !MEASURE_META.some((m) => measureSeries(m.field).length)) {
    const p = document.createElement('p');
    p.className = 'empty-state';
    p.textContent = t('body.empty');
    box.appendChild(p);
    return;
  }
  for (const m of MEASURE_META) {
    const series = measureSeries(m.field);
    if (!series.length) continue;
    const last = series[series.length - 1];
    const prev = series.length > 1 ? series[series.length - 2] : null;
    const row = document.createElement('div');
    row.className = 'measure-row';
    const name = document.createElement('span');
    name.className = 'measure-name';
    name.textContent = t(m.key);
    if (prev) {
      /* Neutrálne: nárast ani pokles nie je sám o sebe dobrý ani zlý. */
      const nowShown = measureToDisplay(last.value, m.kind);
      const prevShown = measureToDisplay(prev.value, m.kind);
      const diff = Math.round((nowShown - prevShown) * 10) / 10;
      const delta = document.createElement('span');
      delta.className = 'measure-delta';
      delta.textContent = ' ' + (diff > 0 ? '+' : (diff < 0 ? '−' : '±'))
        + Math.abs(diff).toFixed(1) + ' ' + measureUnit(m.kind);
      name.appendChild(delta);
    }
    const val = document.createElement('span');
    val.className = 'measure-value';
    val.textContent = formatMeasureValue(last.value, m.kind);
    row.append(name, val);
    box.appendChild(row);
  }
}

/* ---------- Telo: história meraní ---------- */
function renderBodyHistory() {
  const box = document.getElementById('body-history');
  if (!box) return;
  box.innerHTML = '';
  const list = sortedMeasurements().slice().reverse();
  if (!list.length) {
    const p = document.createElement('p');
    p.className = 'empty-state';
    p.textContent = t('body.empty');
    box.appendChild(p);
    return;
  }
  for (const m of list) {
    const row = document.createElement('div');
    row.className = 'measure-entry';

    const head = document.createElement('div');
    head.className = 'measure-entry-head';
    const date = document.createElement('span');
    date.className = 'measure-entry-date';
    date.textContent = formatDate(m.date);
    const actions = document.createElement('span');
    actions.className = 'measure-entry-actions';
    const edit = document.createElement('button');
    edit.type = 'button';
    edit.className = 'btn-icon-sm';
    edit.textContent = '✏️';
    edit.title = t('body.editTitle');
    edit.setAttribute('aria-label', t('body.editTitle'));
    edit.addEventListener('click', () => openMeasureModal(m.id));
    const del = document.createElement('button');
    del.type = 'button';
    del.className = 'btn-icon-sm btn-icon-danger';
    del.textContent = '🗑️';
    del.title = t('body.deleteTitle');
    del.setAttribute('aria-label', t('body.deleteTitle'));
    del.addEventListener('click', () => requestDeleteMeasurement(m.id));
    actions.append(edit, del);
    head.append(date, actions);
    row.appendChild(head);

    const values = document.createElement('div');
    values.className = 'measure-entry-values';
    const parts = MEASURE_META.filter((x) => m[x.field] !== null && m[x.field] !== undefined)
      .map((x) => measureLabel(x.field) + ' ' + formatMeasureValue(m[x.field], x.kind));
    values.textContent = parts.length ? parts.join(' · ') : t('body.noValues');
    row.appendChild(values);

    if (m.note) {
      const note = document.createElement('div');
      note.className = 'measure-entry-note';
      note.textContent = '“' + m.note + '”';
      row.appendChild(note);
    }
    box.appendChild(row);
  }
}

/* ---------- Telo: graf (vlastné SVG, žiadna knižnica) ---------- */
function buildSparkline(series, kind) {
  const ns = 'http://www.w3.org/2000/svg';
  const W = 300, H = 140, PAD = 12;
  const vals = series.map((p) => measureToDisplay(p.value, kind));
  const lo = Math.min(...vals), hi = Math.max(...vals);
  const span = (hi - lo) || 1;
  const n = vals.length;

  const svg = document.createElementNS(ns, 'svg');
  svg.setAttribute('class', 'chart-svg');
  svg.setAttribute('viewBox', '0 0 ' + W + ' ' + H);
  svg.setAttribute('role', 'img');
  svg.setAttribute('aria-label', t('body.chartAria', {
    n, min: (Math.round(lo * 10) / 10).toFixed(1), max: (Math.round(hi * 10) / 10).toFixed(1),
  }));

  const x = (i) => PAD + (i * (W - 2 * PAD)) / (n - 1);
  const y = (v) => H - PAD - ((v - lo) / span) * (H - 2 * PAD);
  const pts = vals.map((v, i) => [x(i), y(v)]);
  const line = pts.map(([px, py], i) => (i ? 'L' : 'M') + px.toFixed(1) + ' ' + py.toFixed(1)).join(' ');
  const area = line + ' L' + x(n - 1).toFixed(1) + ' ' + (H - PAD) + ' L' + x(0).toFixed(1) + ' ' + (H - PAD) + ' Z';

  const areaEl = document.createElementNS(ns, 'path');
  areaEl.setAttribute('class', 'chart-area');
  areaEl.setAttribute('d', area);
  svg.appendChild(areaEl);

  const lineEl = document.createElementNS(ns, 'path');
  lineEl.setAttribute('class', 'chart-line');
  lineEl.setAttribute('d', line);
  svg.appendChild(lineEl);

  /* Pri veľmi dlhej histórii sa bodky vynechávajú, aby graf nebol preplnený. */
  if (n <= 40) {
    for (const [px, py] of pts) {
      const dot = document.createElementNS(ns, 'circle');
      dot.setAttribute('class', 'chart-dot');
      dot.setAttribute('cx', px.toFixed(1));
      dot.setAttribute('cy', py.toFixed(1));
      dot.setAttribute('r', '2.5');
      svg.appendChild(dot);
    }
  }
  return svg;
}

/* Rozsah grafu: 'all' | '3m' | '1m' (iba zobrazenie, nič sa neukladá). */
const BODY_CHART_RANGES = ['all', '3m', '1m'];

/* Dátum (YYYY-MM-DD) -> číslo dňa (UTC, bez posunu letného času). */
function chartDayNum(iso) {
  const p = String(iso).split('-').map(Number);
  return Math.round(Date.UTC(p[0], p[1] - 1, p[2]) / 86400000);
}

/* Body v zvolenom rozsahu: 3 / 1 mesiac dozadu od dnešného dňa. */
function chartRangeSeries(series, range, now) {
  if (range !== '3m' && range !== '1m') return series;
  const d = now ? new Date(now.getTime()) : new Date();
  /* Deň sa orezá na posledný deň cieľového mesiaca (31. 3. − 1 mesiac = 28./29. 2.). */
  const day = d.getDate();
  d.setDate(1);
  d.setMonth(d.getMonth() - (range === '3m' ? 3 : 1));
  d.setDate(Math.min(day, new Date(d.getFullYear(), d.getMonth() + 1, 0).getDate()));
  const pad = (n) => String(n).padStart(2, '0');
  const cut = d.getFullYear() + '-' + pad(d.getMonth() + 1) + '-' + pad(d.getDate());
  return series.filter((p) => p.date >= cut);
}

/* "Pekné" značky osi y: 3 až 5 hodnôt, krok z radu 1/2/5 × 10^k. */
function chartNiceTicks(lo, hi) {
  if (!(hi > lo)) {
    const pad = Math.max(Math.abs(lo) * 0.05, 1);
    lo -= pad; hi += pad;
  }
  const raw = (hi - lo) / 3;
  const pow = Math.pow(10, Math.floor(Math.log10(raw)));
  const step = [1, 2, 5, 10].map((m) => m * pow).find((s) => s >= raw);
  const decimals = step >= 1 ? 0 : Math.ceil(-Math.log10(step) - 1e-9);
  const first = Math.floor(lo / step + 1e-9), last = Math.ceil(hi / step - 1e-9);
  const ticks = [];
  for (let i = first; i <= last; i++) ticks.push(Math.round(i * step * 1e6) / 1e6);
  return { ticks, decimals };
}

/* Krátky dátum osi x ("10 nov."); rok len keď graf presahuje viac rokov. */
function chartShortDate(iso, withYear) {
  const d = parseDate(iso);
  return d.getDate() + ' ' + localeData().monthsShort[d.getMonth()] + (withYear ? ' ' + String(d.getFullYear()).slice(2) : '');
}

/* Responzívny čiarový graf s dátumovou osou x. Šírka sa berie zo skutočnej šírky
   boxu (1 jednotka viewBoxu = 1 px), takže písmo ostane čitateľné aj pri 320 px.
   Os času plynie VŽDY zľava doprava (aj v arabčine): čísla a dátumy sa čítajú
   zľava doprava a starší záznam je vľavo – rovnako ako v zdravotných aplikáciách. */
function buildBodyChart(box, series, meta) {
  const ns = 'http://www.w3.org/2000/svg';
  const W = Math.max(Math.round(box.clientWidth) || 300, 240), H = 210;
  const unit = measureUnit(meta.kind);
  const vals = series.map((p) => measureToDisplay(p.value, meta.kind));
  const shownVal = (v) => (Math.round(v * 10) / 10).toFixed(1);

  const svg = document.createElementNS(ns, 'svg');
  svg.setAttribute('class', 'chart-svg');
  svg.setAttribute('viewBox', '0 0 ' + W + ' ' + H);
  svg.setAttribute('width', W);
  svg.setAttribute('height', H);
  svg.setAttribute('role', 'group');
  svg.setAttribute('aria-label', t('body.chartAria', { n: series.length, min: shownVal(Math.min(...vals)), max: shownVal(Math.max(...vals)) }));
  box.appendChild(svg);
  const fs = parseFloat(getComputedStyle(svg).fontSize) || 11;
  const cw = fs * 0.62;   // odhad šírky znaku

  const nice = chartNiceTicks(Math.min(...vals), Math.max(...vals));
  const tickTxt = nice.ticks.map((v) => v.toFixed(nice.decimals));
  const yW = Math.max(...tickTxt.map((s) => s.length)) * cw;
  const days = series.map((p) => chartDayNum(p.date));
  const d0 = days[0], d1 = days[days.length - 1];
  const withYear = series[0].date.slice(0, 4) !== series[series.length - 1].date.slice(0, 4);
  const labW = (withYear ? 9 : 7) * cw + fs;   // šírka jedného dátumu + medzera
  const half = labW / 2;
  const L = Math.ceil(yW + 8 + Math.max(0, half - yW - 8)), R = W - Math.ceil(half);
  const T = 12, B = H - 30;
  const yMin = nice.ticks[0], yMax = nice.ticks[nice.ticks.length - 1];
  const x = (dn) => (d1 === d0 ? (L + R) / 2 : L + ((dn - d0) / (d1 - d0)) * (R - L));
  const y = (v) => B - ((v - yMin) / (yMax - yMin)) * (B - T);
  const mk = (tag, attrs, text) => {
    const e = document.createElementNS(ns, tag);
    for (const k of Object.keys(attrs)) e.setAttribute(k, attrs[k]);
    if (text !== undefined) e.textContent = text;
    return e;
  };

  /* Os y: vodorovné čiary + hodnoty (jednotky sú v popise grafu). */
  nice.ticks.forEach((v, i) => {
    svg.appendChild(mk('line', { class: 'chart-grid', x1: L, x2: W - 4, y1: y(v).toFixed(1), y2: y(v).toFixed(1) }));
    svg.appendChild(mk('text', { class: 'chart-axis', x: L - 6, y: (y(v) + fs * 0.35).toFixed(1), 'text-anchor': 'end' }, tickTxt[i]));
  });

  /* Os x: dátumy rovnomerne v čase, počet podľa šírky (bez prekrytia). */
  const k = d1 === d0 ? 1 : Math.max(2, Math.min(5, Math.floor((R - L) / labW) + 1));
  for (let i = 0; i < k; i++) {
    const dn = k === 1 ? d0 : d0 + ((d1 - d0) * i) / (k - 1);
    const iso = k === 1 ? series[0].date : (i === 0 ? series[0].date : (i === k - 1 ? series[series.length - 1].date : isoFromDayNum(Math.round(dn))));
    svg.appendChild(mk('text', { class: 'chart-axis', x: x(dn).toFixed(1), y: H - 10, 'text-anchor': 'middle' }, chartShortDate(iso, withYear)));
  }

  const pts = series.map((p, i) => [x(days[i]), y(vals[i])]);
  const line = pts.map(([px, py], i) => (i ? 'L' : 'M') + px.toFixed(1) + ' ' + py.toFixed(1)).join(' ');
  if (pts.length > 1) {
    svg.appendChild(mk('path', { class: 'chart-area', d: line + ' L' + pts[pts.length - 1][0].toFixed(1) + ' ' + B + ' L' + pts[0][0].toFixed(1) + ' ' + B + ' Z' }));
    svg.appendChild(mk('path', { class: 'chart-line', d: line }));
  }

  /* Bodka na záznam; ťuk / fokus / Enter ukáže dátum a hodnotu. Neviditeľná
     väčšia plocha (r = 22) dáva dotykový cieľ ≥ 44 px. */
  const tip = document.createElement('div');
  tip.className = 'chart-tip';
  tip.setAttribute('role', 'status');
  tip.hidden = true;
  box.appendChild(tip);
  const show = (i) => {
    svg.querySelectorAll('.chart-dot').forEach((d, j) => d.classList.toggle('active', j === i));
    tip.textContent = formatDate(series[i].date) + ' · ' + shownVal(vals[i]) + ' ' + unit;
    tip.hidden = false;
    const bw = box.clientWidth, tw = tip.offsetWidth;
    tip.style.left = Math.max(0, Math.min(bw - tw, pts[i][0] - tw / 2)).toFixed(0) + 'px';
    tip.style.top = Math.max(0, pts[i][1] - tip.offsetHeight - 10).toFixed(0) + 'px';
  };
  pts.forEach(([px, py], i) => {
    const g = mk('g', { class: 'chart-pt', tabindex: '0', role: 'button', 'data-i': i,
      'aria-label': formatDate(series[i].date) + ', ' + shownVal(vals[i]) + ' ' + unit });
    g.appendChild(mk('circle', { class: 'chart-hit', cx: px.toFixed(1), cy: py.toFixed(1), r: 22 }));
    g.appendChild(mk('circle', { class: 'chart-dot', cx: px.toFixed(1), cy: py.toFixed(1), r: 4 }));
    g.addEventListener('focus', () => show(i));
    g.addEventListener('keydown', (e) => { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); show(i); } });
    svg.appendChild(g);
  });
  /* Jediný handler (prepíše sa pri každom vykreslení): vyberie najbližšiu bodku podľa x,
     aby husté body (r = 22 sa prekrývajú) zostali ťukateľné; mimo bodiek tooltip zatvorí. */
  box.onclick = (e) => {
    const r = svg.getBoundingClientRect();
    const sc = r.width ? W / r.width : 1;
    const cx = (e.clientX - r.left) * sc, cy = (e.clientY - r.top) * sc;
    let best = -1, bd = Infinity;
    pts.forEach(([px], i) => { const dx = Math.abs(px - cx); if (dx < bd) { bd = dx; best = i; } });
    if (best >= 0 && bd <= 22 && Math.abs(pts[best][1] - cy) <= 22) { show(best); return; }
    tip.hidden = true;
    svg.querySelectorAll('.chart-dot.active').forEach((d) => d.classList.remove('active'));
  };
  return svg;
}

function isoFromDayNum(n) {
  const d = new Date(n * 86400000);
  const pad = (v) => String(v).padStart(2, '0');
  return d.getUTCFullYear() + '-' + pad(d.getUTCMonth() + 1) + '-' + pad(d.getUTCDate());
}

function renderBodyChart() {
  const card = document.getElementById('body-chart-card');
  const chips = document.getElementById('body-metric-chips');
  const box = document.getElementById('body-chart');
  const rangeEl = document.getElementById('body-chart-range');
  const rangeChips = document.getElementById('body-range-chips');
  if (!card || !chips || !box || !rangeEl) return;

  const withPoints = MEASURE_META.filter((m) => measureSeries(m.field).length >= 1);
  card.hidden = withPoints.length === 0;
  if (!withPoints.length) return;
  if (!withPoints.some((m) => m.field === chartField)) chartField = withPoints[0].field;

  chips.innerHTML = '';
  for (const m of MEASURE_META) {
    const series = measureSeries(m.field);
    if (!series.length) continue;
    const chip = document.createElement('button');
    chip.type = 'button';
    chip.className = 'metric-chip' + (chartField === m.field ? ' active' : '');
    chip.dataset.field = m.field;
    chip.textContent = t(m.key);
    chip.setAttribute('aria-pressed', chartField === m.field ? 'true' : 'false');
    chip.addEventListener('click', () => { chartField = m.field; renderBodyChart(); });
    chips.appendChild(chip);
  }
  if (rangeChips) {
    rangeChips.innerHTML = '';
    for (const r of BODY_CHART_RANGES) {
      const chip = document.createElement('button');
      chip.type = 'button';
      chip.className = 'metric-chip' + (chartRange === r ? ' active' : '');
      chip.dataset.range = r;
      chip.textContent = t('body.range.' + r);
      chip.setAttribute('aria-pressed', chartRange === r ? 'true' : 'false');
      chip.addEventListener('click', () => { chartRange = r; renderBodyChart(); });
      rangeChips.appendChild(chip);
    }
  }

  const meta = measureMeta(chartField);
  const series = chartRangeSeries(measureSeries(chartField), chartRange);
  box.innerHTML = '';
  if (!series.length) {
    rangeEl.textContent = t('body.chartNone');
    return;
  }
  buildBodyChart(box, series, meta);
  const vals = series.map((p) => measureToDisplay(p.value, meta.kind));
  const rangeTxt = t('body.chartRange', {
    min: (Math.round(Math.min(...vals) * 10) / 10).toFixed(1),
    max: (Math.round(Math.max(...vals) * 10) / 10).toFixed(1),
    unit: measureUnit(meta.kind),
  });
  rangeEl.textContent = series.length < 2 ? t('body.chartNeedTwo') + ' ' + rangeTxt : rangeTxt;
}

/* ---------- Telo: porovnanie dvoch dátumov ---------- */
/* Pokles je dobrý len pri páse a telesnom tuku; ostatné zmeny sú neutrálne. */
const COMPARE_LOWER_IS_BETTER = ['waistCm', 'bodyFatPct'];

function renderBodyCompare() {
  const card = document.getElementById('body-compare-card');
  const box = document.getElementById('body-compare');
  if (!card || !box) return;
  const list = sortedMeasurements().filter((m) => MEASURE_ALL_FIELDS.some((f) => m[f] !== null && m[f] !== undefined));
  card.hidden = list.length < 2;
  if (list.length < 2) return;
  if (!list.some((m) => m.id === compareA)) compareA = list[0].id;
  if (!list.some((m) => m.id === compareB)) compareB = list[list.length - 1].id;

  box.innerHTML = '';
  const opts = list.map((m) => ({ value: m.id, label: formatDate(m.date) }));
  const grid = document.createElement('div');
  grid.className = 'field-grid';
  grid.appendChild(buildSelect('cmp-a', t('body.cmpFrom'), opts, compareA));
  grid.appendChild(buildSelect('cmp-b', t('body.cmpTo'), opts, compareB));
  grid.querySelectorAll('.field').forEach((f) => f.classList.remove('field-wide'));
  grid.querySelectorAll('select').forEach((s) => s.addEventListener('change', () => {
    compareA = document.getElementById('cmp-a').value;
    compareB = document.getElementById('cmp-b').value;
    renderBodyCompare();
    const again = document.getElementById(s.id);
    if (again) again.focus();
  }));
  box.appendChild(grid);

  const a = measurementById(compareA), b = measurementById(compareB);
  if (!a || !b) return;
  const days = Math.abs(chartDayNum(b.date) - chartDayNum(a.date));
  const daysEl = document.createElement('p');
  daysEl.className = 'card-note';
  daysEl.id = 'cmp-days';
  daysEl.textContent = t('body.cmpDays', { n: days });
  box.appendChild(daysEl);

  const rows = MEASURE_META.filter((m) => a[m.field] !== null && a[m.field] !== undefined && b[m.field] !== null && b[m.field] !== undefined);
  if (!rows.length) {
    const p = document.createElement('p');
    p.className = 'empty-state';
    p.id = 'cmp-none';
    p.textContent = t('body.cmpNone');
    box.appendChild(p);
    return;
  }
  const table = document.createElement('table');
  table.className = 'cmp-table';
  table.id = 'cmp-table';
  table.setAttribute('aria-label', t('body.cmpTableAria'));
  const head = document.createElement('tr');
  for (const txt of [t('body.cmpMeasure'), formatDate(a.date), formatDate(b.date), t('body.cmpChange')]) {
    const th = document.createElement('th');
    th.scope = 'col';
    th.textContent = txt;
    head.appendChild(th);
  }
  const thead = document.createElement('thead');
  thead.appendChild(head);
  table.appendChild(thead);
  const tbody = document.createElement('tbody');
  for (const m of rows) {
    const tr = document.createElement('tr');
    tr.dataset.field = m.field;
    const th = document.createElement('th');
    th.scope = 'row';
    th.textContent = t(m.key);
    const tdA = document.createElement('td');
    tdA.textContent = formatMeasure(a[m.field], m.kind);
    const tdB = document.createElement('td');
    tdB.textContent = formatMeasure(b[m.field], m.kind);
    /* Rozdiel z hodnôt zaokrúhlených na 1 desatinu, ako sú zobrazené v A a B. */
    const r1 = (v) => Math.round(measureToDisplay(v, m.kind) * 10) / 10;
    const diff = Math.round((r1(b[m.field]) - r1(a[m.field])) * 10) / 10;
    const tdD = document.createElement('td');
    tdD.className = 'cmp-diff';
    let word = '';
    if (diff !== 0 && COMPARE_LOWER_IS_BETTER.includes(m.field)) {
      const good = diff < 0;
      tdD.classList.add(good ? 'cmp-good' : 'cmp-bad');
      word = ', ' + t(good ? 'body.cmpBetter' : 'body.cmpWorse');
    }
    const txt = (diff > 0 ? '+' : (diff < 0 ? '−' : '±')) + Math.abs(diff).toFixed(1) + ' ' + measureUnit(m.kind);
    tdD.textContent = txt;
    tdD.setAttribute('aria-label', txt + word);
    tr.append(th, tdA, tdB, tdD);
    tbody.appendChild(tr);
  }
  table.appendChild(tbody);
  box.appendChild(table);
  const note = document.createElement('p');
  note.className = 'card-note';
  note.textContent = t('body.cmpNote');
  box.appendChild(note);
}

/* ---------- Telo: meranie (modal) ---------- */
function renderMeasureFields(values) {
  const box = document.getElementById('measure-fields');
  if (!box) return;
  box.innerHTML = '';
  const grid = document.createElement('div');
  grid.className = 'field-grid';
  for (const m of MEASURE_META) {
    const current = values && values[m.field] !== null && values[m.field] !== undefined
      ? Math.round(measureToDisplay(values[m.field], m.kind) * 10) / 10
      : '';
    grid.appendChild(buildField('m-' + m.field, measureLabel(m.field) + ' (' + measureUnit(m.kind) + ')', current));
  }
  const hint = document.createElement('p');
  hint.className = 'field-hint field-wide';
  hint.textContent = t('body.fieldsHint');
  grid.appendChild(hint);
  box.appendChild(grid);
}

function openMeasureModal(id) {
  measureEditId = id || null;
  const m = id ? measurementById(id) : null;
  document.getElementById('measure-title').textContent = t(m ? 'body.editTitle' : 'body.addTitle');
  document.getElementById('measure-date').value = m ? m.date : todayISO();
  document.getElementById('measure-note').value = m ? m.note : '';
  document.getElementById('measure-error').hidden = true;
  renderMeasureFields(m);
  document.getElementById('modal-measure').hidden = false;
  refreshUpdateBanner();
}

function showMeasureError(msg) {
  const el = document.getElementById('measure-error');
  if (!el) return;
  el.textContent = msg;
  el.hidden = false;
}

function saveMeasure() {
  const date = document.getElementById('measure-date').value || '';
  if (!isDateKey(date)) { showMeasureError(t('body.errDate')); return; }

  const values = {};
  const bad = [];
  document.querySelectorAll('#measure-fields .field input').forEach((inp) => {
    const field = String(inp.id).slice(2);
    const raw = inp.value.trim();
    if (raw === '') { values[field] = null; return; }
    const n = Number(raw);
    const meta = measureMeta(field);
    const limit = MEASURE_LIMITS[field];
    const canon = (Number.isFinite(n) && n > 0)
      ? measureFromDisplay(n, meta.kind)
      : null;
    if (canon === null || canon < limit[0] || canon > limit[1]) {
      bad.push(measureLabel(field));
      values[field] = null;
      return;
    }
    values[field] = canon;   // platná hodnota sa ukladá presne, nikdy sa neupravuje
  });

  if (bad.length) { showMeasureError(t('body.errRange', { fields: bad.join(', ') })); return; }
  const note = document.getElementById('measure-note').value.trim();
  if (MEASURE_ALL_FIELDS.every((f) => values[f] === null) && !note) {
    showMeasureError(t('body.errEmpty'));
    return;
  }

  for (const f of MEASURE_EXTRA_FIELDS) if (values[f] === null) delete values[f];
  const entry = Object.assign({ id: measureEditId || uid(), date, note }, values);
  if (measureEditId) {
    const at = state.measurements.findIndex((m) => m.id === measureEditId);
    if (at >= 0) state.measurements[at] = entry;
    else state.measurements.push(entry);
  } else {
    state.measurements.push(entry);
  }
  measureEditId = null;
  measureExtraRestore(state, true);   // zrkadlo nových polí pre staré verzie appky
  reconcileAchievements();   // úspech "Telesný denník" (váha v 4 týždňoch)
  saveState();
  document.getElementById('modal-measure').hidden = true;
  renderPokrok();
  refreshUpdateBanner();
}

function requestDeleteMeasurement(id) {
  const m = measurementById(id);
  if (!m) return;
  showGeneric(t('body.deleteTitle'), t('common.delete'), () => {
    state.measurements = state.measurements.filter((x) => x.id !== id);
    measureExtraRestore(state, true);
    saveState();
    renderPokrok();
  }, t('body.deleteConfirm', { date: formatDate(m.date) }));
}

/* ---------- Kalorický odhad (voliteľný, opatrný) ---------- */
function latestMeasuredWeightKg() {
  const list = sortedMeasurements().filter((m) => m.weightKg !== null);
  return list.length ? list[list.length - 1] : null;
}

function calorieMissing() {
  const p = state.profile || {};
  const missing = [];
  if (p.heightCm === null) missing.push(t('calorie.inHeight'));
  if (p.ageYears === null) missing.push(t('calorie.inAge'));
  if (!p.sex) missing.push(t('calorie.inSex'));
  if (!p.activity) missing.push(t('calorie.inActivity'));
  if (!latestMeasuredWeightKg()) missing.push(t('calorie.inWeight'));
  return missing;
}

function calorieSignature() {
  const p = state.profile || {};
  const w = latestMeasuredWeightKg();
  return [p.heightCm, p.ageYears, p.sex, p.activity, w ? w.weightKg : null].join('|');
}

/* Mifflin-St Jeor (1990) × faktor aktivity. Vráti null, kým nie sú VŠETKY
   vstupy známe – odhad sa nikdy nedopočítava z neúplných údajov. */
function calorieEstimate() {
  const p = state.profile || {};
  if (p.isAdult !== true) return null;
  const w = latestMeasuredWeightKg();
  const act = ACTIVITY_LEVELS.find((x) => x.id === p.activity);
  if (!w || w.weightKg === null || p.heightCm === null || p.ageYears === null || !p.sex || !act) return null;
  const bmr = 10 * w.weightKg + 6.25 * p.heightCm - 5 * p.ageYears + (p.sex === 'male' ? 5 : -161);
  const tdee = bmr * act.factor;
  return { bmr: Math.round(bmr), low: Math.round((tdee * 0.9) / 10) * 10, high: Math.round((tdee * 1.1) / 10) * 10 };
}

function renderCalorieLimits() {
  const ul = document.getElementById('calorie-limits');
  if (!ul) return;
  ul.innerHTML = '';
  for (let i = 1; i <= 5; i++) {
    const li = document.createElement('li');
    const span = document.createElement('span');
    span.textContent = t('calorie.limit' + i);
    li.appendChild(span);
    ul.appendChild(li);
  }
}

function renderCalorieInputs() {
  const box = document.getElementById('calorie-inputs');
  if (!box) return;
  const p = state.profile || {};
  box.innerHTML = '';
  const grid = document.createElement('div');
  grid.className = 'field-grid';

  const imperial = bodyUnits() === 'imperial';
  const heightShown = p.heightCm === null ? ''
    : Math.round((imperial ? p.heightCm / CM_PER_IN : p.heightCm) * 10) / 10;
  grid.appendChild(buildField('cal-height', t('calorie.inHeight') + ' (' + (imperial ? t('units.in') : t('units.cm')) + ')', heightShown));
  grid.appendChild(buildField('cal-age', t('calorie.inAge') + ' (' + t('calorie.years') + ')', p.ageYears === null ? '' : p.ageYears, { step: '1' }));
  grid.appendChild(buildSelect('cal-sex', t('calorie.inSex'), [
    { value: '', label: t('calorie.sexPick') },
    { value: 'male', label: t('calorie.sexMale') },
    { value: 'female', label: t('calorie.sexFemale') },
  ], p.sex || ''));
  grid.appendChild(buildSelect('cal-activity', t('calorie.inActivity'),
    [{ value: '', label: t('calorie.activityPick') }].concat(ACTIVITY_LEVELS.map((a) => ({ value: a.id, label: t(a.key) }))),
    p.activity || ''));

  const w = latestMeasuredWeightKg();
  const wField = buildField('cal-weight', t('calorie.inWeight') + ' (' + weightUnitLabel() + ')', '', { });
  const wInput = wField.querySelector('input');
  wInput.disabled = true;
  wInput.value = w ? String(Math.round((imperial ? w.weightKg / KG_PER_LB : w.weightKg) * 10) / 10) : '';
  grid.appendChild(wField);
  box.appendChild(grid);

  const wHint = document.createElement('p');
  wHint.className = 'card-note';
  wHint.textContent = w
    ? t('calorie.weightFromLog', { date: formatDate(w.date) })
    : t('calorie.weightMissing');
  box.appendChild(wHint);

  const err = document.createElement('p');
  err.className = 'card-note form-error';
  err.id = 'calorie-error';
  err.hidden = true;
  box.appendChild(err);

  const save = document.createElement('button');
  save.type = 'button';
  save.className = 'btn btn-primary btn-block';
  save.id = 'btn-calorie-save';
  save.textContent = t('calorie.saveInputs');
  save.addEventListener('click', saveCalorieInputs);
  box.appendChild(save);
}

function saveCalorieInputs() {
  const err = document.getElementById('calorie-error');
  const fail = (msg) => { if (err) { err.textContent = msg; err.hidden = false; } };

  const heightRaw = document.getElementById('cal-height').value.trim();
  const ageRaw = document.getElementById('cal-age').value.trim();
  const sex = document.getElementById('cal-sex').value;
  const activity = document.getElementById('cal-activity').value;

  if (ageRaw !== '' && !(Number(ageRaw) >= 1 && Number(ageRaw) <= 120)) { fail(t('calorie.errAge')); return; }
  let heightCm = null;
  if (heightRaw !== '') {
    const n = Number(heightRaw);
    const cm = bodyUnits() === 'imperial' ? n * CM_PER_IN : n;
    if (!Number.isFinite(cm) || cm < 50 || cm > 260) { fail(t('calorie.errHeight')); return; }
    heightCm = Math.round(cm * 10) / 10;
  }

  state.profile.heightCm = heightCm;
  state.profile.ageYears = ageRaw === '' ? null : Math.round(Number(ageRaw));
  state.profile.sex = (sex === 'male' || sex === 'female') ? sex : null;
  state.profile.activity = ACTIVITY_LEVELS.some((a) => a.id === activity) ? activity : null;
  if (err) err.hidden = true;
  saveState();
  renderPokrok();
}

function renderCalorieCard() {
  const card = document.getElementById('body-calorie-card');
  const offCard = document.getElementById('calorie-off');
  if (!card) return;
  const on = state.settings.calorieEnabled === true;
  card.hidden = !on;
  if (offCard) offCard.hidden = on;
  if (!on) return;

  const p = state.profile || {};
  const chips = document.getElementById('calorie-adult-chips');
  if (chips) {
    chips.querySelectorAll('.metric-chip').forEach((b) => {
      const want = b.dataset.adult === 'yes';
      const sel = p.isAdult === want;
      b.classList.toggle('active', sel);
      b.setAttribute('aria-pressed', sel ? 'true' : 'false');
    });
  }

  const underage = document.getElementById('calorie-underage');
  const inputs = document.getElementById('calorie-inputs');
  const result = document.getElementById('calorie-result');
  const range = document.getElementById('calorie-range');
  const bmrLine = document.getElementById('calorie-bmr');
  const updated = document.getElementById('calorie-updated');

  /* Nezodpovedaná otázka: žiadne vstupy, žiadne čísla. */
  if (p.isAdult === null) {
    underage.hidden = true; inputs.hidden = true; result.hidden = true;
    return;
  }
  /* Menej ako 18: žiadne čísla, len krátke vysvetlenie. */
  if (p.isAdult === false) {
    underage.hidden = false;
    underage.textContent = t('calorie.underage');
    inputs.hidden = true;
    result.hidden = true;
    return;
  }

  underage.hidden = true;
  inputs.hidden = false;
  renderCalorieInputs();

  const est = calorieEstimate();
  if (!est) {
    const missing = calorieMissing();
    result.hidden = false;
    range.textContent = t('calorie.needInputs');
    bmrLine.textContent = missing.length ? t('calorie.missing', { list: missing.join(', ') }) : '';
    renderCalorieLimits();
    updated.textContent = '';
    return;
  }

  /* Počítadlo "naposledy vypočítané" sa obnoví len vtedy, keď sa zmenili vstupy. */
  const sig = calorieSignature();
  if (p.calcKey !== sig) {
    state.profile.calcKey = sig;
    state.profile.lastCalcAt = Date.now();
    saveState();
  }
  result.hidden = false;
  range.textContent = t('calorie.range', { low: est.low, high: est.high, unit: t('units.kcal') });
  bmrLine.textContent = t('calorie.bmrLine', { bmr: est.bmr, unit: t('units.kcal') });
  renderCalorieLimits();
  updated.textContent = t('calorie.updated', { when: formatWhen(state.profile.lastCalcAt) });
}

/* ---------- Tipy ---------- */
const TIP_KEYS = ['tips.t1', 'tips.t2', 'tips.t3', 'tips.t4', 'tips.t5'];
const FOOD_TIP_KEYS = ['tips.f1', 'tips.f2'];

function buildTips(ul, keys) {
  ul.innerHTML = '';
  for (const k of keys) {
    const li = document.createElement('li');
    const strong = document.createElement('strong');
    strong.textContent = t(k + 'Title');
    const span = document.createElement('span');
    span.textContent = t(k + 'Body');
    li.append(strong, span);
    ul.appendChild(li);
  }
}

function toggleTips(btnId, bodyId) {
  const btn = document.getElementById(btnId);
  const body = document.getElementById(bodyId);
  if (!btn || !body) return;
  const open = body.hidden;
  body.hidden = !open;
  btn.setAttribute('aria-expanded', open ? 'true' : 'false');
}

function renderTips() {
  const body = document.getElementById('tips-body');
  if (body && !body.dataset.built) {
    const ul = document.createElement('ul');
    ul.className = 'tip-list';
    body.appendChild(ul);
    body.dataset.built = '1';
  }
  if (body && body.firstChild) buildTips(body.firstChild, TIP_KEYS);

  const fbody = document.getElementById('food-tips-body');
  if (fbody && !fbody.dataset.built) {
    const ul = document.createElement('ul');
    ul.className = 'tip-list';
    fbody.appendChild(ul);
    fbody.dataset.built = '1';
  }
  if (fbody && fbody.firstChild) buildTips(fbody.firstChild, FOOD_TIP_KEYS);
}

/* ---------- Jedlo (voliteľný, ručne zapisovaný denník) ---------- */
function foodDayKey() { return foodDate || todayISO(); }

function renderSavedFoods() {
  const box = document.getElementById('food-saved');
  if (!box) return;
  box.innerHTML = '';
  const foods = state.foods || [];
  if (!foods.length) {
    const p = document.createElement('p');
    p.className = 'empty-state';
    p.textContent = t('food.noSaved');
    box.appendChild(p);
    return;
  }
  for (const f of foods) {
    const row = document.createElement('div');
    row.className = 'food-row';
    const main = document.createElement('div');
    main.className = 'food-row-main';
    const name = document.createElement('div');
    name.className = 'food-row-name';
    name.textContent = f.name;   // vlastný názov sa nikdy neprekladá
    const meta = document.createElement('div');
    meta.className = 'food-row-meta';
    meta.textContent = f.kcal + ' ' + t('units.kcal') + (f.protein || f.carbs || f.fat
      ? ' · ' + t('food.macroLine', { p: f.protein, c: f.carbs, f: f.fat }) : '');
    main.append(name, meta);
    const actions = document.createElement('div');
    actions.className = 'food-row-actions';
    const edit = document.createElement('button');
    edit.type = 'button';
    edit.className = 'btn-icon-sm';
    edit.textContent = '✏️';
    edit.title = t('food.editTemplate');
    edit.setAttribute('aria-label', t('food.editTemplate'));
    edit.addEventListener('click', () => openFoodModal('template', f.id));
    const del = document.createElement('button');
    del.type = 'button';
    del.className = 'btn-icon-sm btn-icon-danger';
    del.textContent = '🗑️';
    del.title = t('food.deleteTemplate');
    del.setAttribute('aria-label', t('food.deleteTemplate'));
    del.addEventListener('click', () => requestDeleteFood(f.id));
    actions.append(edit, del);
    row.append(main, actions);
    box.appendChild(row);
  }
}

function renderFoodEntries() {
  const box = document.getElementById('food-entries');
  if (!box) return;
  box.innerHTML = '';
  const key = foodDayKey();
  const entries = foodEntriesFor(key);
  if (!entries.length) {
    const p = document.createElement('p');
    p.className = 'empty-state';
    p.textContent = t('food.emptyDay');
    box.appendChild(p);
    return;
  }
  for (const e of entries) {
    const row = document.createElement('div');
    row.className = 'food-row';
    const main = document.createElement('div');
    main.className = 'food-row-main';
    const name = document.createElement('div');
    name.className = 'food-row-name';
    name.textContent = e.name;
    const meta = document.createElement('div');
    meta.className = 'food-row-meta';
    const q = Number(e.qty) > 0 ? Number(e.qty) : 1;
    meta.textContent = (q === 1 ? '' : q + ' × ') + Math.round(Number(e.kcal) * q) + ' ' + t('units.kcal')
      + ((e.protein || e.carbs || e.fat)
        ? ' · ' + t('food.macroLine', {
          p: Math.round(Number(e.protein) * q * 10) / 10,
          c: Math.round(Number(e.carbs) * q * 10) / 10,
          f: Math.round(Number(e.fat) * q * 10) / 10,
        }) : '');
    main.append(name, meta);
    const actions = document.createElement('div');
    actions.className = 'food-row-actions';
    const edit = document.createElement('button');
    edit.type = 'button';
    edit.className = 'btn-icon-sm';
    edit.textContent = '✏️';
    edit.title = t('food.editEntry');
    edit.setAttribute('aria-label', t('food.editEntry'));
    edit.addEventListener('click', () => openFoodModal('entry', e.id));
    const del = document.createElement('button');
    del.type = 'button';
    del.className = 'btn-icon-sm btn-icon-danger';
    del.textContent = '🗑️';
    del.title = t('food.deleteEntry');
    del.setAttribute('aria-label', t('food.deleteEntry'));
    del.addEventListener('click', () => requestDeleteFoodEntry(e.id));
    actions.append(edit, del);
    row.append(main, actions);
    box.appendChild(row);
  }
}

function renderFood() {
  const enabled = state.settings.foodLogEnabled === true;
  const off = document.getElementById('food-off');
  const on = document.getElementById('food-on');
  if (!off || !on) return;
  off.hidden = enabled;
  on.hidden = !enabled;
  if (!enabled) return;

  const key = foodDayKey();
  document.getElementById('food-date-label').textContent = formatDate(key);
  const entries = foodEntriesFor(key);
  const totals = foodTotals(entries);
  const parts = [totals.kcal + ' ' + t('units.kcal')];
  if (totals.protein || totals.carbs || totals.fat) {
    parts.push(t('food.macroLine', { p: totals.protein, c: totals.carbs, f: totals.fat }));
  }
  document.getElementById('food-totals').textContent = t('food.totalsLine', {
    total: parts.join(' · '),
    entries: tPlural('food.entries', entries.length),
  });
  renderFoodEntries();
  renderSavedFoods();
}

function shiftFoodDay(delta) {
  const d = parseDate(foodDayKey());
  d.setDate(d.getDate() + delta);
  foodDate = localDateKey(d);
  renderFood();
}

/* ---------- Jedlo: modal (záznam aj potravina) ---------- */
function renderFoodFields(values) {
  const box = document.getElementById('food-fields');
  if (!box) return;
  box.innerHTML = '';
  const grid = document.createElement('div');
  grid.className = 'field-grid';
  grid.appendChild(buildField('ff-name', t('food.nameLabel'), values.name, { text: true, wide: true }));
  grid.appendChild(buildField('ff-kcal', t('food.kcalLabel') + ' (' + t('units.kcal') + ')', values.kcal, { step: '1' }));
  grid.appendChild(buildField('ff-protein', t('food.protein') + ' (' + t('units.g') + ')', values.protein));
  grid.appendChild(buildField('ff-carbs', t('food.carbs') + ' (' + t('units.g') + ')', values.carbs));
  grid.appendChild(buildField('ff-fat', t('food.fat') + ' (' + t('units.g') + ')', values.fat));
  box.appendChild(grid);
}

function openFoodModal(mode, id) {
  foodModalMode = mode === 'template' ? 'template' : 'entry';
  foodModalId = id || null;
  const isTemplate = foodModalMode === 'template';
  const key = foodDayKey();

  const pickRow = document.getElementById('food-pick-row');
  const extra = document.getElementById('food-entry-extra');
  pickRow.hidden = isTemplate || !(state.foods || []).length;
  extra.hidden = isTemplate;

  document.getElementById('food-modal-title').textContent = t(isTemplate
    ? (id ? 'food.editTemplateTitle' : 'food.newTemplateTitle')
    : (id ? 'food.editEntryTitle' : 'food.addTitle'));

  let values = { name: '', kcal: '', protein: '', carbs: '', fat: '' };
  if (isTemplate && id) {
    const f = foodById(id);
    if (f) values = { name: f.name, kcal: f.kcal, protein: f.protein, carbs: f.carbs, fat: f.fat };
  } else if (!isTemplate && id) {
    const e = foodEntriesFor(key).find((x) => x.id === id);
    if (e) values = { name: e.name, kcal: e.kcal, protein: e.protein, carbs: e.carbs, fat: e.fat };
  }
  renderFoodFields(values);

  const pick = document.getElementById('food-pick');
  pick.innerHTML = '';
  const none = document.createElement('option');
  none.value = '';
  none.textContent = t('food.pickNone');
  pick.appendChild(none);
  for (const f of state.foods || []) {
    const opt = document.createElement('option');
    opt.value = f.id;
    opt.textContent = f.name + ' · ' + f.kcal + ' ' + t('units.kcal');
    pick.appendChild(opt);
  }

  let qty = '1';
  if (!isTemplate && id) {
    const e = foodEntriesFor(key).find((x) => x.id === id);
    if (e) qty = String(e.qty);
  }
  document.getElementById('food-qty').value = qty;
  document.getElementById('food-save-template').checked = false;
  document.getElementById('food-error').hidden = true;
  document.getElementById('modal-food').hidden = false;
  refreshUpdateBanner();
}

function saveFoodModal() {
  const err = document.getElementById('food-error');
  const fail = (msg) => { if (err) { err.textContent = msg; err.hidden = false; } };
  const name = document.getElementById('ff-name').value.trim();
  if (!name) { fail(t('food.errName')); return; }

  const readNum = (id) => {
    const raw = document.getElementById(id).value.trim();
    if (raw === '') return 0;
    const n = Number(raw);
    return Number.isFinite(n) ? n : NaN;
  };
  const kcal = readNum('ff-kcal'), protein = readNum('ff-protein'), carbs = readNum('ff-carbs'), fat = readNum('ff-fat');
  const okNum = (n, max) => Number.isFinite(n) && n >= 0 && n <= max;
  if (!okNum(kcal, 100000) || !okNum(protein, 10000) || !okNum(carbs, 10000) || !okNum(fat, 10000)) {
    fail(t('food.errNumber'));
    return;
  }

  if (foodModalMode === 'template') {
    if (foodModalId) {
      const f = foodById(foodModalId);
      if (f) Object.assign(f, { name, kcal, protein, carbs, fat });
    } else {
      state.foods.push({ id: uid(), name, kcal, protein, carbs, fat });
    }
  } else {
    const qtyRaw = Number(document.getElementById('food-qty').value);
    if (!Number.isFinite(qtyRaw) || qtyRaw <= 0 || qtyRaw > 1000) { fail(t('food.errQty')); return; }
    const qty = Math.round(qtyRaw * 100) / 100;
    const key = foodDayKey();
    const pickId = document.getElementById('food-pick').value || null;
    const entry = {
      id: foodModalId || uid(),
      foodId: foodModalId
        ? ((foodEntriesFor(key).find((x) => x.id === foodModalId) || {}).foodId || null)
        : (foodById(pickId) ? pickId : null),
      name, kcal, protein, carbs, fat, qty,
    };
    if (!Array.isArray(state.foodLog[key])) state.foodLog[key] = [];
    const at = foodModalId ? state.foodLog[key].findIndex((x) => x.id === foodModalId) : -1;
    if (at >= 0) state.foodLog[key][at] = entry;
    else state.foodLog[key].push(entry);

    if (document.getElementById('food-save-template').checked) {
      const exists = (state.foods || []).some((f) => f.name.toLowerCase() === name.toLowerCase());
      if (!exists) state.foods.push({ id: uid(), name, kcal, protein, carbs, fat });
    }
  }

  foodModalId = null;
  saveState();
  document.getElementById('modal-food').hidden = true;
  renderPokrok();
  refreshUpdateBanner();
}

function requestDeleteFoodEntry(id) {
  const key = foodDayKey();
  const entry = foodEntriesFor(key).find((x) => x.id === id);
  if (!entry) return;
  showGeneric(t('food.deleteEntry'), t('common.delete'), () => {
    state.foodLog[key] = foodEntriesFor(key).filter((x) => x.id !== id);
    if (!state.foodLog[key].length) delete state.foodLog[key];
    saveState();
    renderPokrok();
  }, t('food.deleteEntryConfirm', { name: entry.name }));
}

function requestDeleteFood(id) {
  const f = foodById(id);
  if (!f) return;
  showGeneric(t('food.deleteTemplate'), t('common.delete'), () => {
    /* Záznamy v denníku si nesú vlastnú kópiu hodnôt, takže história zostáva nezmenená. */
    state.foods = (state.foods || []).filter((x) => x.id !== id);
    saveState();
    renderPokrok();
  }, t('food.deleteTemplateConfirm', { name: f.name }));
}

/* ---------- Telo: kalkulačka telesného tuku (US Navy, obvody v cm) ---------- */
/* Rozpracované vstupy (zobrazované jednotky) prežijú prekreslenie; po uložení alebo zmene jednotiek sa zahodia. */
let bodyFatDraft = null;

/* Vráti { pct } alebo { err: 'fill' | 'neck' | 'range', pct? }. Vstupy v cm; boky len pre ženy. */
function bodyFatNavy(sex, heightCm, neckCm, waistCm, hipCm) {
  const num = (v) => (Number.isFinite(v) && v > 0 ? v : null);
  const h = num(heightCm), nk = num(neckCm), w = num(waistCm), hp = num(hipCm);
  if ((sex !== 'male' && sex !== 'female') || !h || !nk || !w || (sex === 'female' && !hp)) return { err: 'fill' };
  const girth = sex === 'male' ? w - nk : w + hp - nk;
  if (girth <= 0) return { err: 'neck' };
  const pct = sex === 'male'
    ? 495 / (1.0324 - 0.19077 * Math.log10(girth) + 0.15456 * Math.log10(h)) - 450
    : 495 / (1.29579 - 0.35004 * Math.log10(girth) + 0.22100 * Math.log10(h)) - 450;
  const rounded = Math.round(pct * 10) / 10;
  if (!Number.isFinite(rounded) || rounded < MEASURE_LIMITS.bodyFatPct[0] || rounded > MEASURE_LIMITS.bodyFatPct[1]) {
    return { err: 'range', pct: rounded };
  }
  return { pct: rounded };
}

/* Prečíta vstupy kalkulačky a prepočíta do cm (null = prázdne alebo neplatné). */
function bodyFatReadInputs() {
  const val = (id) => {
    const el = document.getElementById(id);
    const raw = el ? el.value.trim() : '';
    const n = raw === '' ? NaN : Number(raw);
    return Number.isFinite(n) && n > 0 ? lengthFromDisplay(n) : null;
  };
  const sexEl = document.getElementById('bf-sex');
  return {
    date: (document.getElementById('bf-date') || {}).value || '',
    sex: sexEl ? sexEl.value : '',
    heightCm: val('bf-height'), neckCm: val('bf-neck'), waistCm: val('bf-waist'), hipCm: val('bf-hip'),
  };
}

function bodyFatExistingOn(date) {
  const same = (state.measurements || []).filter((m) => m.date === date);
  return same.length ? same[same.length - 1] : null;
}

function bodyFatRefresh() {
  const res = document.getElementById('bf-result');
  const save = document.getElementById('btn-bf-save');
  const upd = document.getElementById('bf-updates');
  if (!res || !save) return;
  const inp = bodyFatReadInputs();
  const hipWrap = document.getElementById('bf-hip') ? document.getElementById('bf-hip').closest('.field') : null;
  if (hipWrap) hipWrap.hidden = inp.sex !== 'female';
  const r = bodyFatNavy(inp.sex, inp.heightCm, inp.neckCm, inp.waistCm, inp.hipCm);
  res.classList.toggle('bf-bad', !!r.err && r.err !== 'fill');
  if (r.err === 'fill') res.textContent = t('bodyfat.fill');
  else if (r.err === 'neck') res.textContent = t('bodyfat.errNeck');
  else if (r.err === 'range') res.textContent = t('bodyfat.errOut', { pct: r.pct.toFixed(1) });
  else res.textContent = t('bodyfat.result', { pct: r.pct.toFixed(1) });
  save.disabled = !!r.err;
  const ex = isDateKey(inp.date) ? bodyFatExistingOn(inp.date) : null;
  if (upd) { upd.hidden = !ex; upd.textContent = ex ? t('bodyfat.updates', { date: formatDate(inp.date) }) : ''; }
  const shown = (id) => { const el = document.getElementById(id); return el ? el.value : ''; };
  bodyFatDraft = { date: inp.date, sex: inp.sex, height: shown('bf-height'), neck: shown('bf-neck'), waist: shown('bf-waist'), hip: shown('bf-hip') };
  const msg = document.getElementById('bf-msg');
  if (msg) msg.hidden = true;
}

function renderBodyFatCard() {
  const box = document.getElementById('bodyfat-box');
  if (!box) return;
  /* Prekreslenie počas písania nesmie zhodiť fokus ani rozpísané hodnoty. */
  if (box.contains(document.activeElement) && box.firstChild) return;
  const p = state.profile || {};
  const lastOf = (field) => { const s = measureSeries(field); return s.length ? s[s.length - 1].value : null; };
  const disp = (cm) => (cm === null || cm === undefined ? '' : Math.round(lengthToDisplay(cm) * 10) / 10);
  const d = bodyFatDraft || {
    date: todayISO(), sex: p.sex || '', height: disp(p.heightCm),
    neck: disp(lastOf('neckCm')), waist: disp(lastOf('waistCm')), hip: disp(lastOf('hipCm')),
  };
  box.innerHTML = '';
  const grid = document.createElement('div');
  grid.className = 'field-grid';
  const dateWrap = document.createElement('div');
  dateWrap.className = 'field field-wide';
  const dateLabel = document.createElement('label');
  dateLabel.setAttribute('for', 'bf-date');
  dateLabel.textContent = t('bodyfat.date');
  const dateInp = document.createElement('input');
  dateInp.type = 'date'; dateInp.id = 'bf-date'; dateInp.value = d.date;
  dateWrap.append(dateLabel, dateInp);
  grid.appendChild(dateWrap);
  grid.appendChild(buildSelect('bf-sex', t('calorie.inSex'), [
    { value: '', label: t('calorie.sexPick') },
    { value: 'male', label: t('calorie.sexMale') },
    { value: 'female', label: t('calorie.sexFemale') },
  ], d.sex));
  const unit = ' (' + lengthUnitLabel() + ')';
  grid.appendChild(buildField('bf-height', t('calorie.inHeight') + unit, d.height));
  grid.appendChild(buildField('bf-neck', t('body.f.neck') + unit, d.neck));
  grid.appendChild(buildField('bf-waist', t('body.f.waist') + unit, d.waist));
  grid.appendChild(buildField('bf-hip', t('body.f.hip') + unit, d.hip));
  box.appendChild(grid);

  const upd = document.createElement('p');
  upd.className = 'card-note'; upd.id = 'bf-updates'; upd.hidden = true;
  const res = document.createElement('p');
  res.className = 'bf-result'; res.id = 'bf-result';
  res.setAttribute('role', 'status'); res.setAttribute('aria-live', 'polite');
  const err = document.createElement('p');
  err.className = 'card-note form-error'; err.id = 'bf-error'; err.hidden = true;
  const msg = document.createElement('p');
  msg.className = 'card-note'; msg.id = 'bf-msg'; msg.setAttribute('role', 'status');
  msg.hidden = true;
  const save = document.createElement('button');
  save.type = 'button'; save.className = 'btn btn-primary btn-block'; save.id = 'btn-bf-save';
  save.textContent = t('bodyfat.save');
  save.addEventListener('click', saveBodyFat);
  box.append(upd, res, err, save, msg);
  box.querySelectorAll('input, select').forEach((el) => {
    el.addEventListener('input', bodyFatRefresh);
    el.addEventListener('change', bodyFatRefresh);
  });
  bodyFatRefresh();
}

function saveBodyFat() {
  const err = document.getElementById('bf-error');
  const fail = (m) => { if (err) { err.textContent = m; err.hidden = false; } };
  const inp = bodyFatReadInputs();
  if (!isDateKey(inp.date)) { fail(t('body.errDate')); return; }
  if (inp.heightCm < 50 || inp.heightCm > 260) { fail(t('calorie.errHeight')); return; }
  const r = bodyFatNavy(inp.sex, inp.heightCm, inp.neckCm, inp.waistCm, inp.hipCm);
  if (r.err) return;
  if (err) err.hidden = true;

  /* Výška a pohlavie sa uložia do profilu ako pri kalorickom odhade. */
  state.profile.heightCm = Math.round(inp.heightCm * 10) / 10;
  state.profile.sex = inp.sex;

  let entry = bodyFatExistingOn(inp.date);
  if (!entry) {
    entry = { id: uid(), date: inp.date, note: '' };
    for (const f of MEASURE_FIELDS) entry[f] = null;
    state.measurements.push(entry);
  }
  entry.neckCm = cleanMeasureValue('neckCm', inp.neckCm);
  entry.waistCm = cleanMeasureValue('waistCm', inp.waistCm);
  if (inp.sex === 'female') entry.hipCm = cleanMeasureValue('hipCm', inp.hipCm);
  entry.bodyFatPct = r.pct;
  measureExtraRestore(state, true);
  reconcileAchievements();
  saveState();
  bodyFatDraft = null;
  const savedMsg = t('bodyfat.saved', { date: formatDate(inp.date) });
  renderPokrok();
  bodyFatRefresh();   // poznámka „bude aktualizované“ po uložení nesmie zostať zastaraná
  bodyFatDraft = null;
  const msg = document.getElementById('bf-msg');
  if (msg) { msg.textContent = savedMsg; msg.hidden = false; }
}

/* ---------- Telo + jedlo: jedno prekreslenie ---------- */
function renderBody() {
  renderBodyUnits();
  renderBodySummary();
  renderBodyChart();
  renderBodyCompare();
  renderBodyFatCard();
  renderCalorieCard();
  renderBodyHistory();
  renderTips();
  renderStorageNotice('body-storage-notice');
}

function renderFoodView() {
  renderFood();
  renderTips();
  renderStorageNotice('food-storage-notice');
}

const HISTORY_PAGE = 100;
let historyLimit = HISTORY_PAGE;   // koľko riadkov Histórie je vykreslených (dlhá história po stránkach)
function renderPokrok() {
  renderPokrokSubtabs();
  renderBody();
  renderFoodView();
  renderPhotos();
  const week = workoutsInWeek(currentWeekKey());
  const month = workoutsInMonth(currentMonthKey());
  const total = state.history.length;

  document.getElementById('stat-week').textContent = week;
  document.getElementById('stat-month').textContent = month;
  document.getElementById('stat-total').textContent = total;

  const records = document.getElementById('records-list');
  records.innerHTML = '';
  const recs = personalRecords();
  if (!recs.length) {
    records.innerHTML = `<p class="empty-state">${t('pokrok.recordsEmpty')}</p>`;
  } else {
    /* Identita cviku pre každý rekord (jeden prechod históriou), aby riadok mohol otvoriť jeho progres. */
    const idByName = new Map();
    for (const w of state.history) for (const e of w.exercises) if (e && !idByName.has(e.name)) idByName.set(e.name, entryIdentity(e));
    for (const r of recs) {
      const next = Math.floor(r.weight / 5) * 5 + 5;
      const xid = idByName.get(r.name) || null;
      const row = document.createElement(xid ? 'button' : 'div');
      row.className = 'record-row';
      if (xid) {
        row.type = 'button';
        row.dataset.xid = xid;
        row.dataset.xname = r.name;
        /* Bez aria-label: prístupný názov tlačidla je jeho obsah (názov, váha, dátum), inak by ho nahradil. */
      }
      row.innerHTML = `
        <span class="record-main">
          <span class="record-name">${esc(r.name)}</span>
          <span class="record-meta">${tPlural('pokrok.setsCount', r.reps)} · ${formatDate(r.date)}</span>
          <span class="record-meta">${t('pokrok.nextMilestone', { kg: next })}</span>
        </span>
        <span class="record-weight">${r.weight} ${t('units.kg')}</span>`;
      records.appendChild(row);
    }
  }

  const history = document.getElementById('history-list');
  history.innerHTML = '';
  if (!state.history.length && !(state.importedHistory || []).length) {
    history.innerHTML = `<p class="empty-state">${t('pokrok.historyEmpty')}</p>`;
  } else {
    /* Skutočné aj importované tréningy v jednom zozname podľa dátumu; import má vlastný riadok (bez XP a úpravy). */
    const sorted = [...state.history, ...(state.importedHistory || [])].sort((a, b) => (a.date < b.date ? 1 : a.date > b.date ? -1 : 0));
    /* Dlhá história (napr. 5 000 importov): vykreslí sa prvých historyLimit riadkov a tlačidlo "Zobraziť viac" (+100). */
    for (const w of sorted.slice(0, historyLimit)) {
      if (isImportedWorkout(w)) { history.appendChild(importedHistoryRow(w)); continue; }
      const setsDone = w.exercises.reduce((s, ex) => s + exerciseSlotCount(ex), 0);
      const row = document.createElement('div');
      row.className = 'history-row';
      const detail = historyGroupWrap(w.exercises, w.exercises.map(e => historyExerciseDetail(e)), '<br>');
      row.innerHTML = `
        <div class="history-main">
          <div class="history-name">${esc(historyPlanName(w))}</div>
          ${w.trainedWith ? `<div class="history-detail train-with">👥 ${esc(t('train.trainedWith', { name: w.trainedWith }))}</div>` : ''}
          <div class="history-detail">${formatDate(w.date)} · ${tPlural('pokrok.setsCount', setsDone)}</div>
          ${historyDurationLine(w)}
          ${historyWorkoutPhasesHtml(w)}
          <div class="history-detail">${detail}</div>
          ${w.note ? `<div class="history-note">“${esc(w.note)}”</div>` : ''}
        </div>
        <div class="history-side">
          <div class="history-xp">+${historyEntryXp(w)} ${t('units.xp')}</div>
          <div class="history-actions">
            <button class="btn-icon-sm" data-action="edit" title="${t('history.editTitle')}">✏️</button>
            <button class="btn-icon-sm btn-icon-danger" data-action="delete" title="${t('history.deleteTitle')}">🗑️</button>
          </div>
        </div>`;
      row.querySelector('[data-action="edit"]').addEventListener('click', () => openHistoryEdit(w.id));
      row.querySelector('[data-action="delete"]').addEventListener('click', () => requestDeleteWorkout(w.id));
      history.appendChild(row);
    }
    if (sorted.length > historyLimit) {
      const more = document.createElement('button');
      more.type = 'button';
      more.className = 'btn btn-secondary btn-block';
      more.dataset.historyMore = '1';
      more.textContent = t('history.showMore');
      more.addEventListener('click', () => {
        historyLimit += HISTORY_PAGE;
        renderPokrok();
        const nb = document.querySelector('#history-list [data-history-more]');
        if (nb) { try { nb.focus({ preventScroll: true }); } catch (e) { /* bez fokusu */ } }
      });
      history.appendChild(more);
    }
  }

  renderActivities();
}

function esc(s) {
  return String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
}

/* ---------- Vykreslenie: MOTIVÁCIA ---------- */

function renderMotivacia() {
  const info = levelInfo();

  document.getElementById('level-value').textContent = info.level;
  document.getElementById('header-level').textContent = `${t('header.level')} ${info.level}`;
  document.getElementById('level-progress').style.width = `${(info.levelXP / info.total) * 100}%`;
  document.getElementById('level-sub').textContent = t('motivacia.levelSub', { xp: info.xp, left: info.total - info.levelXP });

  const list = document.getElementById('achievements-list');
  list.innerHTML = '';
  const defs = staticAchievementDefs();
  // míľniky (5 kg) — zoradené podľa názvu cviku
  const milestones = Object.entries(state.achievements)
    .filter(([id]) => id.startsWith('ms-'))
    .sort((a, b) => a[0].localeCompare(b[0]));

  for (const def of defs) {
    const done = !!state.achievements[def.id];
    const date = done ? state.achievements[def.id] : null;
    const div = document.createElement('div');
    div.className = 'achievement' + (done ? ' unlocked' : '');
    div.dataset.category = def.category;
    div.dataset.achievementId = def.id;
    div.innerHTML = `
      <span class="achievement-icon">${def.icon}</span>
      <span class="achievement-name">${t(def.nameKey, { n: def.n })}</span>
      <span class="achievement-desc">${t(def.descKey, { g: weeklyGoal(), n: def.n })}</span>
      ${def.xp ? `<span class="achievement-xp"><bdi>${t('motivacia.xpReward', { xp: def.xp })}</bdi></span>` : ''}
      ${done ? `<span class="achievement-date">${t('motivacia.unlocked', { date: formatDate(date) })}</span>` : ''}`;
    list.appendChild(div);
  }

  /* Predchádzajúce odznaky: získané podľa starých pravidiel, ktoré nie sú v novej tabuľke. Zostávajú, bez XP. */
  const newIds = new Set(defs.map((d) => d.id));
  const earlier = LEGACY_ACHIEVEMENT_DEFS.filter((d) => !newIds.has(d.id) && state.achievements[d.id]);
  if (earlier.length) {
    const head = document.createElement('p');
    head.className = 'achievements-sub';
    head.id = 'achievements-earlier';
    head.textContent = t('ach2.earlier');
    list.appendChild(head);
    for (const def of earlier) {
      const div = document.createElement('div');
      div.className = 'achievement unlocked earlier';
      div.dataset.category = def.category;
      div.dataset.achievementId = def.id;
      div.innerHTML = `
        <span class="achievement-icon">${def.icon}</span>
        <span class="achievement-name">${t(def.nameKey)}</span>
        <span class="achievement-desc">${t(def.descKey, { g: weeklyGoal() })}</span>
        <span class="achievement-date">${t('motivacia.unlocked', { date: formatDate(state.achievements[def.id]) })}</span>`;
      list.appendChild(div);
    }
  }

  for (const [id, date] of milestones) {
    const parts = id.split('-');
    const kg = parts[parts.length - 1];
    const rawName = parts.slice(1, -1).join('-');
    const name = recordedNameToDisplay(rawName);
    const div = document.createElement('div');
    div.className = 'achievement unlocked';
    div.innerHTML = `
      <span class="achievement-icon">🏋️</span>
      <span class="achievement-name">${esc(name)} · ${kg} ${t('units.kg')}</span>
      <span class="achievement-desc">${t('motivacia.ach.5kg', { name, kg })}</span>
      <span class="achievement-date">${t('motivacia.unlocked', { date: formatDate(date) })}</span>`;
    list.appendChild(div);
  }
}

/* ---------- Vykreslenie: KALENDÁR ---------- */

/* Jedna O(n) prechádzka históriou na mapu podľa lokálneho dátumu. */
function historyByDate() {
  const map = {};
  for (const w of state.history) {
    if (!w || !w.date) continue;
    if (!map[w.date]) map[w.date] = [];
    map[w.date].push(w);
  }
  return map;
}

/* Jedna O(n) prechádzka aktivitami na mapu podľa lokálneho dátumu. */
function activitiesByDate() {
  const map = {};
  for (const a of (state.activities || [])) {
    if (!a || !a.date) continue;
    if (!map[a.date]) map[a.date] = [];
    map[a.date].push(a);
  }
  return map;
}

/* Jedna O(n) prechádzka úspechmi na mapu podľa dátumu odomknutia. */
function achievementsByDate() {
  const map = {};
  for (const [id, date] of Object.entries(state.achievements || {})) {
    if (!date) continue;
    if (!map[date]) map[date] = [];
    map[date].push(id);
  }
  return map;
}

/* Jednotný čitateľný názov úspechu (statické + 5 kg míľniky). */
function achievementLabel(id) {
  if (id.indexOf('ms-') === 0) {
    const parts = id.split('-');
    const kg = parts[parts.length - 1];
    const name = recordedNameToDisplay(parts.slice(1, -1).join('-'));
    return t('motivacia.ach.5kg', { name, kg });
  }
  const def = allAchievementDefs().find(d => d.id === id);
  return def ? `${def.icon} ${t(def.nameKey, { n: def.n })}` : id;
}

/* Názov cviku v histórii: podľa stabilného exId, inak podľa zaznamenaného názvu. */
function historyExerciseName(ex) {
  if (ex.exId && BUILTIN_EXERCISE_IDS.has(ex.exId)) return t('exercise.' + ex.exId);
  return recordedNameToDisplay(ex.name);
}

/* "Ľavá a pravá" / "iba ľavá" / "iba pravá" / "žiadna". */
function completedSidesLabel(done) {
  const hasLeft = done.left.length > 0;
  const hasRight = done.right.length > 0;
  if (hasLeft && hasRight) return t('unilateral.bothSides');
  if (hasLeft) return t('unilateral.leftOnly');
  if (hasRight) return t('unilateral.rightOnly');
  return t('unilateral.noneSides');
}

/* Zoznam zlyhaní po stranách: "Séria 3 — Pravá, Séria 1 — Ľavá". */
function sideFailureList(fails) {
  const parts = [];
  for (const side of ['left', 'right']) {
    for (const n of fails[side]) parts.push(t('unilateral.setSide', { n, side: sideName(side) }));
  }
  return parts.join(', ');
}

/* Jeden riadok cviku v histórii (Progress). Jednostranný cvik ukáže "na každú stranu",
   dokončené strany a zlyhania po stranách; bežný cvik vyzerá presne ako doteraz. */
function historyExerciseDetail(ex, displayName) {
  if (ex && ex.unilateral === true) {
    const sets = Math.round(Number(ex.sets)) || 0;
    const done = cleanSideSets(ex.sidesDone, sets);
    const fails = cleanSideSets(ex.sidesFailure, sets);
    const head = `${exProgLinkHtml(ex, displayName !== undefined ? displayName : ex.name)} `
      + `${esc(tPlural('unilateral.setsPerSide', sets))} · ${esc(historyRepsValue(ex))} ${t('units.reps')} · ${historyWeightText(ex)}`;
    let out = head + `<div class="history-side-note">${esc(t('unilateral.completed', { sides: completedSidesLabel(done) }))}</div>`;
    const list = sideFailureList(fails);
    if (list) out += `<div class="failure-note">🔥 ${esc(t('unilateral.failureList', { list }))}</div>`;
    return out + historyWarmupsHtml(ex, 'div') + historyEffortHtml(ex, 'div') + historyDropsHtml(ex, 'div');
  }
  const line = `${exProgLinkHtml(ex, displayName !== undefined ? displayName : ex.name)} ${ex.sets}×${esc(historyRepsValue(ex))} · ${historyWeightText(ex)}`;
  const fSets = cleanFailureSets(ex.actualFailureSets, ex.sets);
  /* Zlyhanie sa zobrazuje len vtedy, keď bolo naozaj zaznamenané – nikdy z plánu. */
  return (fSets.length
    ? line + `<div class="failure-note">🔥 ${esc(t('failure.sets', { sets: fSets.join(', ') }))}</div>`
    : line) + historyWarmupsHtml(ex, 'div') + historyEffortHtml(ex, 'div') + historyDropsHtml(ex, 'div');
}
/* Riadok s drop sériami v histórii / kalendári (alebo prázdny reťazec). */
function historyDropsHtml(ex, tag) {
  const text = historyDropsText(ex);
  return text ? `<${tag} class="drop-note">⬇ ${esc(text)}</${tag}>` : '';
}

/* Trvanie uložené v histórii: nezáporné celé sekundy, inak null (nikdy nevymýšľame hodnotu).
   Staré tréningy bez durationSeconds zostávajú bez trvania a zobrazia sa normálne. */
function cleanDurationSeconds(value) {
  if (typeof value !== 'number' || !Number.isFinite(value) || value < 0) return null;
  return Math.round(value);
}

/* Riadok s trvaním pre históriu aj detail dňa v kalendári – len ak trvanie naozaj existuje. */
function historyDurationLine(w) {
  const seconds = cleanDurationSeconds(w && w.durationSeconds);
  if (seconds === null) return '';
  return `<div class="history-duration">${esc(t('history.duration', { duration: formatDurationNatural(seconds) }))}</div>`;
}

function monthTitle() {
  return fillDatePattern(localeData().titlePattern, new Date(viewYear, viewMonth, 1), '');
}

/* Krátky text stavu dňa – používa ho aria-label aj detail dňa. */
function dayStatusText(key, count) {
  if (count > 0) return t('kalendar.statusWorkout');
  if (key > todayISO()) return t('kalendar.statusFuture');
  if (key === todayISO()) return t('kalendar.statusTodayNone');
  return t('kalendar.statusNone');
}

function renderKalendar() {
  const byDate = historyByDate();
  const impByDate = importedByDate();
  const byActs = activitiesByDate();
  const today = todayISO();
  const lang = activeLang();

  document.getElementById('calendar-title').textContent = monthTitle();

  const wd = document.getElementById('calendar-weekdays');
  wd.innerHTML = '';
  for (const label of localeData().weekdaysShort) {
    const el = document.createElement('span');
    el.className = 'calendar-weekday';
    el.textContent = label;
    wd.appendChild(el);
  }

  const daysInMonth = new Date(viewYear, viewMonth + 1, 0).getDate();
  const lead = mondayIndex(new Date(viewYear, viewMonth, 1));
  const totalCells = Math.ceil((lead + daysInMonth) / 7) * 7;

  const grid = document.getElementById('calendar-grid');
  grid.innerHTML = '';
  for (let i = 0; i < totalCells; i++) {
    const dayNum = i - lead + 1;
    const outside = dayNum < 1 || dayNum > daysInMonth;
    /* Aj deň z vedľajšieho mesiaca sa počíta z AKTUÁLNEHO celého dátumu (rok/mesiac/deň),
       takže jeho stav nikdy nezdieľa rovnaké číslo dňa v inom mesiaci. */
    const date = dayNum < 1
      ? new Date(viewYear, viewMonth, dayNum)
      : (dayNum > daysInMonth ? new Date(viewYear, viewMonth + 1, dayNum - daysInMonth) : new Date(viewYear, viewMonth, dayNum));
    const key = localDateKey(date);
    const workouts = byDate[key] || [];
    const count = workouts.length + ((byActs[key] || []).length);
    const impCount = (impByDate[key] || []).length;   // importy: len neutrálna značka, nikdy zelený deň
    const isToday = key === today;
    const isFuture = key > today;
    const status = !count && impCount ? t('imp.status') : dayStatusText(key, count);   // import nie je "dokončený tréning"

    const btn = document.createElement('button');
    btn.type = 'button';
    btn.dataset.day = key;
    btn.className = 'cal-cell'
      + (count ? ' cal-done' : (impCount ? ' cal-imp' : (isFuture || isToday ? '' : ' cal-miss')))
      + (isToday ? ' cal-today' : '')
      + (isFuture ? ' cal-future' : '')
      + (key === selectedDayKey ? ' cal-selected' : '')
      + (outside ? ' cal-outside' : '');
    let aria = t('kalendar.ariaDay', { date: formatFullDate(date), status });
    if (count + impCount > 1) aria += ' · ' + tPlural('kalendar.ariaWorkoutCount', count + impCount);
    btn.setAttribute('aria-label', aria);
    /* Každý deň z vedľajšieho mesiaca dostane krátky názov mesiaca, aby bolo jasné, kam tréning patrí. */
    const monthLabel = outside
      ? `<span class="cal-mon" aria-hidden="true">${esc(String(localeData().monthsShort[date.getMonth()]).replace(/\.$/, ''))}</span>` : '';
    btn.innerHTML = `<span class="cal-num">${date.getDate()}</span>` + monthLabel
      + (count + impCount > 1 ? `<span class="cal-badge">${count + impCount}</span>` : '');
    grid.appendChild(btn);
  }
}

function shiftMonth(delta) {
  const d = new Date(viewYear, viewMonth + delta, 1);   // Date vyrieši aj prechod rokov
  viewYear = d.getFullYear();
  viewMonth = d.getMonth();
  renderKalendar();
}

function goToCurrentMonth() {
  const n = new Date();
  viewYear = n.getFullYear();
  viewMonth = n.getMonth();
  renderKalendar();
}

function openDay(key) {
  selectedDayKey = key;
  if (activeTab === 'kalendar') renderKalendar();
  renderDayDetail(key);
  document.getElementById('modal-day').hidden = false;
  document.getElementById('btn-day-close').focus();
}

function closeDay() {
  document.getElementById('modal-day').hidden = true;
  refreshUpdateBanner();
}

function workoutBlock(w, opts) {
  const imported = !!(opts && opts.imported);   // import: bez XP, zdravia a zdieľania
  const div = document.createElement('div');
  div.className = 'day-workout';
  const rowParts = w.exercises.map(ex => {
    if (ex.unilateral === true) {
      const sets = Math.round(Number(ex.sets)) || 0;
      const done = cleanSideSets(ex.sidesDone, sets);
      const fails = cleanSideSets(ex.sidesFailure, sets);
      const list = sideFailureList(fails);
      return `
    <div class="day-ex">
      <span class="day-ex-name">${exProgLinkHtml(ex, historyExerciseName(ex))}</span>
      <span class="day-ex-meta">${esc(tPlural('unilateral.setsPerSide', sets))} · ${esc(historyRepsValue(ex))} ${t('units.reps')} · ${historyWeightText(ex)} · ${ex.setsDone} ${t('history.setsDoneLabel')}</span>
      <span class="day-ex-completed">${esc(t('unilateral.completed', { sides: completedSidesLabel(done) }))}</span>
      ${list ? `<span class="day-ex-failure">🔥 ${esc(t('unilateral.failureList', { list }))}</span>` : ''}
      ${historyWarmupsHtml(ex, 'span')}
      ${historyEffortHtml(ex, 'span')}
      ${historyDropsHtml(ex, 'span')}
    </div>`;
    }
    const fSets = cleanFailureSets(ex.actualFailureSets, ex.sets);
    return `
    <div class="day-ex">
      <span class="day-ex-name">${exProgLinkHtml(ex, historyExerciseName(ex))}</span>
      <span class="day-ex-meta">${ex.sets} × ${esc(historyRepsValue(ex))} · ${historyWeightText(ex)} · ${ex.setsDone} ${t('history.setsDoneLabel')}</span>
      ${fSets.length ? `<span class="day-ex-failure">🔥 ${esc(t('failure.sets', { sets: fSets.join(', ') }))}</span>` : ''}
      ${historyWarmupsHtml(ex, 'span')}
      ${historyEffortHtml(ex, 'span')}
      ${historyDropsHtml(ex, 'span')}
    </div>`;
  });
  const rows = historyGroupWrap(w.exercises, rowParts, '');
  div.innerHTML = `
    <div class="day-workout-head">
      <span class="day-workout-name">${esc(historyPlanName(w))}</span>
      ${imported ? '' : `<span class="day-workout-xp">+${historyEntryXp(w)} ${t('units.xp')}</span>`}
    </div>
    <div class="day-workout-date">${esc(formatDate(w.date))}</div>
    ${w.trainedWith ? `<div class="day-ex-meta train-with">👥 ${esc(t('train.trainedWith', { name: w.trainedWith }))}</div>` : ''}
    ${historyDurationLine(w)}
    ${historyWorkoutPhasesHtml(w)}
    ${imported ? '' : healthDayHtml(w)}
    ${rows}
    ${w.note ? `<div class="modal-note">“${esc(w.note)}”</div>` : ''}`;
  if (!imported && dayShareAvailable()) div.appendChild(dayShareBlock(w));
  return div;
}

/* Zdieľanie tréningu z kalendára: príspevok do Community (na schválenie) alebo správa
   priateľovi. Len keď je Community zapnutá a server má zdieľanie (0011). */
function dayShareAvailable() {
  return communityConfigured() && communityOptIn() && communityV5();
}
function dayShareBlock(w) {
  const box = document.createElement('div');
  box.className = 'day-share';
  const row = document.createElement('div');
  row.className = 'day-share-row';
  const toCommunity = document.createElement('button');
  toCommunity.type = 'button'; toCommunity.className = 'btn btn-secondary btn-sm day-share-community';
  toCommunity.textContent = t('share.resultButton');
  toCommunity.addEventListener('click', () => { closeDay(); shareWorkoutToCommunity(w.id); });
  const toFriend = document.createElement('button');
  toFriend.type = 'button'; toFriend.className = 'btn btn-secondary btn-sm day-share-friend';
  toFriend.textContent = t('share.toFriend');
  toFriend.setAttribute('aria-expanded', 'false');
  const picker = document.createElement('div');
  picker.className = 'day-share-friends';
  picker.hidden = true;
  toFriend.addEventListener('click', () => {
    const open = picker.hidden;
    picker.hidden = !open;
    toFriend.setAttribute('aria-expanded', open ? 'true' : 'false');
    if (open) dayShareLoadFriends(picker, w.id);
  });
  row.append(toCommunity, toFriend);
  box.append(row, picker);
  return box;
}
async function dayShareLoadFriends(picker, workoutId) {
  picker.innerHTML = `<p class="card-note">${esc(t('community.loading'))}</p>`;
  const sb = communityClient();
  let r;
  try { r = sb ? await sb.rpc('friends_list') : { error: { message: 'offline' } }; } catch (e) { r = { error: e }; }
  if (r.error) { picker.innerHTML = `<p class="card-note">${esc(communityErrText(r.error))}</p>`; return; }
  const friends = r.data || [];
  if (!friends.length) { picker.innerHTML = `<p class="card-note">${esc(t('share.noFriends'))}</p>`; return; }
  picker.innerHTML = `<p class="modal-label">${esc(t('share.pickFriend'))}</p><div class="day-share-list"></div>`;
  const list = picker.querySelector('.day-share-list');
  for (const f of friends) {
    const b = document.createElement('button');
    b.type = 'button'; b.className = 'btn btn-secondary btn-sm day-share-to';
    b.dataset.user = f.user_id;
    b.textContent = f.username || t('community.unknownUser');
    b.addEventListener('click', () => dayShareToFriend(picker, workoutId, f.user_id, f.username || t('community.unknownUser')));
    list.appendChild(b);
  }
}
async function dayShareToFriend(picker, workoutId, friendId, name) {
  const a = shareFromWorkout(state.history.find((x) => x.id === workoutId));
  const sb = communityClient();
  if (!a || !sb) return;
  picker.querySelectorAll('button').forEach((b) => { b.disabled = true; });
  let res;
  try {
    const user = await syncSessionUser();
    const chat = user ? await sb.rpc('open_chat', { p_friend: friendId }) : { error: { message: 'not_signed_in' } };
    res = chat.error ? chat : await sb.from('messages').insert({ conversation_id: chat.data, sender_id: user.id,
      body: shareSummaryText(a).slice(0, COMMUNITY_MESSAGE_MAX), attachment: a }).select('id,conversation_id').single();
  } catch (e) { res = { error: e }; }
  if (res.error) {
    picker.querySelectorAll('button').forEach((b) => { b.disabled = false; });
    let err = picker.querySelector('.day-share-error');
    if (!err) { err = document.createElement('p'); err.className = 'card-note day-share-error'; picker.appendChild(err); }
    err.textContent = communityErrText(res.error);
    return;
  }
  pushNotifyMessage(sb, res.data.id);
  const cid = res.data.conversation_id;
  picker.innerHTML = `<p class="day-share-sent">✓ ${esc(t('share.sentTo', { name }))}</p>`;
  const open = document.createElement('button');
  open.type = 'button'; open.className = 'btn btn-secondary btn-sm day-share-open';
  open.textContent = t('share.goToChat');
  open.addEventListener('click', () => { closeDay(); switchTab('komunita'); communityOpenChat(cid); });
  picker.appendChild(open);
}

function activityBlock(a) {
  const div = document.createElement('div');
  div.className = 'day-workout';
  const parts = [formatClock(a.activeSeconds)];
  if (a.distanceKm !== null) parts.push(formatDistanceValue(a.distanceKm));
  const pace = activityPaceOrSpeed(a);
  if (pace) parts.push(t(pace.type === 'speed' ? 'act.speed' : 'act.pace') + ': ' + pace.label);
  div.innerHTML = `
    <div class="day-workout-head">
      <span class="day-workout-name">${esc(activityKindLabel(a.kind))}</span>
      <span class="day-workout-xp">+${activityEntryXp(a)} ${t('units.xp')}</span>
    </div>
    <div class="day-workout-date">${esc(formatDate(a.date))}</div>
    <div class="day-ex-meta">${esc(parts.join(' · '))}</div>
    ${a.note ? `<div class="modal-note">“${esc(a.note)}”</div>` : ''}`;
  return div;
}

function renderDayDetail(key) {
  const date = parseDate(key);
  const today = todayISO();
  const isFuture = key > today;
  const workouts = historyByDate()[key] || [];
  const acts = activitiesByDate()[key] || [];
  const imported = importedByDate()[key] || [];
  const total = workouts.length + acts.length + imported.length;

  document.getElementById('day-title').textContent = formatFullDate(date);

  const statusEl = document.getElementById('day-status');
  statusEl.className = 'day-status ' + (total ? (workouts.length + acts.length ? 'day-status-done' : 'day-status-imp')
    : isFuture ? 'day-status-future'
    : key === today ? 'day-status-today' : 'day-status-miss');
  statusEl.textContent = !workouts.length && !acts.length && imported.length ? t('imp.status') : dayStatusText(key, workouts.length + acts.length);

  const body = document.getElementById('day-body');
  body.innerHTML = '';
  if (isFuture) {
    body.innerHTML = `<p class="card-note">${esc(t('kalendar.statusFuture'))}</p>`;
    return;
  }
  if (!total) {
    body.innerHTML = `<p class="card-note">${esc(t('kalendar.emptyPast'))}</p>`;
  } else {
    for (const w of workouts) body.appendChild(workoutBlock(w));
    for (const w of imported) body.appendChild(importedWorkoutBlock(w));
    for (const a of acts) body.appendChild(activityBlock(a));
  }
  healthHrChartsMount(body);

  const achIds = achievementsByDate()[key] || [];
  if (achIds.length) {
    const box = document.createElement('div');
    box.className = 'day-achievements';
    box.innerHTML = `<div class="day-label">${esc(t('kalendar.achievements'))}</div>`
      + achIds.map(id => `<div class="day-ach">${esc(achievementLabel(id))}</div>`).join('');
    body.appendChild(box);
  }
}

/* ---------- Celkové vykreslenie ---------- */

/* Jednorazová poznámka o novom výpočte XP (v101): len na tomto zariadení (localStorage, mimo stavu),
   len pre ľudí, ktorí mali históriu už pred touto verziou. Nový používateľ ju nikdy neuvidí. */
const XP_NOTE_KEY = 'gymquest_xp_note';
function renderXpNote() {
  const el = document.getElementById('xp-note');
  if (!el) return;
  let seen = null;
  try { seen = localStorage.getItem(XP_NOTE_KEY); } catch (e) {}
  const hasData = ((state.history || []).length || (state.activities || []).length) && !state.demo;
  if (seen === null && !hasData) {
    try { localStorage.setItem(XP_NOTE_KEY, 'new'); } catch (e) {}   // čerstvá inštalácia (aj ukážkové dáta): poznámku už nikdy
  }
  el.hidden = !(seen === null && hasData);
}
function dismissXpNote() {
  try { localStorage.setItem(XP_NOTE_KEY, '1'); } catch (e) {}
  const el = document.getElementById('xp-note');
  if (el) el.hidden = true;
  renderTourInvite();   // po odkliknutí poznámky príde na rad pozvánka na návod
}

function renderAll() {
  renderXpNote();
  renderTourInvite();   // až po poznámke o XP: obe naraz sa nikdy neukážu
  renderDnes();
  renderTrening();
  renderPokrok();
  renderMotivacia();
  /* Predvoľby časovača patria k obrazovke Tréning, ale jazyk aj zmena dát ich menia. */
  renderTimerPresets();
  renderCustomTimer();
  // Kalendár sa prekresľuje len keď je otvorený – zbytočne nepočítame iné obrazovky.
  if (activeTab === 'kalendar') renderKalendar();
  if (activeTab === 'ty') renderTy();   // jazyk, cieľ, príspevky
  // Otvorený detail dňa musí zareagovať na zmenu jazyka aj na zmenu histórie.
  const dayModal = document.getElementById('modal-day');
  if (dayModal && !dayModal.hidden && selectedDayKey) renderDayDetail(selectedDayKey);
  // Otvorený Full Body builder musí prekresliť zdroje a preklady (výber zostáva zachovaný).
  const fbModal = document.getElementById('modal-fullbody');
  if (fbModal && !fbModal.hidden) renderFullBodyBuilder();
  const progModal = document.getElementById('modal-programs');
  if (progModal && !progModal.hidden) renderPrograms();   // jazyk / zmena týždňa, aj rozpísané TM
  renderRestSoundSetting();   // stav Zapnuté/Vypnuté musí zareagovať na zmenu jazyka
  renderAutoRestSetting();
  renderEffortSetting();
  renderShowSuggestionsSetting();
  refreshUpdateBanner();   // aktualizácia sa môže ponúknuť, len ak nič neupravujeme
  const musclesModal = document.getElementById('modal-muscles');
  if (muState && musclesModal && !musclesModal.hidden) {
    muState.trend = muscleTrend(8);
    muState.maxOff = muscleMaxOffset();
    refreshMusclesMap();
    renderMuscles();
  }
}

/* ---------- Prepínanie kariet ---------- */

function switchTab(tab) {
  if (tab !== 'trening') closePracticeSheet();
  if (tab === 'spravy') { openMessagesTab(); return; }   // Bento: karta Správy = Community obrazovka v režime rozhovorov
  activeTab = tab;
  document.body.dataset.tab = tab;
  communityChatHashSync();
  for (const s of ['dnes', 'trening', 'pokrok', 'kalendar', 'komunita', 'ty']) {
    document.getElementById(`screen-${s}`).hidden = s !== tab;
  }
  /* Kalendár nie je v menu (v návrhu Bento sa otvára z dlaždíc) – zvýraznená ostáva karta, odkiaľ sa otvoril. */
  const navTab = tab === 'kalendar' ? calendarReturnTab : (tab === 'komunita' && communityMode === 'messages' ? 'spravy' : tab);
  document.querySelectorAll('.tab').forEach(el => {
    const on = el.dataset.tab === navTab;
    el.classList.toggle('active', on);
    if (el.closest('.tab-bar')) el.setAttribute('aria-current', on ? 'page' : 'false');
  });
  if (tab === 'dnes') renderDnes();
  if (tab === 'trening') renderTrening();
  if (tab === 'pokrok') renderPokrok();
  if (tab === 'kalendar') renderKalendar();
  if (tab === 'komunita') {
    document.getElementById('screen-komunita').classList.toggle('msg-mode', communityMode === 'messages');
    renderCommunity();
  }
  if (tab === 'ty') {
    const back = tyReturn; tyReturn = null;
    if (back) {   // návrat z príspevku / listu: rovnaký filter a posunutie, bez nového načítania
      tyFilter = back.filter;
      renderTy();
      requestAnimationFrame(() => window.scrollTo(0, back.y));
      if (tyFeed && Date.now() - tyLoadedAt > 60000) tyLoadedAt = 0;
    } else { renderTy(); tyLoad(true); }
  }
  updateStickyBottom();
  refreshUpdateBanner();
}

/* ---------- Ukončenie tréningu ---------- */

function finishWorkout() {
  const plan = currentPlan();
  if (!plan) return;
  const doneCount = totalSetsDone();
  const totalSets = planExerciseCount(plan);
  const xp = xpForNewWorkout(doneCount, todayISO(), phaseSnapshotForHistory(getSession()));
  const limited = xp === 0 && workoutXpFor(doneCount) > 0;   // 0 XP kvôli dennému limitu

  const confirmText = document.getElementById('confirm-text');
  confirmText.innerHTML = t('trening.confirmText', { plan: esc(planDisplayName(plan)), done: doneCount, total: totalSets, xp })
    + (limited ? '<br>' + esc(t('xp.dailyLimit')) : '');
  document.getElementById('confirm-note').value = '';
  document.getElementById('confirm-error').hidden = true;
  document.getElementById('modal-confirm').hidden = false;
  document.getElementById('confirm-note').focus();
}

/* Asistovaný cvik (číslo = pomoc v kg, nie záťaž): značka na riadku alebo asistovaný cvik z knižnice. */
function isAssisted(ex) {
  if (!ex) return false;
  if (ex.assisted === true) return true;
  const lib = libraryEntry(builtinExerciseId(ex));
  return !!(lib && lib.assisted === true);
}

/* Záznam v histórii je asistovaný: značka na zázname (pridaná pri uložení) alebo asistovaný cvik z knižnice (exId). */
function historyEntryAssisted(e) {
  if (!e) return false;
  if (e.assisted === true) return true;
  const lib = e.exId ? libraryEntry(e.exId) : null;
  return !!(lib && lib.assisted === true);
}

/* Text záťaže cviku: "25 kg" / pri asistovanom "Pomoc 25 kg". */
function exerciseLoadText(ex, weight) {
  const w = weight === undefined ? ex.weight : weight;
  return isAssisted(ex) ? t('assisted.line', { w: w + ' ' + t('units.kg') }) : w + ' ' + t('units.kg');
}

/* Identita riadku plánu: id zabudovaného cviku, cx-id (aj s príponou -N), inak odvodená z názvu. */
function exerciseRowIdentity(ex) {
  if (ex && typeof ex.id === 'string' && ex.id.indexOf('cx-') === 0 && !builtinExerciseId(ex)) return ex.id;
  return exerciseIdentity(ex);
}

/* Platný záznam settings.exerciseMemory pre identitu (váha 0..999, konečné číslo), inak null. */
function exerciseMemoryEntry(identity) {
  const mem = identity && state.settings && state.settings.exerciseMemory;
  if (!mem || typeof mem !== 'object' || !Object.prototype.hasOwnProperty.call(mem, identity)) return null;
  const m = mem[identity];
  if (!m || typeof m !== 'object') return null;
  const w = Number(m.weight);
  return typeof m.weight === 'number' && Number.isFinite(w) && w >= 0 && w <= 999 ? m : null;
}

/* Zapíše spoločné hodnoty cviku do riadkov plánov s rovnakou identitou a do settings.exerciseMemory.
   Váha patrí plánu (rozhodnutie vlastníka 2026-11-10): do riadka sa zapíše iba v pláne `planId`; v ostatných
   plánoch zostáva ich vlastná. Jednostrannosť, strana a asistencia sú vlastnosti cviku a platia všade.
   settings.exerciseMemory drží poslednú váhu ako predvoľbu pre nový riadok / rýchly tréning.
   Nevolá saveState; vráti true, ak sa niečo zmenilo (zmena => `at`). */
function applyExerciseDefaults(identity, values, at, planId) {
  if (!identity || !values) return false;
  const fields = ['weight', 'unilateral', 'startSide', 'assisted', 'muscles'].filter((f) => values[f] !== undefined);
  if (!fields.length) return false;
  let changed = false;
  const setField = (obj, f, v) => {
    if (f === 'muscles' ? JSON.stringify(obj[f] || null) !== JSON.stringify(v || null) : f === 'weight' ? obj[f] !== v : (v === false ? obj[f] !== undefined : obj[f] !== v)) {
      if (f !== 'weight' && v === false) delete obj[f]; else obj[f] = v;
      changed = true;
    }
  };
  for (const [pid, plan] of Object.entries(state.plans || {})) {
    if (!plan || !Array.isArray(plan.exercises)) continue;
    /* Zdvojený cvik v jednom pláne (pyramída, rozcvička) je zámer: spoločné hodnoty dostane len PRVÝ riadok. */
    const ex = plan.exercises.find((r) => r && exerciseRowIdentity(r) === identity);
    if (ex) for (const f of fields) if (f !== 'weight' || pid === planId) setField(ex, f, values[f]);
  }
  if (!state.settings.exerciseMemory || typeof state.settings.exerciseMemory !== 'object' || Array.isArray(state.settings.exerciseMemory)) {
    state.settings.exerciseMemory = {};
  }
  const mem = state.settings.exerciseMemory;
  const cur = Object.prototype.hasOwnProperty.call(mem, identity) && mem[identity] && typeof mem[identity] === 'object' ? mem[identity] : null;
  const next = Object.assign({}, cur);
  for (const f of fields) {
    if (f !== 'weight' && values[f] === false) delete next[f]; else next[f] = values[f];
  }
  if (changed || !cur || fields.some((f) => (cur[f] === undefined ? (f === 'weight' || values[f] !== false) : cur[f] !== values[f]))) {
    next.at = at;
    mem[identity] = next;
    changed = true;
  }
  return changed;
}
/* Samostatné volanie (jedno saveState => normálny nárast počítadla zmien, synchronizuje sa). */
function rememberExerciseDefaults(identity, values, at, planId) {
  const changed = applyExerciseDefaults(identity, values, at == null ? Date.now() : at, planId);
  if (changed) saveState();
  return changed;
}

/* Jeden cvik do histórie: setsDone aj actualFailureSets sa čítajú zo session cez stabilné
   kľúče cvikov, takže sa nikdy nemôžu pomiešať dva cviky s rovnakým menom ani stratiť
   po úprave plánu. `ex.name` je záznam názvu v čase tréningu – nemenný snapshot. */
function historyExerciseEntry(ex, sess) {
  const sides = exerciseSideOrder(ex);
  const entry = {
    name: ex.name,
    exId: (ex.id && BUILTIN_EXERCISE_IDS.has(ex.id)) ? ex.id : undefined,
    sets: sessionSetCount(ex),
    reps: ex.reps,
    weight: ex.weight,
    plannedFailureSets: cleanFailureSets(ex.plannedFailureSets, ex.sets),
  };
  if (!builtinExerciseId(ex)) {
    entry.customId = exerciseRowIdentity(ex);
    const profile = muscleProfile(ex);
    entry.muscles = { primary: profile.primary, secondary: profile.secondary.slice() };
    if (profile.primary === 'other' && (typeof ex.musclesAuto === 'boolean' || profile.source !== 'saved')) {
      entry.musclesAuto = profile.source === 'unknown' || ex.musclesAuto === true;
    }
  }
  /* Asistovaný cvik: značka na zázname (additívne), aby história ukazovala "Pomoc" aj po zmene plánu. */
  if (isAssisted(ex)) entry.assisted = true;
  if (groupIdOf(ex)) entry.group = ex.group;   // supersérie: skupina sa v histórii len zobrazuje
  if (sides) {
    /* Jednostranný cvik: každá strana sa zaznamenáva samostatne.
       setsDone zostáva SÚČET oboch strán – rovnaký význam ako pri bežnom cviku. */
    const doneSide = { left: [], right: [] };
    const failSide = { left: [], right: [] };
    for (let i = 0; i < sessionSetCount(ex); i++) {
      for (const side of sides) {
        if (sess && sess.completedSets[setSessionKey(ex, i, side)]) doneSide[side].push(i + 1);
        if (sess && sess.actualFailureSets[setSessionKey(ex, i, side)]) failSide[side].push(i + 1);
      }
    }
    const cleanDone = cleanSideSets(doneSide, sessionSetCount(ex));
    const cleanFails = cleanSideSets(failSide, sessionSetCount(ex));
    entry.unilateral = true;
    entry.startSide = ex.startSide === 'right' ? 'right' : 'left';
    entry.setsDone = cleanDone.left.length + cleanDone.right.length;
    entry.sidesDone = cleanDone;
    historyApplySetWeights(entry, ex, Array.from(new Set(cleanDone.left.concat(cleanDone.right))));
    historyApplySetReps(entry, ex);
    historyApplyWarmups(entry, ex);
    historyApplyDrops(entry, ex);
    historyApplyEffort(entry, ex, sess, sides);
    entry.sidesFailure = cleanFails;
    /* actualFailureSets zostáva zjednotením čísel sérií – pre staršie zobrazenia aj kompatibilitu. */
    entry.actualFailureSets = Array.from(new Set(cleanFails.left.concat(cleanFails.right)))
      .sort((a, b) => a - b);
  } else {
    const done = [];
    const fails = [];
    for (let i = 0; i < sessionSetCount(ex); i++) {
      if (sess && sess.completedSets[setSessionKey(ex, i)]) done.push(i + 1);
      if (sess && sess.actualFailureSets[setSessionKey(ex, i)]) fails.push(i + 1);
    }
    entry.setsDone = done.length;
    if (done.length) entry.doneSets = done.slice();   // presné čísla hotových sérií (aditívne)
    entry.actualFailureSets = cleanFailureSets(fails, sessionSetCount(ex));
    historyApplySetWeights(entry, ex, done);
    historyApplySetReps(entry, ex);
    historyApplyWarmups(entry, ex);
    historyApplyDrops(entry, ex);
    historyApplyEffort(entry, ex, sess, null);
  }
  return entry;
}

/* Hotové hlavné série jedného cviku z ukončeného tréningu: len značky "hotovo" (drop série sa
   nezapočítavajú, séria označená zlyhaním je tiež hotová), s váhou, akú zapíše historyExerciseEntry
   (výnimky aj zámky cez effectiveSetWeight). Jednostranný cvik nesie stranu 'left' / 'right'. */
function completedMainSets(ex, sess) {
  const out = [];
  if (!sess || !sess.completedSets) return out;   // značky sa čítajú z rozbehnutej session ako pri historyExerciseEntry
  const sides = exerciseSideOrder(ex);
  for (let i = 0; i < sessionSetCount(ex); i++) {
    for (const side of (sides || [null])) {
      if (!setMark('done', ex, i, side || undefined)) continue;
      const row = { weight: effectiveSetWeight(ex, i, side || undefined) };
      if (side) row.side = side;
      out.push(row);
    }
  }
  return out;
}

/* Pracovná váha na ďalší tréning z hotových hlavných sérií (spec §3.4): váha použitá aspoň v 2 sériách
   → najvyššia taká (asistované: najnižšia), inak váha poslednej hotovej série; bez sérií null.
   Jednostranný cvik: po stranách, potom ťažšia strana (asistované: nižšia asistencia). Čistá funkcia. */
function nextWorkingWeight(sets, opts) {
  const assisted = !!(opts && opts.assisted);
  const EPS = 0.001;
  const pick = (list) => {
    if (!list.length) return null;
    const repeated = list.filter((w) => list.filter((x) => Math.abs(x - w) < EPS).length >= 2);
    if (repeated.length) return assisted ? Math.min.apply(null, repeated) : Math.max.apply(null, repeated);
    return list[list.length - 1];
  };
  const valid = (Array.isArray(sets) ? sets : []).filter((s) => s && typeof s.weight === 'number' && Number.isFinite(s.weight));
  const per = ['left', 'right', undefined].map((sd) => pick(valid.filter((s) => (s.side || undefined) === sd).map((s) => s.weight)))
    .filter((v) => v !== null);
  if (!per.length) return null;
  return assisted ? Math.min.apply(null, per) : Math.max.apply(null, per);
}

/* Zmena váhy počas tréningu: záznam dostane váhy všetkých sérií (setWeights), pôvodnú
   plánovanú váhu (plannedWeight) a ako `weight` najťažšiu ODCVIČENÚ sériu – rekordy,
   úspechy aj porovnanie s minulým tréningom tak počítajú so skutočne zdvihnutou váhou. */
function historyApplySetWeights(entry, ex, doneSetNumbers) {
  const vals = sessionSetValues('weight', ex);
  if (!vals) return;
  entry.setWeights = vals.list;
  if (vals.sides) entry.sideWeights = vals.sides;
  entry.plannedWeight = Number(ex.weight) || 0;
  /* Po stranách sa berie skutočná váha odcvičenej strany, inak váha série. */
  const doneWeights = vals.sides && entry.sidesDone
    ? ['left', 'right'].flatMap((sd) => (entry.sidesDone[sd] || []).map((n) => vals.sides[sd][n - 1]))
    : (doneSetNumbers || []).map((n) => vals.list[n - 1]);
  const valid = doneWeights.filter((v) => typeof v === 'number');
  /* Asistovaný cvik: do záznamu ide najnižšia pomoc (najlepší výkon), nie najvyššie číslo. */
  if (valid.length) entry.weight = isAssisted(ex) ? Math.min.apply(null, valid) : Math.max.apply(null, valid);
}

/* Zmena opakovaní počas tréningu: záznam dostane opakovania všetkých sérií (setReps);
   `reps` zostáva plánovaný počet, takže porovnania a staršie zobrazenia fungujú ako doteraz. */
function historyApplySetReps(entry, ex) {
  const vals = sessionSetValues('reps', ex);
  if (!vals) return;
  entry.setReps = vals.list;
  if (vals.sides) entry.sideReps = vals.sides;
}
/* Dokončené drop série do histórie: [{ weight, reps }]. */
function historyApplyDrops(entry, ex) {
  const list = sessionDrops(ex).filter((d) => d.done).map((d) => ({ weight: d.w, reps: d.r }));
  if (list.length) entry.drops = list;
}

/* Zápis dokončenia sa nepodaril: okno ostáva otvorené (session, značky aj poznámka sa nemenia) a ukáže sa chyba ukladania. */
function finishSaveFailed() {
  const err = document.getElementById('confirm-error');
  if (err) err.hidden = false;
}

function confirmFinish() {
  /* Ochrana pred dvojitým uložením: potvrdzovacie okno je otvorené práve do prvého uloženia. */
  if (document.getElementById('modal-confirm').hidden) return;
  const plan = currentPlan();
  if (!plan) return;
  const sess = getSession();
  if (sess && state.history.some(w => w.id === sess.id)) {
    /* Záznam tohto tréningu v histórii už je (druhý zápis nedobehol alebo prišiel zo synchronizácie): nezapíše sa znova.
       Session sa zruší až po úspešnom zápise stavu. */
    if (!persistState()) { finishSaveFailed(); return; }
    workoutPhaseCancelOwner();
    clearSession(); stopTimer();
    document.getElementById('modal-confirm').hidden = true;
    saveState(); renderAll();
    return;
  }
  const prevRecommended = recommendedPlan();
  const beforeUnlocked = Object.keys(state.achievements);
  const beforeAchXP = achievementXP();
  const beforeLevel = levelForXp(totalXP()).level;

  /* Výmena cviku počas tréningu sa zapisuje POCTIVO: pôvodný cvik si ponechá svoje
     skutočne odcvičené série a náhrada sa zapíše zvlášť. Hotové série sa NIKDY
     neprepisujú na nový cvik. Cvik bez jedinej série ani rozcvičky či dropu sa do histórie nedostane.
     Zmena nastavení (kind 'settings') nemení logický cvik: jeho segmenty sú jedna skupina so spoločnou
     identitou (`segment`) a každý nesie len svoju odcvičenú prácu s vlastnými príznakmi. Segment s odcvičenou
     rozcvičkou či dropom sa zapíše aj bez hlavnej série (s nulou hotových sérií) a jeho rozcvičky a dropy sa
     nikdy nezlučujú do iného segmentu. */
  const exercises = [];
  const remembered = {};   // identita -> pracovná váha na ďalší tréning (z hotových hlavných sérií)
  const seenIdentity = {};
  /* `segments` = všetky segmenty toho istého logického cviku. Pracovná váha vychádza z hotových hlavných sérií len tých
     segmentov, ktoré sú zlučiteľné s CIEĽOVÝM riadkom plánu (rovnaká asistencia aj režim obojstranný/jednostranný): váha pomoci
     alebo jednej strany sa tak nikdy nezapíše do riadka s inou sémantikou. Bez zlučiteľného segmentu ostáva pamäť aj plán
     bez zmeny. Zapisuje sa iba váha, nikdy nastavenia. */
  const noteWeight = (segments) => {
    const identity = exerciseRowIdentity(segments[0]);
    if (!identity || seenIdentity[identity]) return;   // váhu určuje PRVÝ slot cviku v tréningu
    seenIdentity[identity] = true;
    if (sess && Array.isArray(sess.editedIdentities) && sess.editedIdentities.includes(identity)) return;   // novšia úprava plánu vyhráva
    const saved = state.plans && state.plans[plan.id];
    const target = (saved && Array.isArray(saved.exercises) && saved.exercises.find((r) => r && exerciseRowIdentity(r) === identity)) || segments[0];
    const compatible = (c) => exerciseRowIdentity(c) === identity && isAssisted(c) === isAssisted(target)
      && (c.unilateral === true) === (target.unilateral === true);
    const done = [];
    for (const c of segments) if (compatible(c)) for (const s of completedMainSets(c, sess)) done.push(s);
    const w = nextWorkingWeight(done, { assisted: isAssisted(target) });
    if (w !== null) remembered[identity] = { weight: w };
  };
  const finishGroups = supersetInfo(plan);
  for (const [si, info] of exerciseSlots(plan).entries()) {
    const slotGroup = finishGroups.get(si);   // náhrada patrí do skupiny svojho slotu
    const tagGroup = (e) => { if (slotGroup) e.group = slotGroup.group; else delete e.group; return e; };
    const chain = exerciseChainGroups(info);
    chain.forEach((grp, gi) => {
      const items = grp.items;
      let pushed = items.filter((it) => countDoneSets(it.ex) > 0 || sessionExtrasDone(it.ex));
      /* Skupina bez odcvičenej práce: pôvodný riadok sa zapíše, len ak je jediný (ako doteraz); výmena vždy. */
      if (!pushed.length && (gi > 0 || chain.length === 1)) pushed = [items[items.length - 1]];
      if (!pushed.length) return;
      const groupDone = items.reduce((n, it) => n + countDoneSets(it.ex), 0);
      const entries = pushed.map((it) => {
        /* Segment uzavretý zmenou nastavení: zapíše sa len práca po poslednú hotovú sériu. */
        const cap = items.indexOf(it) < items.length - 1 ? exSettingsDoneExtent(it.ex) : 0;
        return tagGroup(historyEntryForSegment(it.ex, sess, cap));
      });
      noteWeight(items.map((it) => it.ex));
      if (gi > 0 && items[0].step && items[0].step.oldName) entries[0].substitutedFor = items[0].step.oldName;
      /* Zapíše sa cvik, ktorý skupinu NAOZAJ vystriedal – pri reťazci teda ďalšia výmena, nie posledný krok. */
      if (gi < chain.length - 1 && groupDone > 0) {
        const last = entries[entries.length - 1];
        last.replacedBy = exerciseDisplayName(chain[gi + 1].items[0].ex);
        last.replacedAfterSets = groupDone;
      }
      if (items.length > 1) entries.forEach((e, k) => { e.segment = { id: info.slot + '~' + gi, n: k + 1, of: entries.length }; });
      for (const e of entries) exercises.push(e);
    });
  }

  const doneCount = totalSetsDone();
  const xp = xpForNewWorkout(doneCount, todayISO(), phaseSnapshotForHistory(getSession()));
  const note = document.getElementById('confirm-note').value.trim();
  const trainData = trainActive() ? trainProgressData() : null;   // pred zrušením session

  const entry = {
    id: sess ? sess.id : uid(),
    planId: plan.id,
    planName: recordedPlanName(plan),
    date: todayISO(),
    xp,
    note,
    exercises,
    endedAt: Date.now(),   // čas ukončenia (ms) pre prehľad regenerácie; staré záznamy ho nemajú
  };
  const phases = phaseSnapshotForHistory(sess);
  if (phases) entry.phases = phases;
  /* Trvanie sa zapíše len ak naozaj existuje rozbehnutá session – nikdy nevymýšľame nulu. */
  if (sess) entry.durationSeconds = sessionElapsedSeconds(sess);
  if (sess && sess.restUsed === true) entry.restUsed = true;   // aspoň raz bežal odpočet pauzy (úspech rest5)
  /* Health Connect (Android): skutočný čas tréningu – podľa neho sa číta tep a zapíše cvičenie. */
  if (sess && healthOn()) {
    const end = Date.now();
    entry.health = { start: new Date(end - entry.durationSeconds * 1000).toISOString(), end: new Date(end).toISOString() };
  }

  /* Bod návratu: ak sa zápis histórie nepodarí, vrátia sa všetky zmeny stavu v pamäti (história, váhy, úspechy, cieľ týždňa). */
  const goalBefore = JSON.stringify(state.goalHistory), memoryBefore0 = JSON.stringify(state.settings.exerciseMemory);
  const demoBefore = state.demo, achievementsBefore = state.achievements;
  const rowWeights = [];
  for (const p of Object.values(state.plans || {})) {
    if (p && Array.isArray(p.exercises)) for (const r of p.exercises) if (r) rowWeights.push([r, r.weight]);
  }
  const restoreJson = (obj, field, json) => { if (json === undefined) delete obj[field]; else obj[field] = JSON.parse(json); };

  /* Spoločná pracovná váha: až po zostavení histórie (tá drží skutočné váhy), pred jediným zápisom nižšie. */
  const rememberedAt = Date.now();
  /* Pre Zrušiť tréning: čo bolo v pamäti pred zápisom (null = záznam neexistoval) a čo sa zapísalo. */
  const memoryBefore = {}, memoryAfter = {}, memoryRowBefore = {};
  for (const [identity, values] of Object.entries(remembered)) {
    const cur = state.settings.exerciseMemory && Object.prototype.hasOwnProperty.call(state.settings.exerciseMemory, identity)
      && state.settings.exerciseMemory[identity] && typeof state.settings.exerciseMemory[identity] === 'object'
      ? Object.assign({}, state.settings.exerciseMemory[identity]) : null;
    const rowsW = {};   // plánId -> váha prvého riadka cviku pred zápisom
    for (const [pid, p] of Object.entries(state.plans || {})) {
      const row = p && Array.isArray(p.exercises) ? p.exercises.find((r) => r && exerciseRowIdentity(r) === identity) : null;
      if (row && typeof row.weight === 'number') rowsW[pid] = row.weight;
    }
    if (!applyExerciseDefaults(identity, values, rememberedAt, plan.id)) continue;   // váha len do plánu tohto tréningu
    memoryBefore[identity] = cur;
    memoryAfter[identity] = Object.assign({}, values);
    if (Object.keys(rowsW).length) memoryRowBefore[identity] = rowsW;
  }

  for (const [field, map] of [['memoryBefore', memoryBefore], ['memoryAfter', memoryAfter], ['memoryRowBefore', memoryRowBefore]]) {
    const clean = cleanMemoryTrail(map, field);
    if (clean) entry[field] = clean;
  }
  state.history.push(entry);
  syncGoalSnapshot();    // tento týždeň je teraz "pozorovaný" so svojím cieľom
  state.demo = false;  // real workout → data is no longer demo
  reconcileAchievements();
  /* História sa musí zapísať ako PRVÁ: kým zápis nepreukázateľne uspel, session ostáva, nič sa nezruší ani neodmení
     a v pamäti nezostane záznam, ktorý by sa pri ďalšom pokuse dal považovať za už uložený. */
  if (!persistState()) {
    const at = state.history.lastIndexOf(entry);
    if (at >= 0) state.history.splice(at, 1);
    restoreJson(state, 'goalHistory', goalBefore);
    restoreJson(state.settings, 'exerciseMemory', memoryBefore0);
    for (const [row, weight] of rowWeights) { if (weight === undefined) delete row.weight; else row.weight = weight; }
    state.demo = demoBefore;
    state.achievements = achievementsBefore;
    suggestMemoReset();
    xpCacheClear();
    finishSaveFailed();
    return;
  }
  syncNoteLocalChange();
  leaderboardQueue();
  try { localStorage.setItem(STORAGE_KEY + '_real', '1'); } catch (e) { /* pomocný príznak: stav už nesie demo = false */ }
  lastWorkoutId = entry.id;

  lastUnlocked = Object.keys(state.achievements).filter(id => !beforeUnlocked.includes(id));
  lastAchXP = achievementXP() - beforeAchXP;
  lastLevelUp = levelForXp(totalXP()).level > beforeLevel ? levelForXp(totalXP()).level : 0;

  lastXP = historyEntryXp(entry);
  selectedPlan = prevRecommended || selectedPlan;
  trainOnWorkoutFinished(entry, trainData);   // "trénoval s …" + priateľ uvidí hotovo (až po zápise histórie)
  /* Session sa ruší až po uložení histórie – nikdy predtým. */
  clearSession();
  stopTimer();
  saveState();

  document.getElementById('modal-confirm').hidden = true;

  showResultModal();
  renderAll();
  nativeHealthAfterFinish(entry);
}

function showResultModal() {
  const info = levelInfo();
  document.getElementById('result-xp').innerHTML = `<bdi>+${lastXP} ${esc(t('units.xp'))}</bdi>`;   // bdi: v arabčine sa "+50 XP" nepreskladá
  document.getElementById('result-msg').textContent = randomEncouragement();

  const achEl = document.getElementById('result-achievements');
  if (lastUnlocked.length) {
    const names = lastUnlocked.map(id => {
      if (id.startsWith('ms-')) {
        const parts = id.split('-');
        const kg = parts[parts.length - 1];
        return `${t('motivacia.ach.5kg', { name: recordedNameToDisplay(parts.slice(1, -1).join('-')), kg })}`;
      }
      const def = allAchievementDefs().find(d => d.id === id);
      return def ? `${def.icon} ${t(def.nameKey, { n: def.n })}` : id;
    }).join(', ');
    achEl.textContent = t('motivacia.newAchievement', { names })
      + (lastAchXP > 0 ? ' · ' + t('motivacia.newAchXp', { xp: lastAchXP }) : '');
    achEl.hidden = false;
  } else {
    achEl.hidden = true;
  }

  const upEl = document.getElementById('result-levelup');
  if (upEl) {
    upEl.textContent = lastLevelUp ? t('xp.levelUp', { n: lastLevelUp }) : '';
    upEl.hidden = !lastLevelUp;
  }

  const note = document.getElementById('result-note');
  const entry = state.history.find(w => w.id === lastWorkoutId);
  if (entry && entry.note) {
    note.textContent = `“${entry.note}”`;
    note.hidden = false;
  } else {
    note.hidden = true;
  }

  /* Zdieľanie do Community hneď po tréningu (len keď je Community zapnutá a server má 0011). */
  const shareBtn = document.getElementById('btn-result-share');
  if (shareBtn) shareBtn.hidden = !(communityConfigured() && communityOptIn() && communityV5() && entry);

  /* Trvanie sa zobrazí len ak bolo naozaj zmerané. */
  const durEl = document.getElementById('result-duration');
  const savedSeconds = cleanDurationSeconds(entry && entry.durationSeconds);
  if (savedSeconds !== null) {
    durEl.textContent = t('trening.durationResult', { duration: formatDurationNatural(savedSeconds) });
    durEl.hidden = false;
  } else {
    durEl.hidden = true;
  }
  renderResultHealth(entry);

  document.getElementById('modal-result').hidden = false;
}

/* ---------- Undo / edit / delete tréningu ---------- */

/* Zrušiť tréning vráti aj váhy, ktoré Dokončiť zapísal: len ak sa pamäť a riadky plánov od vtedy
   nezmenili (rovnajú sa tomu, čo Dokončiť zapísal) – novšia úprava používateľa ostáva. */
function restoreRememberedWeights(entry) {
  const after = entry && entry.memoryAfter;
  const before = entry && entry.memoryBefore;
  if (!after || !before || !state.settings) return;
  const fieldsOf = (v) => Object.keys(v).filter((f) => f !== 'at');
  for (const identity of Object.keys(after)) {
    if (!Object.prototype.hasOwnProperty.call(before, identity)) continue;
    const a = after[identity], b = before[identity];
    const mem = state.settings.exerciseMemory;
    const cur = mem && Object.prototype.hasOwnProperty.call(mem, identity) ? mem[identity] : null;
    const same = (obj) => obj && typeof obj === 'object' && fieldsOf(a).every((f) => obj[f] === a[f]);
    if (!same(cur)) continue;   // pamäť sa zmenila (úprava plánu, ďalší tréning) – nechá sa
    const rows = [];
    for (const [pid, plan] of Object.entries(state.plans || {})) {
      const row = plan && Array.isArray(plan.exercises) ? plan.exercises.find((r) => r && exerciseRowIdentity(r) === identity) : null;
      if (row && same(row)) rows.push([pid, row]);
    }
    const rowBefore = (entry.memoryRowBefore && entry.memoryRowBefore[identity]) || {};
    for (const [pid, row] of rows) {
      for (const f of fieldsOf(a)) {
        let v = b ? b[f] : undefined;
        if (f === 'weight' && rowBefore[pid] !== undefined) v = rowBefore[pid];   // každý riadok späť na vlastnú pôvodnú váhu
        if (v === undefined) { if (f !== 'weight') delete row[f]; } else row[f] = v;
      }
    }
    if (b) mem[identity] = Object.assign({}, b); else delete mem[identity];
  }
}

function requestUndoWorkout() {
  const entry = state.history.find(w => w.id === lastWorkoutId);
  if (!entry) return;
  showGeneric(t('trening.undoConfirmTitle'), t('trening.undo'), () => {
    healthDeleteSession(entry);
    restoreRememberedWeights(entry);
    state.history = state.history.filter(w => w.id !== lastWorkoutId);
    lastWorkoutId = null;
    lastUnlocked = [];
    lastAchXP = 0;
    state.demo = false;
    localStorage.setItem(STORAGE_KEY + '_real', '1');
    document.getElementById('modal-result').hidden = true;
    recalculateAll();
    saveState();
    switchTab('trening');
  }, t('trening.undoConfirm', { xp: historyEntryXp(entry) }) + '<br>' + esc(t('phase.undoHelp')), t('history.keepWorkout'));
}

function requestDeleteWorkout(id) {
  const entry = state.history.find(w => w.id === id);
  if (!entry) return;
  showGeneric(t('history.deleteTitle'), t('common.delete'), () => {
    healthDeleteSession(entry);
    state.history = state.history.filter(w => w.id !== id);
    if (lastWorkoutId === id) lastWorkoutId = null;
    recalculateAll();
    saveState();
    renderPokrok();
  }, t('history.deleteConfirm', { xp: historyEntryXp(entry) }), t('history.keepWorkout'));
}

/* ---------- Úprava tréningu z histórie ---------- */

let heWorkoutId = null;
let heOriginal = [];   // váha a počet sérií pri otvorení úpravy (pre váhy jednotlivých sérií)

function openHistoryEdit(id) {
  const w = state.history.find(x => x.id === id);
  if (!w) return;
  heWorkoutId = id;
  heOriginal = w.exercises.map((e) => ({ weight: e.weight, sets: e.sets, reps: e.reps }));
  document.getElementById('he-date').value = w.date;
  document.getElementById('he-note').value = w.note || '';
  const box = document.getElementById('he-exercises');
  box.innerHTML = '';
  w.exercises.forEach((ex, idx) => {
    const row = document.createElement('div');
    row.className = 'he-ex-row';
    row.innerHTML = `
      <span class="he-name">${esc(ex.name)}</span>
      ${ex.unilateral === true ? `<span class="he-side">${esc(tPlural('unilateral.setsPerSide', ex.sets))}</span>` : ''}
      <span class="he-label">${t('history.setsLabel')}</span><input type="number" min="1" max="99" value="${ex.sets}" data-f="sets">
      <span class="he-label">${t('history.repsLabel')}</span><input type="number" min="1" max="99" value="${ex.reps}" data-f="reps">
      <span class="he-label">${t('units.kg')}</span><input type="number" min="0" max="999" value="${ex.weight}" data-f="weight">
      <span class="he-label">${t('history.setsDoneLabel')}</span><input type="number" min="0" max="99" value="${ex.setsDone}" data-f="setsDone">`;
    row.querySelectorAll('input').forEach(inp => {
      inp.addEventListener('input', () => {
        w.exercises[idx][inp.dataset.f] = num(inp.value);
      });
    });
    box.appendChild(row);
  });
  document.getElementById('modal-history-edit').hidden = false;
}

function saveHistoryEdit() {
  const w = state.history.find(x => x.id === heWorkoutId);
  if (!w) return;
  const prevDate = w.date;
  w.date = document.getElementById('he-date').value || w.date;
  /* Zmena dátumu zneplatní čas ukončenia (inak by zotavenie počítalo so starým dňom). */
  if (w.date !== prevDate) delete w.endedAt;
  w.note = document.getElementById('he-note').value.trim();
  w.exercises.forEach((e, idx) => {
    e.sets = Math.max(1, Math.min(99, Math.round(e.sets)));
    e.reps = Math.max(1, Math.min(99, Math.round(e.reps)));
    e.weight = Math.max(0, Math.min(999, Math.round(e.weight * 2) / 2));
    e.setsDone = Math.max(0, Math.min(e.sets, Math.round(e.setsDone)));
    /* Presný zoznam hotových sérií platí, len kým súhlasí s počtom sérií a hotových; inak ho nahradí odhad. */
    if (e.doneSets !== undefined && !cleanHistoryDoneSets(e)) delete e.doneSets;
    /* Váhy jednotlivých sérií platia len pre pôvodný záznam: ručne zmenená váha alebo počet
       sérií ich nahradí jednou váhou (inak by zobrazenie odporovalo upravenej hodnote). */
    const orig = heOriginal[idx];
    if (Array.isArray(e.setWeights) && (!orig || e.weight !== orig.weight || e.sets !== orig.sets || !cleanHistorySetWeights(e))) {
      delete e.setWeights; delete e.plannedWeight; delete e.sideWeights;
    }
    /* Rovnako opakovania jednotlivých sérií: ručne zmenené opakovania alebo počet sérií ich nahradia. */
    if (Array.isArray(e.setReps) && (!orig || e.reps !== orig.reps || e.sets !== orig.sets || !cleanHistorySetReps(e))) { delete e.setReps; delete e.sideReps; }
    /* Existujúce polia do zlyhania sa orežú na nový počet sérií; starým záznamom sa nepridávajú. */
    historyEditEffort(e);
    if (Array.isArray(e.actualFailureSets)) e.actualFailureSets = cleanFailureSets(e.actualFailureSets, e.sets);
    if (Array.isArray(e.plannedFailureSets)) e.plannedFailureSets = cleanFailureSets(e.plannedFailureSets, e.sets);
    if (e.unilateral === true) {
      /* Jednostranný cvik: setsDone je súčet oboch strán, takže sa oreže na 2× počet sérií.
         Zlyhania po stranách sa orežú rovnako a zjednotenie sa prepočíta. */
      e.startSide = e.startSide === 'right' ? 'right' : 'left';
      e.setsDone = Math.max(0, Math.min(e.sets * 2, Math.round(e.setsDone)));
      e.sidesDone = cleanSideSets(e.sidesDone, e.sets);
      e.sidesFailure = cleanSideSets(e.sidesFailure, e.sets);
      e.actualFailureSets = Array.from(new Set(e.sidesFailure.left.concat(e.sidesFailure.right)))
        .sort((a, b) => a - b);
    }
  });
  /* Uložené xp sa pri úprave nemení: staré záznamy majú pôvodné (staré) XP a denný limit by sa spätne prepisoval. */
  document.getElementById('modal-history-edit').hidden = true;
  recalculateAll();
  saveState();
  renderPokrok();
}

/* ---------- Rekalkulácia ---------- */

function recalculateAll() {
  suggestMemoReset();   // render pred uložením nesmie použiť starý návrh
  reconcileAchievements();
  renderAll();
}

