/* ---------- Vzhľad: Bento svetlý / tmavý / podľa telefónu ----------
   Voľba tohto zariadenia (localStorage 'gymquest_theme'), mimo stavu aplikácie: nesynchronizuje
   sa, nie je v exporte a nikdy nemení dáta. Skript v <head> ju použije ešte pred vykreslením,
   tu sa len prepína a reaguje na zmenu režimu telefónu. */
const THEME_KEY = 'gymquest_theme';
const THEME_COLORS = { light: '#E9E8E4', dark: '#0E0E0F' };
function themePref() {
  let v = null;
  try { v = localStorage.getItem(THEME_KEY); } catch (e) {}
  return v === 'light' || v === 'dark' ? v : 'auto';
}
function themeResolved(pref) {
  const p = pref || themePref();
  if (p === 'light' || p === 'dark') return p;
  return window.matchMedia && window.matchMedia('(prefers-color-scheme: dark)').matches ? 'dark' : 'light';
}
function applyTheme() {
  const t = themeResolved();
  document.documentElement.setAttribute('data-theme', t);
  const m = document.querySelector('meta[name="theme-color"]');
  if (m) m.setAttribute('content', THEME_COLORS[t]);
  nativeThemeBars(t);
  renderThemeChips();
}
/* Android appka: stavová lišta má farbu pozadia appky a ikony čitateľné na nej
   (DARK = svetlé ikony na tmavom pozadí, LIGHT = tmavé ikony na svetlom).
   GymBars (vlastný plugin v appke) zafarbí okno pod OBOMA systémovými lištami – Capacitor 8 dáva
   WebView medzi lišty, takže inak tam presvitá systémové pozadie podľa režimu telefónu
   (sivé/čierne lišty vo svetlej téme, keď je telefón v tmavom režime). */
function nativeThemeBars(t) {
  const bar = nativePlugin('StatusBar');
  if (bar) {
    bar.setStyle({ style: t === 'dark' ? 'DARK' : 'LIGHT' }).catch(() => {});
    bar.setBackgroundColor({ color: THEME_COLORS[t] }).catch(() => {});
  }
  const bars = nativePlugin('GymBars');
  if (bars) bars.setColors({ color: THEME_COLORS[t], dark: t === 'dark' }).catch(() => {});
}

/* Android appka s 3-tlačidlovou navigáciou: tab bar sa pripne na celú šírku tesne nad systémové tlačidlá
   (html.nav-buttons). Capacitor 8 dáva WebView medzi lišty, takže env() režim nepovie – pýta sa GymBars. */
function nativeNavMode() {
  const bars = nativePlugin('GymBars');
  if (!bars || !bars.navMode) return;
  bars.navMode().then((r) => {
    document.documentElement.classList.toggle('nav-buttons', !!r && r.mode === 'buttons');
    if (typeof updateStickyBottom === 'function') updateStickyBottom();
  }).catch(() => {});
}

/* Android appka: WebView ignoruje <a download>, preto sa súbor zapíše do cache appky a ponúkne
   cez systémové zdieľanie (Uložiť do Súborov, Disk Google, e-mail…). data = text alebo Blob.
   true = zdieľanie sa otvorilo, NIE "súbor je uložený"; zrušenie nie je chyba. */
function nativeBlobBase64(blob) {
  return new Promise((resolve, reject) => {
    const r = new FileReader();
    r.onload = () => resolve(String(r.result).replace(/^data:[^,]*,/, ''));
    r.onerror = () => reject(r.error);
    r.readAsDataURL(blob);
  });
}
async function nativeSaveAndShare(fileName, mime, data) {
  const fsys = nativePlugin('Filesystem');
  const share = nativePlugin('Share');
  if (!fsys || !share) return false;
  let written;
  try {
    const opts = { path: fileName, directory: 'CACHE', recursive: true };
    if (typeof data === 'string') { opts.data = data; opts.encoding = 'utf8'; }
    else opts.data = await nativeBlobBase64(data);
    written = await fsys.writeFile(opts);
  } catch (e) { return false; }
  try { await share.share({ title: 'GymQuest', files: [written.uri] }); } catch (e) { /* zrušené */ }
  return true;
}
function setThemePref(v) {
  try {
    if (v === 'light' || v === 'dark') localStorage.setItem(THEME_KEY, v);
    else localStorage.removeItem(THEME_KEY);
  } catch (e) {}
  applyTheme();
}
function renderThemeChips() {
  const pref = themePref();
  document.querySelectorAll('#theme-chips [data-theme-choice]').forEach((b) => {
    const on = b.dataset.themeChoice === pref;
    b.classList.toggle('active', on);
    b.setAttribute('aria-checked', on ? 'true' : 'false');
    b.tabIndex = on ? 0 : -1;   // skupina prepínačov: Tab vstúpi na vybraný, šípky menia voľbu
  });
}
function themeChipsKey(e) {
  const keys = { ArrowRight: 1, ArrowDown: 1, ArrowLeft: -1, ArrowUp: -1 };
  if (!(e.key in keys)) return;
  const list = [...document.querySelectorAll('#theme-chips [data-theme-choice]')];
  const i = list.indexOf(document.activeElement);
  if (i < 0) return;
  e.preventDefault();
  const dir = document.documentElement.dir === 'rtl' && (e.key === 'ArrowLeft' || e.key === 'ArrowRight') ? -keys[e.key] : keys[e.key];
  const next = list[(i + dir + list.length) % list.length];
  setThemePref(next.dataset.themeChoice);
  next.focus();
}
(function watchSystemTheme() {
  try {
    const mq = window.matchMedia && window.matchMedia('(prefers-color-scheme: dark)');
    const onChange = () => { if (themePref() === 'auto') applyTheme(); };
    if (mq && mq.addEventListener) mq.addEventListener('change', onChange);
    else if (mq && mq.addListener) mq.addListener(onChange);
  } catch (e) {}
})();

let tourHelpOpener = null;   // kto otvoril Nastavenia: tam sa vráti fokus po návode spustenom z Pomoci
