      if (tab.dataset.tab === 'komunita' && communityMode === 'messages') { communityMode = 'community'; communityBack = []; communityView = 'feed'; }
      if (tab.dataset.tab === 'pokrok') pokrokView = 'stats';
      pokrokReturnTab = null;
