    const list = [...document.querySelectorAll('#ty-seg [data-ty-filter]')];
    let i = list.indexOf(cur) + ((e.key === 'ArrowRight') !== (document.documentElement.dir === 'rtl') ? 1 : -1);
    i = (i + list.length) % list.length;
