/* iPhone (aj appka z plochy): druhé rýchle ťuknutie na to isté miesto stránku priblíži („smart zoom“),
   aj keď je nastavené touch-action: manipulation – dlaždice plánov sa ťukajú dvakrát rýchlo za sebou.
   Druhé rýchle ťuknutie jedným prstom bez pohybu sa preto vybaví ako obyčajné ťuknutie (klik) a iOS ho
   nepriblíži. Priblíženie dvoma prstami, posúvanie a polia formulárov (klávesnica) zostávajú nedotknuté. */
const DOUBLE_TAP_MS = 350;
let tapGuardStart = null;
let tapGuardLast = { at: 0, x: 0, y: 0 };
function installDoubleTapGuard() {
  document.addEventListener('touchstart', (e) => {
    if (e.touches.length !== 1) { tapGuardStart = null; tapGuardLast.at = 0; lastPlanTap = null; return; }   // viac prstov = gesto
    const t = e.touches[0];
    tapGuardStart = { x: t.clientX, y: t.clientY, at: Date.now() };
  }, { passive: true });
  document.addEventListener('touchend', (e) => {
    const start = tapGuardStart;
    tapGuardStart = null;
    if (!start || e.touches.length || e.changedTouches.length !== 1) return;
    const t = e.changedTouches[0];
    const now = Date.now();
    const moved = Math.abs(t.clientX - start.x) > 10 || Math.abs(t.clientY - start.y) > 10;
    if (moved || now - start.at > 500) { tapGuardLast.at = 0; lastPlanTap = null; return; }   // posúvanie / podržanie nie je ťuknutie
    const quick = now - tapGuardLast.at < DOUBLE_TAP_MS && Math.abs(t.clientX - tapGuardLast.x) < 40 && Math.abs(t.clientY - tapGuardLast.y) < 40;
    tapGuardLast = { at: now, x: t.clientX, y: t.clientY };
    if (!quick) return;
    const target = e.target && e.target.closest ? e.target : null;
    if (!target || target.closest('input, textarea, select, [contenteditable="true"], video, audio')) return;
    e.preventDefault();   // iOS potom nespustí dvojité priblíženie (ani vlastný klik)…
    if (target.closest('#plan-chips .chip')) {
      /* Druhý dotyk má rovnakú aktiváciu ako klik; obyčajné .click() nemá detail a patrí klávesnici. */
      target.dispatchEvent(new MouseEvent('click', { bubbles: true, cancelable: true, detail: 1, clientX: t.clientX, clientY: t.clientY }));
    } else target.click();   // ostatné ovládacie prvky zachovajú pôvodné správanie
  }, { passive: false });
  document.addEventListener('touchcancel', () => {
    tapGuardStart = null;
    tapGuardLast.at = 0;
    lastPlanTap = null;
  }, { passive: true });
}

/* ---------- Denný strážca (dátum, ISO týždeň, týždenný progres) ---------- */

/* Ak sa zmenil lokálny deň, prekreslí dátum a týždenné ukazovatele.
   Zámerne nevolá renderAll(): prekreslenie celej appky je zbytočné pri zmene dňa.
   Priebeh tréningu medzitým drží state.activeSession, takže sa nič nestratí. */
function refreshDayIfChanged() {
  const today = todayISO();
  if (today === lastRenderedDay) return false;
  lastRenderedDay = today;
  syncGoalSnapshot();    // nový deň (napr. pondelok) = nový bežiaci týždeň so svojím cieľom
  renderDnes();
  renderPokrok();
  if (activeTab === 'kalendar') renderKalendar();   // oranžový krúžok "dnes" sa posunie
  return true;
}

/* Vytvorí práve jeden interval. Opakované volanie nič nerobí,
   takže po prekreslení nevzniknú duplicitné časovače. */
function startDayWatcher() {
  if (dayWatchInterval !== null) return;
  lastRenderedDay = todayISO();
  dayWatchInterval = setInterval(refreshDayIfChanged, 60000);
  document.addEventListener('visibilitychange', refreshDayIfChanged);
}

/* ---------- Service worker: offline cache a aktualizácie ---------- */

let swRegistration = null;
let swUpdateReady = false;          // čaká nová verzia
let reloadingForUpdate = false;     // ochrana proti slučke reloadov
let pendingUpdateReload = false;    // nová verzia je aktívna, ale používateľ je zaneprázdnený
/* Pri prvej inštalácii stránku neriadi žiadny service worker; clients.claim()
   vtedy vyvolá controllerchange, ktorý nesmie spôsobiť reload. Ignoruje sa však
   len tento prvý – každý ďalší controllerchange je skutočná aktualizácia
   (napr. "Aktualizovať" v tej istej karte, ktorá appku práve nainštalovala). */
let swHasController = !!(navigator.serviceWorker && navigator.serviceWorker.controller);

/* Prebieha niečo, pri čom by reload mohol stratiť vstup používateľa? */
function isBusy() {
  if (editingPlan !== null) return true;                 // otvorený editor plánu s neuloženými zmenami
  if (getSession()) return true;                         // rozbehnutý aktívny tréning (meria sa jeho trvanie)
  if (totalSetsDone() > 0) return true;                  // rozbehnutý tréning s označenými sériami
  if (presetManageMode) return true;                     // otvorená správa predvolieb časovača
  const ctPanel = document.getElementById('custom-timer');
  if (ctPanel && !ctPanel.hidden) return true;           // rozrobený vlastný čas pauzy
  const forms = ['modal-confirm', 'modal-history-edit', 'modal-settings', 'modal-setup', 'modal-generic',
    'modal-practice',
    'modal-ex-settings',
    'modal-reminders',
    'modal-planchoice', 'modal-fullbody', 'modal-lang', 'modal-measure', 'modal-food',
    'modal-library', 'modal-exercise', 'modal-photo-add', 'modal-photo', 'modal-photo-compare',
    'modal-community-caption', 'modal-auth', 'modal-sync', 'modal-plates', 'modal-effort', 'modal-suggest', 'modal-programs', 'modal-ex-actions', 'modal-ex-progress', 'modal-muscles', 'modal-csv', 'modal-csv-import'];
  for (const id of forms) {
    const el = document.getElementById(id);
    if (el && !el.hidden) return true;                   // otvorený formulár / dialóg
  }
  if (activeTab === 'komunita' && ['compose', 'chat', 'comments'].indexOf(communityView) >= 0) return true;   // písanie v Community
  return false;
}

function reloadForUpdate() {
  if (reloadingForUpdate) return;
  if (isBusy()) { pendingUpdateReload = true; return; }  // počkaj, kým používateľ dokončí
  reloadingForUpdate = true;
  location.reload();
}

/* Banner sa ukáže len vtedy, keď je aktualizácia pripravená a nič sa neupravuje. */
function refreshUpdateBanner() {
  const banner = document.getElementById('update-banner');
  if (!banner) return;
  const show = swUpdateReady && !isBusy() && !isNativeApp();
  if (show && tourOpen()) closeTour('yield');   // ponuka aktualizácie má prednosť pred návodom
  banner.hidden = !show;
  document.body.classList.toggle('has-update-banner', show);
  if (pendingUpdateReload && !isBusy()) {
    pendingUpdateReload = false;
    reloadForUpdate();
  }
  /* Záloha sa vyhodnocuje vždy, keď sa obrazovka ustálila – a nikdy počas
     tréningu ani otvoreného dialógu (pozri backupBlocked). */
  refreshBackupOffer();
}

function applyUpdate() {
  const waiting = swRegistration && swRegistration.waiting;
  if (!waiting) return;
  swUpdateReady = false;
  swHasController = true;   // používateľ si aktualizáciu vyžiadal – nasledujúci controllerchange musí obnoviť stránku
  refreshUpdateBanner();
  waiting.postMessage({ type: 'SKIP_WAITING' });
}

/* ---------- Nastavenia: aktualizácie aplikácie ----------
   Ručná kontrola tým istým mechanizmom ako lišta "Aktualizovať": nová verzia sa
   stiahne cez service worker a nainštaluje sa až po kliknutí. Počas tréningu sa
   neinštaluje (rovnaké pravidlo ako isBusy). */
let appUpdateCheck = '';   // '' | 'checking' | 'downloading' | 'latest' | 'offline' | 'failed'

function swSupported() {
  return !isNativeApp() && typeof navigator !== 'undefined' && 'serviceWorker' in navigator
    && (location.protocol === 'http:' || location.protocol === 'https:');
}

/* Verzia, ktorú hlási service worker (CACHE_VERSION); '' ak neodpovie. */
function askSwVersion(worker) {
  return new Promise((resolve) => {
    if (!worker || typeof MessageChannel === 'undefined') { resolve(''); return; }
    const ch = new MessageChannel();
    const timer = setTimeout(() => resolve(''), 1500);
    ch.port1.onmessage = (e) => { clearTimeout(timer); resolve((e.data && e.data.version) || ''); };
    try { worker.postMessage({ type: 'GET_VERSION' }, [ch.port2]); } catch (e) { clearTimeout(timer); resolve(''); }
  });
}

function updateBlockedByWorkout() {
  return !!getSession() || totalSetsDone() > 0;
}

function renderAppUpdateSetting() {
  const block = document.getElementById('app-update-block');
  if (!block) return;
  block.hidden = !swSupported();
  if (block.hidden) return;
  const status = document.getElementById('app-update-status');
  const checkBtn = document.getElementById('btn-check-update');
  const updBtn = document.getElementById('btn-settings-update');
  const blocked = swUpdateReady && updateBlockedByWorkout();
  let msg = '';
  if (swUpdateReady) msg = blocked ? t('update.ready') + ' ' + t('update.finishWorkout') : t('update.ready');
  else if (appUpdateCheck) msg = t('update.' + appUpdateCheck);
  status.textContent = msg;
  status.hidden = !msg;
  updBtn.hidden = !swUpdateReady;
  updBtn.disabled = blocked;
  checkBtn.hidden = swUpdateReady;
  checkBtn.disabled = appUpdateCheck === 'checking' || appUpdateCheck === 'downloading';
  const line = document.getElementById('app-version-line');
  askSwVersion(navigator.serviceWorker.controller).then((v) => {
    line.textContent = v ? t('update.version', { v }) : '';
    line.hidden = !v;
  });
}

async function checkForAppUpdate() {
  if (appUpdateCheck === 'checking' || appUpdateCheck === 'downloading') return;
  if (!swRegistration) {
    appUpdateCheck = navigator.onLine === false ? 'offline' : 'failed';
    renderAppUpdateSetting();
    return;
  }
  appUpdateCheck = 'checking';
  renderAppUpdateSetting();
  try {
    await swRegistration.update();
    if (swUpdateReady) appUpdateCheck = '';
    else if (swRegistration.installing) appUpdateCheck = 'downloading';   // dokončenie hlási statechange
    else if (swRegistration.waiting && navigator.serviceWorker.controller) {
      swUpdateReady = true;
      appUpdateCheck = '';
      refreshUpdateBanner();
    } else appUpdateCheck = 'latest';
  } catch (e) {
    appUpdateCheck = navigator.onLine === false ? 'offline' : 'failed';
  }
  renderAppUpdateSetting();
}

/* "Aktualizovať" v Nastaveniach: Nastavenia sa zatvoria ako cez "Zavrieť" (cieľ sa uloží),
   inak by otvorený dialóg (isBusy) obnovenie stránky odložil. */
function applyUpdateFromSettings() {
  if (!swUpdateReady || updateBlockedByWorkout()) { renderAppUpdateSetting(); return; }
  saveSettingsGoal();
  document.getElementById('modal-settings').hidden = true;
  applyUpdate();
}

/* ---------- Návod ---------- */
/* Krátky sprievodca: tmavý prekryv s vyrezaným zvýraznením prvku a kartou s textom kroku. Nikdy nemení
   dáta appky (state, plány, tréningy, nastavenia): jediné, čo si pamätá, je localStorage TOUR_KEY
   { v: 1, status: 'done'|'skipped'|'invited-dismissed', at } – len na tomto zariadení, nikdy sa nesynchronizuje.
   Krok: { id, target: () => Element|null, illus: () => HTMLElement|null, title, body, tab?, illusWithTarget? }.
   title/body: funkcia, kľúč z I18N, alebo hotový text. Ak je cieľ viditeľný, posunie sa do výhľadu (len ak v ňom
   ešte nie je) a zvýrazní; inak sa v karte ukáže ilustrácia (neaktívna kópia s odstránenými ID-čkami);
   illusWithTarget ju ukáže aj popri zvýraznenom cieli. tab: každá z 6 kariet sa len ZOBRAZÍ (tourEnterTab): bez switchTab, bez načítania
   zo siete, bez zápisu a bez zmeny activeTab / režimu Správy-Community; pri zatvorení sa pôvodné zobrazenie vráti priamo. */
const TOUR_KEY = 'gymquest_tutorial';
const TOUR_I18N = {
  sk: { 'tour.back': 'Späť', 'tour.next': 'Ďalej', 'tour.done': 'Hotovo', 'tour.skip': 'Preskočiť', 'tour.close': 'Zavrieť návod', 'tour.stepOf': '{n} z {total}' },
  en: { 'tour.back': 'Back', 'tour.next': 'Next', 'tour.done': 'Done', 'tour.skip': 'Skip', 'tour.close': 'Close tour', 'tour.stepOf': '{n} of {total}' },
  es: { 'tour.back': 'Atrás', 'tour.next': 'Siguiente', 'tour.done': 'Listo', 'tour.skip': 'Omitir', 'tour.close': 'Cerrar la guía', 'tour.stepOf': '{n} de {total}' },
  'pt-BR': { 'tour.back': 'Voltar', 'tour.next': 'Próximo', 'tour.done': 'Concluir', 'tour.skip': 'Pular', 'tour.close': 'Fechar o tutorial', 'tour.stepOf': '{n} de {total}' },
  fr: { 'tour.back': 'Retour', 'tour.next': 'Suivant', 'tour.done': 'Terminé', 'tour.skip': 'Passer', 'tour.close': 'Fermer le guide', 'tour.stepOf': '{n} sur {total}' },
  ar: { 'tour.back': 'رجوع', 'tour.next': 'التالي', 'tour.done': 'تم', 'tour.skip': 'تخطّي', 'tour.close': 'إغلاق الدليل', 'tour.stepOf': '{n} من {total}' },
};
for (const lang of Object.keys(TOUR_I18N)) Object.assign(I18N[lang] || (I18N[lang] = {}), TOUR_I18N[lang]);

const TOUR_TABS = ['dnes', 'trening', 'pokrok', 'komunita', 'spravy', 'ty'];
const TOUR_SCREENS = ['dnes', 'trening', 'pokrok', 'kalendar', 'komunita', 'ty'];
let tourRun = null;   // { steps, i, root, spot, card, opener, nav, shown, startScroll, raf, animUntil, animT, off } | null
let tourQuiet = false;   // krátko po zatvorení: znovu zobrazená obrazovka spustí IntersectionObserver-y; ich stránkovanie sa preskočí (tourSuppressed)
function tourSuppressed() { return tourRun !== null || tourQuiet; }

/* Zobrazená karta: Správy a Community sú jedna obrazovka, odlišuje ich communityMode (ten návod nikdy nemení). */
function tourShownKey() { return activeTab === 'komunita' && communityMode === 'messages' ? 'spravy' : activeTab; }
/* Odtlačok zobrazenia pred návodom: obrazovky, zvýraznenie menu (trieda + aria-current), trieda msg-mode a body[data-tab]. */
function tourSnapshotNav() {
  const kom = document.getElementById('screen-komunita');
  return {
    app: [activeTab, communityMode, communityView, communityChatId],   // skutočný stav appky; ak sa počas návodu zmení (napr. ťuknutie na upozornenie), obnova by klamala
    body: document.body.dataset.tab,
    screens: TOUR_SCREENS.map((s) => [s, document.getElementById('screen-' + s).hidden]),
    msg: !!kom && kom.classList.contains('msg-mode'),
    tabs: Array.from(document.querySelectorAll('.tab')).map((el) => [el, el.classList.contains('active'), el.getAttribute('aria-current')]),
  };
}
/* Čisto prezentačné zobrazenie karty (obrazovky, menu, msg-mode, body[data-tab]); nič sa nevykresľuje ani nenačítava. */
function tourShowScreen(tab) {
  const screen = tab === 'spravy' ? 'komunita' : tab;
  document.body.dataset.tab = screen;
  for (const s of TOUR_SCREENS) document.getElementById('screen-' + s).hidden = s !== screen;
  document.querySelectorAll('.tab').forEach((el) => {
    const on = el.dataset.tab === tab;
    el.classList.toggle('active', on);
    if (el.closest('.tab-bar')) el.setAttribute('aria-current', on ? 'page' : 'false');
  });
  const kom = document.getElementById('screen-komunita');
  if (kom) kom.classList.toggle('msg-mode', tab === 'spravy');
  updateStickyBottom();
}
/* Zatvorenie: ak sa stav appky počas návodu nezmenil, vráti sa presne pôvodný odtlačok; ak sa zmenil (switchTab/pushOpenChat počas návodu),
   zobrazí sa AKTUÁLNA karta (nikdy zastaraná). V oboch prípadoch bez renderu a siete; potom krátko potláča stránkovanie pozorovateľov. */
function tourRestoreNav(n) {
  const now = [activeTab, communityMode, communityView, communityChatId];
  if (now.every((v, i) => v === n.app[i])) tourApplyNav(n); else tourShowScreen(tourShownKey());
  tourQuiet = true;
  setTimeout(() => { tourQuiet = false; }, 500);
}
function tourApplyNav(n) {
  document.body.dataset.tab = n.body;
  for (const [s, hidden] of n.screens) document.getElementById('screen-' + s).hidden = hidden;
  const kom = document.getElementById('screen-komunita');
  if (kom) kom.classList.toggle('msg-mode', n.msg);
  for (const [el, on, cur] of n.tabs) {
    el.classList.toggle('active', on);
    if (cur === null) el.removeAttribute('aria-current'); else el.setAttribute('aria-current', cur);
  }
  updateStickyBottom();
}
/* Krok len ZOBRAZÍ kartu. Žiadne switchTab / openMessagesTab / tyLoad, activeTab ani communityMode/ReturnTab/View/Back sa nemenia (bežné
   prepnutie na Community by pre prihláseného používateľa spustilo community_join, leaderboardSend, profileAchievementsSend, pushRefresh a
   načítanie schránky; Správy by prepísali režim a Community pohľad). Pozorovatelia a handlery, ktoré sa riadia activeTab (chat, stránkovanie
   Ty/Community), tak preview nevidia. Obsah sa vykreslí len z lokálnych dát; Community len keď je vypnuté/nenakonfigurované (lokálne úvodné
   okno), inak ostáva obsah, aký tam bol. */
function tourEnterTab(r, tab) {
  if (tab === r.shown) return;
  r.shown = tab;
  tourShowScreen(tab);
  const screen = tab === 'spravy' ? 'komunita' : tab;
  if (screen === 'dnes') renderDnes();
  else if (screen === 'trening') renderTrening();
  else if (screen === 'pokrok') renderPokrok();
  else if (screen === 'ty') renderTy();
  else if (!communityConfigured() || !communityOptIn()) renderCommunity();
  updateStickyBottom();
}

function tourOpen() { return !!tourRun; }
function tourRead() {
  try {
    const v = JSON.parse(localStorage.getItem(TOUR_KEY));
    return v && v.v === 1 && typeof v.status === 'string' ? v : null;
  } catch (e) { return null; }
}
function tourWrite(status) {
  try { localStorage.setItem(TOUR_KEY, JSON.stringify({ v: 1, status, at: new Date().toISOString() })); } catch (e) {}
}
function tourText(v) {
  if (typeof v === 'function') return String(v());
  if (typeof v === 'string' && I18N.en && I18N.en[v] !== undefined) return t(v);
  return v == null ? '' : String(v);
}
/* Cieľ je použiteľný, len ak je naozaj vidieť (nie display:none, nie nulová veľkosť). */
function tourTargetEl(step) {
  let el = null;
  try { el = step.target ? step.target() : null; } catch (e) { el = null; }
  if (!el || !el.isConnected || !el.getClientRects().length) return null;
  const r = el.getBoundingClientRect();
  return r.width > 0 && r.height > 0 ? el : null;
}

/* opts.from: prvok, na ktorý sa po zatvorení vráti fokus (predvolene aktívny prvok). */
function startTour(steps, opts) {
  if (tourRun || !Array.isArray(steps) || !steps.length) return false;
  const from = opts && opts.from;
  const root = document.createElement('div');
  root.id = 'tour';
  root.className = 'tour';
  root.setAttribute('role', 'dialog');
  root.setAttribute('aria-modal', 'true');
  root.setAttribute('aria-labelledby', 'tour-title');
  root.setAttribute('aria-describedby', 'tour-body');
  root.innerHTML =
    '<div class="tour-spot" aria-hidden="true"></div>' +
    '<div class="tour-card" id="tour-card">' +
      '<span class="tour-caret" aria-hidden="true"></span>' +
      '<button type="button" class="btn-icon tour-x" id="tour-close">✕</button>' +
      '<div class="tour-illus" aria-hidden="true" hidden></div>' +
      '<div class="tour-text" aria-live="polite"><h3 class="tour-title" id="tour-title"></h3><p class="tour-body" id="tour-body"></p></div>' +
      '<div class="tour-foot"><span class="tour-count"></span><div class="tour-btns">' +
        '<button type="button" class="btn btn-secondary" id="tour-back"></button>' +
        '<button type="button" class="btn btn-secondary" id="tour-skip"></button>' +
        '<button type="button" class="btn btn-primary" id="tour-next"></button>' +
      '</div></div>' +
    '</div>';
  document.body.appendChild(root);
  tourRun = {
    steps, i: 0, root,
    spot: root.querySelector('.tour-spot'), card: root.querySelector('.tour-card'),
    opener: (from && from.nodeType === 1) ? from : document.activeElement,
    nav: tourSnapshotNav(), shown: tourShownKey(), startScroll: window.scrollY || 0, raf: 0, animUntil: 0, animT: 0,
  };
  const relayout = () => {
    if (!tourRun || tourRun.raf) return;
    tourRun.raf = requestAnimationFrame(() => {
      if (!tourRun) return;
      tourRun.raf = 0;
      if (performance.now() > tourRun.animUntil) tourRun.root.classList.remove('tour-anim');   // posun/zmena veľkosti sa nikdy neanimuje
      tourLayout();
    });
  };
  const keydown = (e) => {
    if (e.key !== 'Tab' || !tourRun) return;
    const f = Array.from(root.querySelectorAll('button, .tour-text[tabindex]')).filter((b) => !b.disabled && b.getClientRects().length);
    if (!f.length) return;
    const a = document.activeElement;
    if (e.shiftKey && (a === f[0] || !root.contains(a))) { e.preventDefault(); f[f.length - 1].focus(); }
    else if (!e.shiftKey && (a === f[f.length - 1] || !root.contains(a))) { e.preventDefault(); f[0].focus(); }
  };
  const focusin = (e) => {   // fokus nesmie uniknúť do appky pod prekryvom
    if (tourRun && !root.contains(e.target)) { const n = document.getElementById('tour-next'); if (n) n.focus(); }
  };
  const block = (e) => { if (!(e.target.closest && e.target.closest('.tour-card'))) e.preventDefault(); };   // pozadie sa nescrolluje
  root.addEventListener('wheel', block, { passive: false });
  root.addEventListener('touchmove', block, { passive: false });
  root.addEventListener('keydown', keydown);
  document.addEventListener('focusin', focusin);
  window.addEventListener('resize', relayout);
  window.addEventListener('orientationchange', relayout);
  const onScroll = (e) => { if (!(e.target && e.target.closest && e.target.closest('.tour-text'))) relayout(); };   // rolovanie textu karty nesmie prepočítať polohu
  window.addEventListener('scroll', onScroll, true);
  if (window.visualViewport) window.visualViewport.addEventListener('resize', relayout);
  /* dialóg sa otvoril (aktualizácia, konflikt synchronizácie, nastavenia…): návod ustúpi. Sleduje sa len atribút hidden. */
  const watch = (m) => mo.observe(m, { attributes: true, attributeFilter: ['hidden'] });
  const mo = new MutationObserver((recs) => {
    for (const rec of recs) for (const n of rec.addedNodes) if (n.nodeType === 1 && n.classList.contains('modal-backdrop')) watch(n);   // dialóg vytvorený až neskôr (napr. „Použiť tu“)
    if (tourRun && tourModalOpen()) closeTour('yield');
  });
  for (const m of document.querySelectorAll('.modal-backdrop')) watch(m);
  mo.observe(document.body, { childList: true });   // len priame deti body
  const lb = document.getElementById('community-lightbox');
  if (lb) mo.observe(lb, { attributes: true, attributeFilter: ['hidden'] });
  tourRun.off = () => {
    mo.disconnect();
    document.removeEventListener('focusin', focusin);
    window.removeEventListener('resize', relayout);
    window.removeEventListener('orientationchange', relayout);
    window.removeEventListener('scroll', onScroll, true);
    if (window.visualViewport) window.visualViewport.removeEventListener('resize', relayout);
  };
  root.addEventListener('click', (e) => {
    const b = e.target.closest ? e.target.closest('button') : null;
    if (!b || !tourRun) return;
    if (b.id === 'tour-next') { if (tourRun.i >= tourRun.steps.length - 1) closeTour('done'); else tourGo(tourRun.i + 1); }
    else if (b.id === 'tour-back') tourGo(tourRun.i - 1);
    else if (b.id === 'tour-skip' || b.id === 'tour-close') closeTour('skipped');
  });
  tourGo(0);
  const nx = document.getElementById('tour-next');
  if (nx) nx.focus();
  return true;
}

/* Dočasná prázdna rezerva na konci stránky (zruší sa pri ďalšom kroku aj pri zatvorení). */
function tourSpacer(r, px) {
  if (!r.spacer && px <= 0) return;
  if (!r.spacer) { r.spacer = document.createElement('div'); r.spacer.setAttribute('aria-hidden', 'true'); r.spacer.style.cssText = 'pointer-events:none;flex:none'; document.body.appendChild(r.spacer); }
  r.spacer.style.height = Math.max(0, px) + 'px';
}

function tourGo(i) {
  const r = tourRun;
  if (!r || i < 0 || i >= r.steps.length) return;
  r.i = i;
  const step = r.steps[i];
  const last = i === r.steps.length - 1;
  const hadFocus = r.root.contains(document.activeElement) ? document.activeElement : null;
  if (step.tab && TOUR_TABS.includes(step.tab)) tourEnterTab(r, step.tab);   // len zobrazenie karty, nič sa nezapisuje
  const q = (s) => r.root.querySelector(s);
  q('#tour-title').textContent = tourText(step.title);
  q('#tour-body').textContent = tourText(step.body);
  q('.tour-text').scrollTop = 0;   // nový krok vždy od začiatku textu
  q('.tour-count').textContent = t('tour.stepOf', { n: i + 1, total: r.steps.length });
  q('#tour-close').setAttribute('aria-label', t('tour.close')); q('#tour-close').title = t('tour.close');
  q('#tour-back').textContent = t('tour.back');
  q('#tour-back').hidden = i === 0;
  q('#tour-skip').textContent = t('tour.skip');
  q('#tour-skip').hidden = last;
  q('#tour-next').textContent = t(last ? 'tour.done' : 'tour.next');
  tourSpacer(r, 0);
  const target = tourTargetEl(step);
  /* Ilustrácia: neaktívna kópia (bez ID-čiek, mimo poradia Tab, skrytá pre čítačky) */
  const il = q('.tour-illus');
  il.textContent = '';
  il.hidden = true;
  if ((!target || step.illusWithTarget) && step.illus) {
    let node = null;
    try { node = step.illus(); } catch (e) { node = null; }
    if (node && node.nodeType === 1) {
      const c = node.cloneNode(true);
      for (const el of [c, ...c.querySelectorAll('*')]) {
        el.removeAttribute('id');
        if (el.matches('button, a, input, select, textarea, [tabindex]')) el.setAttribute('tabindex', '-1');
      }
      c.setAttribute('inert', '');
      il.appendChild(c);
      il.hidden = false;
    }
  }
  if (target) {   // posun len ak cieľ nie je celý v bezpečnej oblasti (zbytočné skákanie stránky by pôsobilo rušivo)
    const cs = getComputedStyle(r.root), top = parseFloat(cs.paddingTop) || 0, bottom = r.root.clientHeight - (parseFloat(cs.paddingBottom) || 0);
    let tr = target.getBoundingClientRect();
    if (tr.top < top || tr.bottom > bottom) {
      try { target.scrollIntoView({ block: 'center', inline: 'nearest', behavior: 'instant' }); }
      catch (e) { try { target.scrollIntoView({ block: 'center' }); } catch (e2) {} }
      tr = target.getBoundingClientRect();
    }
    /* vysoká karta (ilustrácia) sa nezmestí nad ani pod cieľ uprostred obrazovky: cieľ posunieme k hornému okraju, karta ide pod neho */
    const ch = tourCardMetrics(r, bottom - top).want, gap = 12, pad = 6;
    if (bottom - tr.bottom - pad - gap < ch && tr.top - top - pad - gap < ch && tr.height + 2 * pad + gap + ch <= bottom - top) {
      const want = tr.top - pad - top, de = document.documentElement;
      const room = de.scrollHeight - window.innerHeight - window.scrollY;
      if (want > room) tourSpacer(r, Math.ceil(want - room));   // koniec stránky: dočasná rezerva (len rozloženie), aby sa dalo posunúť
      window.scrollBy({ top: want, behavior: 'instant' });
    }
  }
  r.root.classList.toggle('tour-dim', !target);   // bez zvýraznenia stmavíme celú obrazovku
  r.root.dataset.step = step.id || String(i);
  /* plynulý presun zvýraznenia len medzi krokmi – nie pri prvom rozložení, posune ani zmene veľkosti */
  const animate = !!r.laidOut && !window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  r.laidOut = true;
  clearTimeout(r.animT);
  r.root.classList.toggle('tour-anim', animate);
  if (animate) { r.animUntil = performance.now() + 300; r.animT = setTimeout(() => { if (tourRun === r) r.root.classList.remove('tour-anim'); }, 320); }
  tourLayout();
  /* tlačidlo, na ktorom bol fokus, sa mohlo skryť (Späť na kroku 1) – fokus nesmie zostať v prázdne */
  if (hadFocus && (hadFocus.hidden || !hadFocus.getClientRects().length)) q('#tour-next').focus();
  /* po prepnutí karty sa obsah prekreslí – prepočítame znova, keď sa usadí */
  requestAnimationFrame(() => { if (tourRun === r) tourLayout(); });
}

/* Rozmery karty: celý text (nadpis + telo) sa meria bez obmedzenia; pevná časť (ilustrácia, päta, odsadenie) sa nikdy nerolluje, rolluje sa len text.
   want = výška, ktorú karta pri cieli potrebuje (celá, najviac polovica plochy, nie menej ako pevná časť + čitateľný kúsok textu). */
const TOUR_MIN_TEXT = 120;
function tourCardMetrics(r, avail) {
  const text = r.card.querySelector('.tour-text');
  const st = text.scrollTop, mh = text.style.maxHeight, ov = text.style.overflowY;   // meranie bez obmedzenia výšky by scrollTop vynulovalo
  text.style.maxHeight = 'none'; text.style.overflowY = 'visible';
  const natural = r.card.offsetHeight, textH = text.offsetHeight, fixed = natural - textH, minText = Math.min(textH, TOUR_MIN_TEXT);
  text.style.maxHeight = mh; text.style.overflowY = ov; text.scrollTop = st;   // meranie je bez vedľajších účinkov: obmedzenie aj posunutie sa vrátia
  return { text, textH, fixed, minText, want: Math.min(natural, Math.max(fixed + minText, Math.round(avail / 2))) };
}
/* Text dostane najviac `limit - fixed` px; ak sa nezmestí, rolluje sa (fokusovateľná oblasť pre klávesnicu/čítačky). Vráti výslednú výšku karty. */
function tourFitCard(m, limit) {
  const room = Math.max(m.minText, Math.min(m.textH, Math.floor(limit - m.fixed)));
  const scroll = m.textH > room + 1;
  m.text.style.maxHeight = room + 'px';
  m.text.style.overflowY = scroll ? 'auto' : 'visible';
  if (scroll) m.text.setAttribute('tabindex', '0'); else m.text.removeAttribute('tabindex');
  return m.fixed + room;
}
/* Poloha zvýraznenia a karty: karta nad alebo pod cieľom podľa miesta, vždy v zornom poli (bezpečné okraje) a mimo cieľa, kým je
   vedľa neho miesto aspoň na `want`; inak sa preferuje čitateľnosť (obrovský cieľ). */
function tourLayout() {
  const r = tourRun;
  if (!r) return;
  const step = r.steps[r.i];
  const root = r.root, card = r.card, spot = r.spot;
  const cs = getComputedStyle(root);
  const H = root.clientHeight, W = root.clientWidth;
  const padT = parseFloat(cs.paddingTop) || 0, padB = parseFloat(cs.paddingBottom) || 0;
  const avail = Math.max(120, H - padT - padB);
  const caret = card.querySelector('.tour-caret');
  caret.hidden = true;
  const m = tourCardMetrics(r, avail);
  const target = tourTargetEl(step);
  if (!target) {
    spot.hidden = true;
    const ch0 = tourFitCard(m, avail);
    card.style.top = Math.round(padT + Math.max(0, (avail - ch0) / 2)) + 'px';
    return;
  }
  const gap = 12, pad = 6;
  const tr = target.getBoundingClientRect();
  /* zvýraznenie sa orezáva na zorné pole (veľký cieľ presahuje obrazovku) */
  const sx = Math.max(0, tr.left - pad), sy = Math.max(0, tr.top - pad);
  const ex = Math.min(W, tr.right + pad), ey = Math.min(H, tr.bottom + pad);
  spot.hidden = false;
  spot.style.left = sx + 'px'; spot.style.top = sy + 'px';
  spot.style.width = Math.max(0, ex - sx) + 'px'; spot.style.height = Math.max(0, ey - sy) + 'px';
  const below = H - padB - ey - gap, above = sy - padT - gap;
  let top, place, ch;
  if (below >= m.want) { ch = tourFitCard(m, below); top = ey + gap; place = 'below'; }
  else if (above >= m.want) { ch = tourFitCard(m, above); top = sy - gap - ch; place = 'above'; }
  else { ch = tourFitCard(m, avail); place = below >= above ? 'below' : 'above'; top = place === 'below' ? H - padB - ch : padT; }   // obrovský cieľ: karta ho čiastočne zakryje, no zostane čitateľná
  top = Math.min(Math.max(top, padT), Math.max(padT, H - padB - ch));
  card.style.top = Math.round(top) + 'px';
  /* šípka ukazuje na stred cieľa (fyzická poloha, takže funguje rovnako v RTL); ak karta cieľ prekrýva, šípka by klamala */
  const cr = card.getBoundingClientRect();
  caret.hidden = top < ey && top + ch > sy;
  caret.style.left = Math.min(Math.max((sx + ex) / 2 - cr.left, 22), Math.max(22, cr.width - 22)) + 'px';
  card.dataset.place = place;
}

/* reason: 'done' | 'skipped' sa zapíše ako stav (hotový návod sa nepreklopí na preskočený); iný dôvod (napr. 'yield') ho len zavrie. */
function closeTour(reason) {
  const r = tourRun;
  if (!r) return false;
  tourRun = null;
  if (r.raf) cancelAnimationFrame(r.raf);
  clearTimeout(r.animT);
  if (r.spacer) r.spacer.remove();
  r.off();
  r.root.remove();
  if ((reason === 'done' || reason === 'skipped') && !(tourRead() && tourRead().status === 'done')) tourWrite(reason);
  tourRestoreNav(r.nav);   // bez switchTab / renderu / načítania: pôvodný odtlačok, alebo aktuálna karta ak sa stav počas návodu zmenil
  if (r.opener && r.opener.isConnected && r.opener.focus) { try { r.opener.focus({ preventScroll: true }); } catch (e) {} }
  try { window.scrollTo({ top: r.startScroll, behavior: 'instant' }); } catch (e) { window.scrollTo(0, r.startScroll); }   // stránka sa vráti tam, kde používateľ bol
  renderTourInvite();   // po Preskočiť / Hotovo karta s pozvánkou zmizne
  refreshBackupOffer();   // záloha čakala, kým návod beží
  return true;
}

