/* Jeden krok späť. Poradie: najvrchnejší dialóg → vnorený panel → podpohľad karty → karta Dnes
   → appka do pozadia (ako na Androide 12+, nič sa neukončí – bežiaci tréning pokračuje).
   Vracia 'closed' | 'view' | 'home' | 'background' | 'blocked'. */
function nativeBack() {
  if (tourOpen()) { closeTour('skipped'); return 'closed'; }   // návod je nad všetkým (nie je .modal-backdrop)
  const lightbox = document.getElementById('community-lightbox');   // fotka z Community (nad všetkým, nie je .modal-backdrop)
  if (lightbox && !lightbox.hidden) { lightbox.hidden = true; lightbox.innerHTML = ''; return 'closed'; }
  const open = Array.from(document.querySelectorAll('.modal-backdrop')).filter((m) => !m.hidden);
  const top = open[open.length - 1];
  if (top) {
    const ctPanel = document.getElementById('custom-timer');
    if (top.id === 'modal-rest' && ctPanel && !ctPanel.hidden) { hideCustomTimer(); return 'view'; }
    if (top.id === 'modal-rest' && presetManageMode) { setPresetManageMode(false); return 'view'; }
    if (top.id === 'modal-programs' && programsCanStepBack()) { programsBack(); return 'view'; }
    const entry = NATIVE_BACK_CLOSE.find((e) => e[0] === top.id);
    if (entry && entry[1] === null) return 'blocked';
    const btn = entry ? document.querySelector(entry[1]) : null;
    if (btn && !btn.disabled) btn.click();
    else { top.hidden = true; refreshUpdateBanner(); }   // dialóg bez tlačidla (napr. prázdny) – len zavrieť
    return 'closed';
  }
  if (sessionMenuOpen()) { closeSessionMenu(); return 'closed'; }   // ⋯ menu tréningu
  if (editingPlan !== null) { document.getElementById('btn-edit-cancel').click(); return 'view'; }
  if (activeTab === 'komunita' && (communityBack.length || communityReturnTab
      || (communityMode === 'messages' ? communityView !== 'chats' : communityView !== 'feed'))) {
    communityGoBack();
    return 'view';
  }
  if (activeTab === 'pokrok' && pokrokView !== 'stats') { setPokrokView('stats'); window.scrollTo(0, 0); return 'view'; }
  if (activeTab === 'kalendar') { document.getElementById('back-calendar').click(); return 'view'; }
  if (activeTab !== 'dnes') { switchTab('dnes'); window.scrollTo(0, 0); return 'home'; }
  const app = nativePlugin('App');
  if (app) app.minimizeApp().catch(() => {});
  return 'background';
}

/* Upozornenia v Android appke. Povolenie (Android 13+) je jedno pre pripomienky aj správy;
   "zapnuté" = povolené A toto zariadenie je priradené prihlásenému účtu (ako na webe). */
let nativeNotifPerm = 'prompt';   // 'granted' | 'denied' | 'prompt' (posledná známa hodnota)
async function nativeRefreshPerm() {
  const ln = nativePlugin('LocalNotifications');
  if (!ln) return nativeNotifPerm;
  try { const r = await ln.checkPermissions(); nativeNotifPerm = (r && r.display) || 'prompt'; } catch (e) {}
  return nativeNotifPerm;
}
function nativePushState() {
  if (nativeNotifPerm === 'denied') return 'denied';
  const dev = pushDeviceRead();
  const me = communityProfile && communityProfile.id;
  return nativeNotifPerm === 'granted' && dev && me && dev.uid === me ? 'on' : 'off';
}

/* Pripomienky v telefóne: tie isté nastavenia účtu (reminders_get), ale plánuje ich Android
   (LocalNotifications), takže chodia aj bez siete. Server ich posiela len na webové odbery, preto
   nevznikajú dvojité. Voda každých N minút od–do vrátane (ako reminders_due), jedlá v ich čase,
   tréning v zvolené dni (ISO Po=1 → Android Ne=1). ID: voda 1000+, jedlá 2000+, tréning 3000+, vlastné 3100–3179. */
const NATIVE_REM_TEXT = {
  water: { sk: '💧 Čas napiť sa vody', en: '💧 Time to drink some water', es: '💧 Hora de beber agua',
    'pt-BR': '💧 Hora de beber água', fr: '💧 C’est le moment de boire de l’eau', ar: '💧 حان وقت شرب الماء' },
  meal: { sk: '🍽️ Čas na jedlo', en: '🍽️ Time to eat', es: '🍽️ Hora de comer',
    'pt-BR': '🍽️ Hora de comer', fr: '🍽️ C’est l’heure de manger', ar: '🍽️ حان وقت الأكل' },
  workout: { sk: '🏋️ Dnes je tréningový deň – poď na to!', en: '🏋️ It’s workout time – let’s go!', es: '🏋️ ¡Hora de entrenar, vamos!',
    'pt-BR': '🏋️ Hora de treinar – bora!', fr: '🏋️ C’est l’heure de l’entraînement – on y va !', ar: '🏋️ حان وقت التمرين – هيا بنا!' },
};
function nativeReminderSchedule(d) {
  const out = [];
  if (!d) return out;
  const mins = (v) => { const m = /^(\d{1,2}):(\d{2})/.exec(String(v || '')); return m ? Number(m[1]) * 60 + Number(m[2]) : null; };
  const note = (id, kind, m, weekday, text) => {
    const on = { hour: Math.floor(m / 60), minute: m % 60 };
    if (weekday) on.weekday = weekday;
    return { id, title: 'GymQuest', body: text || NATIVE_REM_TEXT[kind][activeLang()] || NATIVE_REM_TEXT[kind].en,
      channelId: 'reminders', smallIcon: 'ic_stat_gq', schedule: { on, allowWhileIdle: true },
      isExactNotification: false };   // presné budíky appka nemá (Play) – inak by plugin pri plánovaní otváral nastavenia
  };
  if (d.water_on && d.water_mode === 'times') {   // 0019: voda v presných časoch (až 12)
    const ts = (Array.isArray(d.water_times) ? d.water_times : []).map(mins).filter((m) => m !== null);
    Array.from(new Set(ts)).sort((a, b) => a - b).slice(0, 12).forEach((m, i) => out.push(note(1000 + i, 'water', m)));
  } else if (d.water_on) {
    const from = mins(d.water_from), to = mins(d.water_to), every = Math.max(30, Number(d.water_every) || 120);
    if (from !== null && to !== null) for (let m = from, i = 0; m <= to && i < 48; m += every, i++) out.push(note(1000 + i, 'water', m));
  }
  if (d.meals_on && Array.isArray(d.meal_times)) {
    d.meal_times.slice(0, 6).forEach((v, i) => { const m = mins(v); if (m !== null) out.push(note(2000 + i, 'meal', m)); });
  }
  if (d.workout_on && Array.isArray(d.workout_days)) {
    const m = mins(d.workout_time);
    if (m !== null) Array.from(new Set(d.workout_days.map(Number))).filter((x) => x >= 1 && x <= 7).sort((a, b) => a - b)
      .forEach((iso) => out.push(note(3000 + iso, 'workout', m, (iso % 7) + 1)));
  }
  /* Vlastné pripomienky (0019): ID 3100 + 8 × poradie + (0 = každý deň, inak ISO deň 1–7); text používateľa
     ako obyčajný text (nikdy HTML). Všetky dni = jedno denné upozornenie. */
  if (Array.isArray(d.custom)) {
    d.custom.slice(0, 10).forEach((c, idx) => {
      const m = mins(c && c.time), text = remindersCleanText(c && c.text);
      const days = Array.from(new Set(((c && c.days) || []).map(Number))).filter((x) => x >= 1 && x <= 7).sort((a, b) => a - b);
      if (m === null || !text || !days.length) return;
      if (days.length === 7) out.push(note(3100 + idx * 8, 'custom', m, 0, text));
      else days.forEach((iso) => out.push(note(3100 + idx * 8 + iso, 'custom', m, (iso % 7) + 1, text)));
    });
  }
  return out;
}
/* Zruší naše naplánované pripomienky a naplánuje aktuálne – len ak sú upozornenia v tomto
   telefóne zapnuté pre prihlásený účet. Volania idú za sebou (nikdy dve naraz). */
let nativeRemChain = Promise.resolve();
const NATIVE_REM_LAST_KEY = 'gymquest_reminders_last';   // { uid, data } – posledné známe nastavenia (štart bez siete)
function nativeRemindersApply() {
  const run = async () => {
    const ln = nativePlugin('LocalNotifications');
    if (!ln) return;
    /* "vypnuté" len keď to naozaj vieme: zariadenie bez záznamu (odhlásené / vypnuté), bez povolenia
       alebo prihlásený iný účet. Nenačítaný profil či nastavenia (bez siete) nie sú "vypnuté" –
       vtedy sa použijú posledné známe nastavenia tohto účtu. */
    await nativeRefreshPerm();
    const dev = pushDeviceRead();
    const me = communityProfile && communityProfile.id;
    const off = !dev || nativeNotifPerm !== 'granted' || (!!me && dev.uid !== me);
    let data = null;
    if (!off) {
      if (me && remindersData) {
        data = remindersData;
        try { localStorage.setItem(NATIVE_REM_LAST_KEY, JSON.stringify({ uid: me, data })); } catch (e) {}
      } else {
        try { const last = JSON.parse(localStorage.getItem(NATIVE_REM_LAST_KEY) || 'null'); if (last && last.uid === dev.uid) data = last.data; } catch (e) {}
      }
    }
    if (!off && !data) return;   // nastavenia ešte nepoznáme (štart bez siete) – naplánované pripomienky zostanú
    try {
      const pend = await ln.getPending();
      const ours = ((pend && pend.notifications) || []).filter((n) => n.id >= 1000 && n.id < 4000).map((n) => ({ id: n.id }));
      if (ours.length) await ln.cancel({ notifications: ours });
    } catch (e) {}
    if (off) return;
    const list = nativeReminderSchedule(data);
    if (list.length) { try { await ln.schedule({ notifications: list }); } catch (e) {} }
  };
  nativeRemChain = nativeRemChain.then(run, run);
  return nativeRemChain;
}

/* Správy cez Firebase Cloud Messaging (migrácia 0016). Web Push vo WebView nefunguje, preto sa
   token FCM uloží cez push_fcm_register; funkcia `push` ho použije popri webových odberoch.
   Server bez 0016 (funkcia chýba) → prepínač sa skryje (nativeFcmMissing). */
let nativeFcmMissing = false;
let nativeFcmWaiters = [];
function nativeFcmToken() {
  const pn = nativePlugin('PushNotifications');
  if (!pn) return Promise.reject(new Error('no_plugin'));
  return new Promise((resolve, reject) => {
    const w = {};
    const timer = setTimeout(() => w.reject(new Error('fcm_timeout')), 20000);
    w.resolve = (v) => { clearTimeout(timer); nativeFcmWaiters = nativeFcmWaiters.filter((x) => x !== w); resolve(v); };
    w.reject = (e) => { clearTimeout(timer); nativeFcmWaiters = nativeFcmWaiters.filter((x) => x !== w); reject(e); };
    nativeFcmWaiters.push(w);
    pn.register().catch((e) => w.reject(e));
  });
}
function nativeFcmMissingError(err) {
  const txt = String((err && (err.code + ' ' + err.message)) || '');
  return /PGRST202|could not find the function|function .* does not exist/i.test(txt);
}
async function nativeFcmSave(sb, uid, token) {
  let r;
  try { r = await sb.rpc('push_fcm_register', { p_token: token, p_lang: activeLang() }); } catch (e) { r = { error: e }; }
  if (r && r.error) { if (nativeFcmMissingError(r.error)) nativeFcmMissing = true; return false; }
  pushDeviceWrite({ uid, fcm: token });
  return true;
}
function nativePermFrom(receive) { return receive === 'granted' ? 'granted' : (receive === 'denied' ? 'denied' : 'prompt'); }
async function nativePushEnable() {
  const sb = communityClient();
  const me = communityProfile && communityProfile.id;
  const pn = nativePlugin('PushNotifications');
  if (pushBusy || !sb || !me || !pn || !pushAvailable()) return;
  pushBusy = true;
  let msg = 'push.on';
  try {
    const perm = await pn.requestPermissions();
    nativeNotifPerm = nativePermFrom(perm && perm.receive);
    if (nativeNotifPerm !== 'granted') { msg = nativeNotifPerm === 'denied' ? 'push.denied' : 'push.notAllowed'; return; }
    const token = await nativeFcmToken();
    if (!(await nativeFcmSave(sb, me, token))) {
      msg = 'push.errFailed';
      if (nativeFcmMissing) { try { await pn.unregister(); } catch (e) {} }
      return;
    }
    await remindersEnsureDefaults(sb);   // pripomienky sú predvolene zapnuté (ako na webe)
    nativeRemindersApply();
  } catch (e) {
    msg = 'push.errFailed';
  } finally {
    pushBusy = false;
    remindersPushFeedback(msg);
  }
}
/* Odhlásenie, vypnutie, opustenie Community: token preč zo servera aj z FCM, pripomienky zrušené. */
async function nativePushDisable(sb, rpc) {
  const dev = pushDeviceRead();
  pushDeviceWrite(null);
  try { localStorage.removeItem(NATIVE_REM_LAST_KEY); } catch (e) {}
  if (rpc && dev && dev.fcm) { try { await sb.rpc('push_fcm_unregister', { p_token: dev.fcm }); } catch (e) {} }
  const pn = nativePlugin('PushNotifications');
  if (pn) { try { await pn.unregister(); } catch (e) {} }
  await nativeRemindersApply();
}
/* Po prihlásení a pri zmene jazyka: zapnutý telefón sa obnoví na serveri (token, jazyk). */
async function nativePushRefresh(sb, uid) {
  const dev = pushDeviceRead();
  if (dev && uid && dev.uid !== uid) {
    /* Telefón zostal prihlásený k inému účtu (relácia sa stratila bez odhlásenia): token FCM sa zmaže,
       server ho pri ďalšej správe vyradí (UNREGISTERED) – upozornenia cudzieho účtu sem už neprídu. */
    pushDeviceWrite(null);
    const pn = nativePlugin('PushNotifications');
    if (pn) { try { await pn.unregister(); } catch (e) {} }
    nativeRemindersApply();
    return;
  }
  if (!dev || !uid || !sb || !pushAvailable()) return;
  if ((await nativeRefreshPerm()) !== 'granted') { if (nativeNotifPerm === 'denied') pushDeviceWrite(null); return; }
  try { await nativeFcmSave(sb, uid, await nativeFcmToken()); } catch (e) { /* bez siete: skúsi sa pri ďalšom spustení */ }
  await remindersEnsureDefaults(sb);
  nativeRemindersApply();
}
/* FCM vydal nový token mimo zapínania (obnova) → uloží sa, ak sú upozornenia zapnuté. */
function nativeOnFcmToken(ev) {
  const token = ev && ev.value;
  if (!token) return;
  if (nativeFcmWaiters.length) { nativeFcmWaiters.slice().forEach((w) => w.resolve(token)); return; }
  const dev = pushDeviceRead();
  const sb = communityClient();
  if (sb && dev && dev.fcm !== token && nativePushState() === 'on') nativeFcmSave(sb, dev.uid, token);
}
/* Otvorený chat: jeho upozornenia v lište sa zatvoria. */
async function nativeClearChat(cid) {
  const pn = nativePlugin('PushNotifications');
  if (!pn) return;
  try {
    const d = await pn.getDeliveredNotifications();
    const mine = ((d && d.notifications) || []).filter((n) => n && (n.tag === 'gq-chat-' + cid || (n.data && n.data.conv === cid)));
    if (mine.length) await pn.removeDeliveredNotifications({ notifications: mine });
  } catch (e) {}
}

/* ---------- Health Connect (Android) ----------
   Voliteľné (Nastavenia). Po tréningu sa do Health Connect zapíše cvičenie (id = id tréningu,
   skutočný začiatok a koniec) a z neho sa prečíta tep a aktívne kalórie z hodiniek za ten čas.
   V histórii: entry.health = { start, end, hrAvg?, hrMax?, kcal?, readAt? } – len hodnoty, ktoré
   naozaj existujú (nikdy nuly). Synchronizuje sa so súkromnou zálohou ako zvyšok tréningu, ale do
   Community (príspevky, zdieľanie, chaty, rebríček) sa nikdy nedostane – tie berú len vybrané polia.
   Hodinky sa niekedy synchronizujú neskôr: návrat do appky skúsi tréningy z posledných 2 hodín
   a v detaile dňa je "Obnoviť tep". Plugin GymHealth je v appke (Kotlin). */
const HEALTH_RETRY_MS = 2 * 3600 * 1000;
let healthStatusKey = '';
const healthWrites = {};   // id tréningu → prebiehajúci zápis do Health Connect
function healthOn() { return isNativeApp() && !!(state && state.settings && state.settings.healthConnect) && !!nativePlugin('GymHealth'); }
function renderHealthSetting() {
  const block = document.getElementById('health-setting');
  if (!block) return;
  block.hidden = !isNativeApp() || !nativePlugin('GymHealth');
  if (block.hidden) return;
  document.getElementById('health-switch').checked = !!state.settings.healthConnect;
  const st = document.getElementById('health-status');
  st.textContent = healthStatusKey ? t(healthStatusKey) : '';
  st.hidden = !healthStatusKey;
}
async function healthToggle(on) {
  const hc = nativePlugin('GymHealth');
  const off = (key) => { state.settings.healthConnect = false; healthStatusKey = key || ''; saveState(); renderHealthSetting(); };
  if (!on || !hc) { off(''); return; }
  try {
    const a = await hc.isAvailable();
    if (!a || !a.available) { off('health.unavailable'); return; }
    const g = await hc.requestPermissions();
    if (!g || !Array.isArray(g.granted) || !g.granted.length) { off('health.denied'); return; }
  } catch (e) { off('health.unavailable'); return; }
  state.settings.healthConnect = true;
  healthStatusKey = '';
  saveState();
  renderHealthSetting();
}
/* Povolenie mohlo byť medzitým odobraté v Health Connect → prepínač sa vypne s poznámkou. */
async function healthRecheck() {
  const hc = nativePlugin('GymHealth');
  if (!hc || !isNativeApp() || !state.settings.healthConnect) return;
  let g = null;
  try { g = await hc.checkPermissions(); } catch (e) { return; }
  if (g && Array.isArray(g.granted) && !g.granted.length) {
    state.settings.healthConnect = false;
    healthStatusKey = 'health.denied';
    saveState();
    renderHealthSetting();
  }
}
function healthStatsFrom(r) {
  const out = {};
  if (r && Number(r.hrCount) > 0 && Number.isFinite(Number(r.hrAvg)) && Number(r.hrAvg) > 0) {
    out.hrAvg = Math.round(Number(r.hrAvg));
    if (Number.isFinite(Number(r.hrMax)) && Number(r.hrMax) > 0) out.hrMax = Math.round(Number(r.hrMax));
  }
  if (r && Number.isFinite(Number(r.kcal)) && Number(r.kcal) > 0) out.kcal = Math.round(Number(r.kcal));
  return out;
}
/* Prečíta tep za čas tréningu a uloží ho k tréningu. Nové hodnoty prepíšu staré; keď nič nepríde,
   staré zostanú. */
async function healthReadInto(id) {
  const hc = nativePlugin('GymHealth');
  const w = state.history.find((x) => x.id === id);
  if (!hc || !w || !w.health) return false;
  delete hrCache[id];   // nové čítanie → aj krivka sa načíta znova
  let r;
  try { r = await hc.readStats({ start: w.health.start, end: w.health.end }); } catch (e) { return false; }
  const cur = state.history.find((x) => x.id === id);   // medzitým mohol byť zmazaný
  if (!cur || !cur.health) return false;
  cur.health = Object.assign({}, cur.health, healthStatsFrom(r), { readAt: new Date().toISOString() });
  saveState();
  if (lastWorkoutId === id && !document.getElementById('modal-result').hidden) renderResultHealth(cur);
  const dayModal = document.getElementById('modal-day');
  if (dayModal && !dayModal.hidden && selectedDayKey) renderDayDetail(selectedDayKey);
  return true;
}
async function nativeHealthAfterFinish(entry) {
  if (!entry || !entry.health || !healthOn()) return;
  const hc = nativePlugin('GymHealth');
  const write = hc.writeWorkout({ id: entry.id, start: entry.health.start, end: entry.health.end, title: historyPlanName(entry) }).catch(() => {});
  healthWrites[entry.id] = write;   // rýchle "Vrátiť späť" počká na zápis, inak by v Health Connect zostal duch
  await write;
  if (healthWrites[entry.id] === write) delete healthWrites[entry.id];
  await healthReadInto(entry.id);
}
function healthRetryRecent() {
  if (!healthOn()) return;
  const now = Date.now();
  state.history.filter((w) => w.health && !('hrAvg' in w.health) && now - Date.parse(w.health.end) < HEALTH_RETRY_MS)
    .forEach((w) => { healthReadInto(w.id); });
}
/* Vrátený alebo zmazaný tréning zmizne aj z Health Connect. */
function healthDeleteSession(entry) {
  if (!entry || !entry.health) return;
  const hc = nativePlugin('GymHealth');
  if (hc) Promise.resolve(healthWrites[entry.id]).then(() => hc.deleteWorkout({ id: entry.id })).catch(() => {});
}
function healthLineText(w) {
  const h = w && w.health;
  if (!h) return '';
  const parts = [];
  if (h.hrAvg) parts.push(t('health.hr', { avg: h.hrAvg, max: h.hrMax || h.hrAvg }));
  if (h.kcal) parts.push(t('health.kcal', { kcal: h.kcal }));
  return parts.join(' · ');
}
function renderResultHealth(entry) {
  const el = document.getElementById('result-health');
  if (!el) return;
  const txt = isNativeApp() ? healthLineText(entry) : '';
  el.textContent = txt;
  el.hidden = !txt;
}
/* Graf tepu v detaile tréningu. Vzorky sa čítajú z Health Connect na požiadanie a držia sa len v pamäti
   (hrCache) – nikdy v state, localStorage, zálohe ani Community. */
const HR_MAX_POINTS = 300;
const hrCache = {};   // id tréningu → Promise s { samples } alebo { error }
function healthHrClean(r, w) {
  const a = Date.parse(w.health.start), b = Date.parse(w.health.end);
  const raw = r && Array.isArray(r.samples) ? r.samples : [];
  const out = raw.map((x) => ({ t: Number(x && x.t), bpm: Math.round(Number(x && x.bpm)) }))
    .filter((x) => Number.isFinite(x.t) && x.t >= a && x.t <= b && x.bpm >= 25 && x.bpm <= 250)
    .sort((p, q) => p.t - q.t);
  if (out.length <= HR_MAX_POINTS) return out;
  const step = out.length / HR_MAX_POINTS, keep = [];
  for (let i = 0; i < HR_MAX_POINTS; i++) {   // poistka: z každého kusa ostane najvyšší tep
    let best = null;
    for (let j = Math.floor(i * step); j < Math.floor((i + 1) * step); j++) if (!best || out[j].bpm > best.bpm) best = out[j];
    if (best) keep.push(best);
  }
  return keep;
}
function healthHrLoad(w) {
  if (!hrCache[w.id]) {
    const hc = nativePlugin('GymHealth');
    const id = w.id;
    const pr = hrCache[id] = Promise.resolve().then(() => hc.heartRateSamples({ start: w.health.start, end: w.health.end }))
      .then((r) => ({ samples: healthHrClean(r, w) }))
      .catch((e) => ({ error: /denied/.test(String(e && e.message || e)) ? 'denied' : 'error' }));
    // v pamäti ostane len úspešný neprázdny výsledok; chyba alebo prázdno sa pri ďalšom otvorení skúsi znova
    pr.then((r) => { if (r.error || !r.samples || r.samples.length < 2) { if (hrCache[id] === pr) delete hrCache[id]; } });
  }
  return hrCache[w.id];
}
/* Čas osi x je v minútach od začiatku; os plynie vždy zľava doprava (ako graf mier). */
function buildHrChart(box, samples, w) {
  const ns = 'http://www.w3.org/2000/svg';
  const W = Math.max(Math.round(box.clientWidth) || 300, 240), H = 170;
  const t0 = Date.parse(w.health.start), t1 = Date.parse(w.health.end);
  const mins = Math.max((t1 - t0) / 60000, 1);
  const bpms = samples.map((p) => p.bpm);
  const lo = Math.min(...bpms), hi = Math.max(...bpms);
  const mean = Math.round(bpms.reduce((a, b) => a + b, 0) / bpms.length);
  const avg = w.health.hrAvg || mean;
  const svg = document.createElementNS(ns, 'svg');
  svg.setAttribute('class', 'chart-svg hr-svg');
  svg.setAttribute('viewBox', '0 0 ' + W + ' ' + H);
  svg.setAttribute('width', W);
  svg.setAttribute('height', H);
  svg.setAttribute('role', 'img');
  svg.setAttribute('aria-label', t('health.chart.aria', { n: samples.length, min: lo, max: hi, avg }));
  box.appendChild(svg);
  const fs = parseFloat(getComputedStyle(svg).fontSize) || 11;
  const cw = fs * 0.62;
  const nice = chartNiceTicks(Math.min(lo, avg), Math.max(hi, avg));
  const tickTxt = nice.ticks.map((v) => v.toFixed(nice.decimals));
  const yW = Math.max(...tickTxt.map((s) => s.length)) * cw;
  const avgTxt = t('health.chart.avg', { n: avg }), lw = avgTxt.length * cw + 4;
  const side = lw <= W * 0.22;   // popisok priemeru v pravom okraji (krivka tam nikdy nie je); inak nad/pod čiarou
  const L = Math.ceil(yW + 8), R = W - 8 - (side ? Math.ceil(lw) + 4 : 0), T = 20, B = H - 26;
  const yMin = nice.ticks[0], yMax = nice.ticks[nice.ticks.length - 1];
  const x = (ms) => L + ((ms - t0) / (t1 - t0)) * (R - L);
  const y = (v) => B - ((v - yMin) / (yMax - yMin)) * (B - T);
  const mk = (tag, attrs, text) => {
    const e = document.createElementNS(ns, tag);
    for (const k of Object.keys(attrs)) e.setAttribute(k, attrs[k]);
    if (text !== undefined) e.textContent = text;
    return e;
  };
  nice.ticks.forEach((v, i) => {
    svg.appendChild(mk('line', { class: 'chart-grid', x1: L, x2: R, y1: y(v).toFixed(1), y2: y(v).toFixed(1) }));
    svg.appendChild(mk('text', { class: 'chart-axis', x: L - 6, y: (y(v) + fs * 0.35).toFixed(1), 'text-anchor': 'end' }, tickTxt[i]));
  });
  const stepMin = [1, 2, 5, 10, 15, 20, 30, 60, 120].find((s) => mins / s <= 5) || 120;
  for (let m = 0; m <= mins + 1e-6; m += stepMin) {
    const mxp = x(t0 + m * 60000);
    svg.appendChild(mk('text', { class: 'chart-axis', x: mxp.toFixed(1), y: H - 8, 'text-anchor': m === 0 ? 'start' : (mxp > R - 3 * cw ? 'end' : 'middle') }, m === 0 ? '0 ' + t('health.chart.min') : String(m)));
  }
  const pts = samples.map((p) => [x(p.t), y(p.bpm)]);
  const line = pts.map(([px, py], i) => (i ? 'L' : 'M') + px.toFixed(1) + ' ' + py.toFixed(1)).join(' ');
  if (pts.length > 1) {
    svg.appendChild(mk('path', { class: 'chart-area', d: line + ' L' + pts[pts.length - 1][0].toFixed(1) + ' ' + B + ' L' + pts[0][0].toFixed(1) + ' ' + B + ' Z' }));
    svg.appendChild(mk('path', { class: 'chart-line hr-line', d: line }));
  }
  svg.appendChild(mk('line', { class: 'hr-avg', x1: L, x2: R, y1: y(avg).toFixed(1), y2: y(avg).toFixed(1) }));
  /* Popisok priemeru (keď sa nezmestí do okraja): z miest pozdĺž čiary (nad/pod) vyberie to, kde je krivka najďalej od textu (pri zhode radšej vpravo). */
  const ay = y(avg);
  let bestC = null;
  for (let k = 0; k <= 12 && !side; k++) {
    for (const above of [true, false]) {
      const x0 = R - lw - (k / 12) * (R - L - lw), ty = above ? ay - 4 : ay + fs + 2;
      if (ty - fs < T - 8 || ty > B) continue;   // zostane v ploche grafu
      const x1 = x0 + lw, y0 = ty - fs, y1 = ty + 2;
      let clear = Infinity;
      for (const [px, py] of pts) {
        if (px < x0 - 3 || px > x1 + 3) continue;
        clear = Math.min(clear, py < y0 ? y0 - py : (py > y1 ? py - y1 : 0));
      }
      if (!bestC || clear > bestC.clear + 0.5) bestC = { clear, x0, ty };
    }
  }
  if (side) bestC = { x0: R + 4, ty: ay + fs * 0.35 };
  else if (!bestC) bestC = { x0: R - lw, ty: ay - 4 };
  svg.appendChild(mk('text', { class: 'chart-axis hr-avg-label', x: bestC.x0.toFixed(1), y: bestC.ty.toFixed(1), 'text-anchor': 'start' }, avgTxt));
  const mi = bpms.indexOf(hi), [mx, my] = pts[mi];
  svg.appendChild(mk('circle', { class: 'chart-dot hr-max', cx: mx.toFixed(1), cy: my.toFixed(1), r: 4.5 }));
  svg.appendChild(mk('text', { class: 'chart-axis hr-max-label', x: Math.min(Math.max(mx, L + 24), R - 24).toFixed(1), y: Math.max(my - 9, fs).toFixed(1), 'text-anchor': 'middle' }, t('health.chart.max', { n: hi })));
  return svg;
}
/* Po vykreslení detailu dňa: každý placeholder dostane graf, načítanie alebo poznámku. */
function healthHrChartsMount(root) {
  if (!healthOn()) return;
  (root || document).querySelectorAll('[data-hr-chart]').forEach((box) => {
    const w = state.history.find((x) => x.id === box.dataset.hrChart);
    if (!w || !w.health || !w.health.start || !w.health.end) return;
    const note = (key) => { box.innerHTML = `<p class="card-note hr-note">${esc(t(key))}</p>`; };
    note('health.chart.loading');
    healthHrLoad(w).then((r) => {
      if (!box.isConnected) return;
      box.innerHTML = '';
      if (r.error === 'denied') return note('health.chart.denied');
      if (r.error || !r.samples || r.samples.length < 2) return note('health.chart.empty');
      buildHrChart(box, r.samples, w);
    });
  });
}
/* Detail dňa: tep tréningu; bez dát (alebo prečítané krátko po tréningu) tlačidlo "Obnoviť tep". */
function healthDayHtml(w) {
  if (!isNativeApp() || !w || !w.health) return '';
  const txt = healthLineText(w);
  const readAt = Date.parse(w.health.readAt || '') || 0;
  const canRefresh = !!nativePlugin('GymHealth') && (!w.health.hrAvg || readAt < Date.parse(w.health.end) + 24 * 3600 * 1000);
  const chart = healthOn() && w.health.start && w.health.end ? `<div class="hr-chart" data-hr-chart="${escAttr(w.id)}"></div>` : '';
  return `<div class="day-ex-meta health-line">${esc(txt || t('health.none'))}</div>`
    + chart
    + (canRefresh ? `<button type="button" class="btn btn-secondary btn-sm health-refresh" data-health-refresh="${escAttr(w.id)}">${esc(t('health.refresh'))}</button>` : '');
}

let nativeStarted = false;
/* Raz po prvom vykreslení: skryje spúšťaciu obrazovku a zapojí natívne udalosti. */
function nativeInit() {
  if (!isNativeApp() || nativeStarted) return;
  nativeStarted = true;
  initWearBridge();
  const splash = nativePlugin('SplashScreen');
  if (splash) splash.hide().catch(() => {});
  nativeThemeBars(themeResolved());   // tému pri štarte nastavuje skript v <head>, lišta sa zladí tu
  nativeNavMode();
  window.addEventListener('resize', nativeNavMode);   // otočenie / zmena režimu navigácie
  const app = nativePlugin('App');
  if (app) {
    app.addListener('backButton', () => { nativeBack(); });
    app.addListener('resume', () => { nativeNavMode(); nativeRemindersApply(); healthRecheck().then(healthRetryRecent); workoutPhaseReconcile(); workoutPhaseCapabilities(); workoutPhaseCommunityReprobe(); if (timerInterval !== null) nativeRestSync(); });
  }
  const ln = nativePlugin('LocalNotifications');
  if (ln) ln.createChannel({ id: 'reminders', name: t('rem.title'), importance: 3 }).catch(() => {});
  const pn = nativePlugin('PushNotifications');
  if (pn) {
    pn.createChannel({ id: 'messages', name: t('push.title'), importance: 4 }).catch(() => {});
    pn.addListener('registration', nativeOnFcmToken);
    pn.addListener('registrationError', (e) => { nativeFcmWaiters.slice().forEach((w) => w.reject(new Error((e && e.error) || 'fcm_error'))); });
    pn.addListener('pushNotificationActionPerformed', (a) => {
      const d = a && a.notification && a.notification.data;
      if (d && d.type === 'chat' && d.conv) pushOpenChat(d.conv);   // ťuknutie na upozornenie → ten chat
    });
  }
  nativeRefreshPerm();
}

function registerServiceWorker() {
  if (isNativeApp()) return;   // Android appka: súbory sú v appke, aktualizácie cez obchod
  if (!('serviceWorker' in navigator)) return;
  // file:// nemá service workery – lokálne otvorenie súboru funguje ďalej bez zmeny
  if (location.protocol !== 'http:' && location.protocol !== 'https:') return;

  navigator.serviceWorker.register('sw.js', { updateViaCache: 'none' }).then((reg) => {
    swRegistration = reg;
    // verzia mohla čakať už z minulej návštevy
    if (reg.waiting && navigator.serviceWorker.controller) {
      swUpdateReady = true;
      refreshUpdateBanner();
    }
    reg.addEventListener('updatefound', () => {
      const incoming = reg.installing;
      if (!incoming) return;
      incoming.addEventListener('statechange', () => {
        // 'installed' + existujúci kontrolór = čaká novšia verzia
        if (incoming.state === 'installed' && navigator.serviceWorker.controller) {
          swUpdateReady = true;
          if (appUpdateCheck === 'downloading') appUpdateCheck = '';
          refreshUpdateBanner();
          renderAppUpdateSetting();
        }
        if (incoming.state === 'redundant' && appUpdateCheck === 'downloading') {
          appUpdateCheck = 'failed';   // inštalácia novej verzie zlyhala (napr. výpadok siete)
          renderAppUpdateSetting();
        }
      });
    });
  }).catch((err) => {
    // Bez service workera aplikácia funguje ďalej, ale tichý neúspech by sa ťažko hľadal.
    console.warn('GymQuest: service worker sa nepodarilo zaregistrovať:', err);
  });

  navigator.serviceWorker.addEventListener('controllerchange', () => {
    if (!swHasController) { swHasController = true; return; }   // prvá inštalácia – nič sa neobnovuje
    swUpdateReady = false;
    reloadForUpdate();
  });

  /* Appka z plochy (iPhone/Android) sa po návrate z pozadia neobnovuje, takže prehliadač
     sám novú verziu nehľadá – skontroluje sa pri každom návrate (najviac raz za minútu). */
  let swLastCheck = Date.now();
  document.addEventListener('visibilitychange', () => {
    if (document.hidden || !swRegistration || Date.now() - swLastCheck < 60000) return;
    swLastCheck = Date.now();
    swRegistration.update().catch(() => {});   // offline: skúsi sa pri ďalšom návrate
  });
}

/* ---------- Jedna aktívna karta ----------
   Každá karta drží vlastný stav v pamäti a vlastnú frontu synchronizácie, takže dve
   súčasne aktívne karty by si navzájom prepisovali uložené dáta. Preto aplikácia
   beží naraz len v JEDNEJ karte (Web Locks). Ďalšia karta je zablokovaná a ponúkne
   „Použiť tu“: aktívna karta dokončí bežiacu synchronizáciu, uloží stav, uvoľní
   zámok a sama sa zablokuje. Bez Web Locks (staré prehliadače) koordinácia chýba. */
const APP_LOCK = 'gymquest-app';
let appLockRelease = null;
let appYielded = false;
let appChannel = null;
let syncStartupPromise = null;

function tabText(key) {
  let lang = DEFAULT_LANG;
  try { const dev = JSON.parse(localStorage.getItem(DEVICE_SETTINGS_KEY) || 'null'); if (dev && dev.lang) lang = normalizeLang(dev.lang); } catch (e) {}
  return (I18N[lang] && I18N[lang][key]) || I18N.en[key] || key;
}
function appShowBlocked() {
  let el = document.getElementById('app-tab-block');
  if (!el) {
    el = document.createElement('div');
    el.id = 'app-tab-block';
    el.className = 'modal-backdrop';
    el.style.zIndex = '10000';
    el.style.background = 'var(--bg, #0f1115)';
    document.body.appendChild(el);
  }
  el.innerHTML = '<div class="modal"><h3>' + esc(tabText('sync.tabTitle')) + '</h3>'
    + '<p class="card-note">' + esc(tabText('sync.tabBody')) + '</p>'
    + '<div class="modal-actions"><button type="button" class="btn btn-primary" id="btn-tab-take">' + esc(tabText('sync.tabUseHere')) + '</button></div></div>';
  el.hidden = false;
  document.getElementById('btn-tab-take').addEventListener('click', appTakeOver);
}
/* „Použiť tu“: zaradí sa do fronty na zámok a požiada aktívnu kartu, aby ho uvoľnila. */
function appTakeOver() {
  const btn = document.getElementById('btn-tab-take');
  if (btn) { btn.disabled = true; btn.textContent = tabText('sync.tabWaiting'); }
  navigator.locks.request(APP_LOCK, () => new Promise((release) => {
    appLockRelease = release;
    const el = document.getElementById('app-tab-block');
    if (el) el.remove();
    appStart();
  }));
  try { appChannel.postMessage({ type: 'yield' }); } catch (e) {}
}
/* Táto karta odovzdáva aplikáciu inej: dokončí synchronizáciu, uloží a viac nezapisuje. */
async function appYield() {
  if (appYielded || !appLockRelease) return;
  await wearRevoke();
  await workoutPhaseCancelOwner(); stopTimer();
  await gqHook('tab:yield');
  await syncQuiesce();
  persistState();
  appYielded = true;                 // od tejto chvíle žiadne zápisy z tejto karty
  const release = appLockRelease;
  appLockRelease = null;
  release();
  location.reload();                 // znovu načítaná karta sa zobrazí ako zablokovaná
}
function appBoot() {
  try {
    appChannel = new BroadcastChannel('gymquest-tabs');
    appChannel.onmessage = (e) => { if (e.data && e.data.type === 'yield') appYield(); };
  } catch (e) { appChannel = null; }
  if (typeof navigator === 'undefined' || !navigator.locks || typeof navigator.locks.request !== 'function') { appStart(); return; }
  navigator.locks.request(APP_LOCK, { ifAvailable: true }, (lock) => {
    if (!lock) { appShowBlocked(); return undefined; }
    return new Promise((release) => { appLockRelease = release; appStart(); });
  });
}

/* ---------- Štart ---------- */
function appStart() {
  wsInit();        // aktívny pracovný priestor (účet / hosť) → jeho úložiská
  loadState();
  if (!getPlan(selectedPlan)) selectedPlan = activePlanIds()[0] || null;
  /* Obnovený rozbehnutý tréning: previažeme ho na jeho plán a dáme používateľovi vedieť. */
  const restoredSession = getSession();
  if (restoredSession && getPlan(restoredSession.planId)) {
    selectedPlan = restoredSession.planId;
  }
  setupEvents();
  applyStaticI18n();
  verifyI18n();
  switchTab('dnes');
  renderAll();
  /* Community (ak je zapnutá a účet prihlásený): odznaky a živé správy – neblokujúco. */
  communityBackgroundStart();
  /* Upozornenia na správy: ťuknutie na upozornenie otvorí chat (správa od service workera alebo ?chat=). */
  pushStartListening();
  const chatFromNotification = pushChatFromUrl();
  if (chatFromNotification) pushOpenChat(chatFromNotification);
  /* Vlastné médiá cvikov (IndexedDB) sa načítajú neblokujúco po prvom vykreslení. */
  initPersonalMedia();
  /* Fotky progresu (IndexedDB) – tiež neblokujúco. */
  initProgressPhotos();
  /* E-mailové odkazy (potvrdenie / obnova hesla) – fungujú aj pred zapnutím Community.
     Potom: obnova po prerušení, priradenie účtu a synchronizácia (spúšťače: štart,
     prihlásenie, lokálna zmena, online, návrat do popredia, každých 5 min). */
  syncStartupPromise = initAuthCallback().catch(() => {}).then(syncStartup);
  try {
    const notice = sessionStorage.getItem('gq_notice');
    if (notice) { sessionStorage.removeItem('gq_notice'); syncNotice = t(notice); }
  } catch (e) {}
  startDayWatcher();
  startDurationTicker();
  if (restoredSession) setSessionNote('trening.sessionRestored', 10000);
  restoreRestTimer();          // obnoví bežiaci (alebo už dobehnutý) odpočet z absolútneho konca
  refreshBackupOffer();        // a vyhodnotí, či od minule "dozrela" záloha
  scheduleCommunityInvite();   // kto Community nepoužíva, občas dostane pozvánku
  registerServiceWorker();
  nativeInit();                // Android appka: spúšťacia obrazovka, natívne udalosti
  workoutPhaseInit();
  if (state.history.length === 0 && !localStorage.getItem(STORAGE_KEY + '_seeded')) {
    openSetup();
  }
}
appBoot();
